INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(10173, 'plPL', 'Kostur arcymaga', 'Pozwól, że się przedstawię, $N.$B$BJestem Ravandwyr, uczeń arcymaga Vargotha.$B$BMój mistrz jest... powiedzmy, że niedysponowany. Przybyłem tu w sprawie wielkiej wagi.$B$BRuiny Arklon na południowy wschód od miasta to wylęgarnia działalności Płonącego Legionu. Co demony robią w ruinach, nie obchodzi ani mnie, ani mojego mistrza, ale ich przywódca, Ekkorash, ma kostur arcymaga.$B$BTen proszek przywołań pozwoli ci wywabić demona z kryjówki. Posyp nim kadzielnicę pośrodku ruin.', 'Odbierz kostur arcymaga Vargotha Ekkorashowi Inkwizytorowi i zanieś go Ravandwyrowi w Strefie 52. Aby wywabić Ekkorasha z kryjówki, posyp proszkiem przywołań kadzielnicę pośrodku ruin.', '', 'Wróć do Ravandwyra w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10174, 'plPL', 'Klątwa Purpurowej Wieży', 'Teraz będziesz $gmógł:mogła; użyć kostura arcymaga, by się z nim skontaktować.$B$BPrzebywa w Purpurowej Wieży, na „wyspie” na południowym wschodzie. Wieża, obłożona klątwą, jest dla niego zarówno schronieniem, jak i więzieniem. Członkowie Kirin Toru nie mogą ani do niej wejść, ani jej opuścić, więc nie mogę dotrzeć do mojego mistrza.$B$BMagia kostura przeniknie zabezpieczenia wieży, ale tylko jeśli przywoła ją ktoś spoza Kirin Toru.$B$BWeź kostur arcymaga i przywołaj nim jego wizerunek. Powiedz mu, co się stało, i że nie zawiodłem go całkowicie.', 'Użyj kostura arcymaga Vargotha, by nawiązać kontakt z arcymagiem Vargothem.$B$BJeśli zgubisz kostur arcymaga Vargotha, porozmawiaj z Ravandwyrem w Strefie 52, a dostaniesz nowy.', '', '', '', '', '', '', 0),
(10176, 'plPL', 'Ar\'kelos Strażnik', 'Skoro $gzebrałeś:zebrałaś; już wszystkie przedmioty potrzebne mi do złamania klątwy Kael\'thasa, zostało tylko jedno. Zapieczętowawszy wieżę, Kael\'thas umieścił u jej podstawy tajemnego golema zwanego Ar\'kelosem.$B$BMusisz pokonać Ar\'kelosa, abym znów mógł władać magią w wieży.$B$BGdy wejdziesz do Purpurowej Wieży, klątwa zacznie na ciebie działać.$B$BKiedy pokonasz Ar\'kelosa, wejdź na szczyt wieży i pomóż mi w przygotowaniach do rytuału.', 'Wejdź do Purpurowej Wieży w centrum Wioski Kirin\'Var, pokonaj Ar\'kelosa, a potem porozmawiaj z arcymagiem Vargothem.', '', 'Porozmawiaj z arcymagiem Vargothem – osobiście – w Purpurowej Wieży w Burzy Otchłani.', '', '', '', '', 0),
(10179, 'plPL', 'Kustosz Kirin\'Var', 'Gdy stało się jasne, że nasza ekspedycja utknęła w Rubieży bez możliwości powrotu do Azeroth, oddział Kirin Toru udał się na Równiny Farahlonu i zbudował Wioskę Kirin\'Var. Zarząd nad osadą powierzyłem kustoszowi Dieworthowi, ale gdy Kael\'thas i jego siły zamknęli mnie w Purpurowej Wieży, straciłem z nim kontakt.$B$BPoszukaj go w Wiosce Kirin\'Var i pomóż mu, jak tylko zdołasz, $N. Jestem pewien, że po ataku ma pełne ręce roboty.', 'Porozmawiaj z kustoszem Dieworthem w Wiosce Kirin\'Var w Burzy Otchłani.', '', '', '', '', '', '', 0),
(10182, 'plPL', 'Mag bojowy Dathric', 'Miecz jest wyjątkowej jakości, starannie wykonany i doskonale wyważony dla maga bojowego. Na głowicy wygrawerowano pieczęć Kirin Toru i imię „Dathric”.$B$BObracając broń w dłoniach, wyczuwasz, że bije od metalu coś niewłaściwego, jakby przedmiot był rozdarty między dwoma światami. Czy to on wiąże ducha maga bojowego Dathrica z tym światem?$B$BByć może odłożenie go na właściwe miejsce zerwie tę więź i pozwoli duchowi Dathrica wreszcie spocząć.', 'Odszukaj kwaterę maga bojowego Dathrica w Alei Czarodziejów i odłóż ostrze na jego stojak na broń. Potem porozmawiaj z kustoszem Dieworthem w Wiosce Kirin\'Var.', '', 'Wróć do kustosza Diewortha w Wiosce Kirin\'Var w Burzy Otchłani.', '', 'Ukój ducha Dathrica', '', '', 0),
(10183, 'plPL', 'Do Strefy 52', 'Badam tu Otchłań – eteryczne prądy i tak dalej. To idealne miejsce, z dala od świateł i zgiełku miasta. Czy ten most nie jest wspaniały? Gdybym tylko umiał utrzymać ten złom na chodzie.$B$BHej, wiesz co, jeśli szukasz pracy, w Strefie 52 jest jej mnóstwo! To kawałek w górę ścieżki, na rozwidleniu w prawo.$B$BMoże zaniesiesz moje najnowsze notatki badawcze Rakietowodzowi Kadłubkowi? Na pewno znajdzie dla ciebie mnóstwo roboty, zwłaszcza teraz, przy tym statku rakietowym X-52 i w ogóle!', 'Zanieś notatki otchłanologa Rakietowodzowi Kadłubkowi w Strefie 52 w Burzy Otchłani.', '', '', '', '', '', '', 0),
(10184, 'plPL', 'Złowrogie pozostałości', 'Większość duchów w wiosce to niewiele więcej niż blade cienie magów Kirin Toru. Nie pamiętają, kim byli, i błąkają się po ruinach w ślepym gniewie.$B$BNie zawsze tak jednak było. Tuż po ataku duchy były niespokojne, ale nie złośliwe. Z czasem stawały się tylko coraz bardziej agresywne. Nie odważę się zapuścić w południową część wioski, bo nie oszczędzą nawet mnie. Ucisz je i miejmy nadzieję, że to ukoi ich gniew.', 'Kustosz Dieworth z Wioski Kirin\'Var chce, żebyś $gpokonał:pokonała; 20 odciętych duchów na Rynku Kirin\'Var.', '', 'Wróć do kustosza Diewortha w Wiosce Kirin\'Var w Burzy Otchłani.', '', '', '', '', 0),
(10185, 'plPL', 'Los gorszy od śmierci', 'Kiedy krwawe elfy zrównały Wioskę Kirin\'Var z ziemią, zaczęły budowę dużego gmachu na północnym zachodzie. Bez wiedzy arcymaga nie możemy powiedzieć na pewno, co się tam dzieje.$B$BJedno jest jednak jasne. Działania krwawych elfów ściągnęły na wioskę falę wygłodniałych żywiołaków many. Zdają się lgnąć do ruin Alei Czarodziejów i sieją tam dalsze zniszczenie. Nie możemy na to pozwolić.', 'Zabij 10 pogromców magów i 10 poszukiwaczy many, a potem wróć do kustosza Diewortha w Wiosce Kirin\'Var.', '', 'Wróć do kustosza Diewortha w Wiosce Kirin\'Var w Burzy Otchłani.', '', '', '', '', 0),
(10186, 'plPL', 'Masz tę robotę!', 'Pozwól, że jako pierwszy powitam cię na pokładzie, $gmłodszy techniku:młodsza techniczko; 3. stopnia $N!$B$BBudujemy tu moje arcydzieło – Rakietę Otchłani X-52!$B$BAle najpierw musimy zdobyć wszystkie części i paliwo. I tu wkraczasz ty.$B$BNa początek potrzebuję kryształów – MNÓSTWA kryształów – do eterolitowej matrycy silnika rakiety. Draenei mieli kryształów od groma!$B$BRuszaj więc na północ, do Ruin Enkaat, i przynieś mi je! Nie przejmuj się duchami draenei.', 'Zbierz 10 kryształów matrycy z eterolitu i zanieś je Rakietowodzowi Kadłubkowi w Strefie 52 w Burzy Otchłani.', '', 'Wróć do Rakietowodza Kadłubka w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10187, 'plPL', 'Wiadomość dla arcymaga', 'Choć sytuacja jest tu ponura, bardzo podniosła nas na duchu wieść od ciebie, że arcymag nie zapomniał o niedoli wioski.$B$B<Kustosz zerka na wieżę.>$B$BTo absurdalne, prawda? Czasem wydaje się, że dzieli nas tylko zwykła kamienna ściana. O ścianie z magii łatwo zapomnieć.$B$BJeśli możesz, wejdź na szczyt wieży i przekaż arcymagowi Vargothowi, że robimy postępy w wiosce i wkrótce będziemy mieć plan, jak odeprzeć istoty many.', 'Porozmawiaj z arcymagiem Vargothem na szczycie Purpurowej Wieży w Burzy Otchłani.', '', '', '', '', '', '', 0),
(10188, 'plPL', 'Symbol Krasusa', 'Zanim przed laty opuściliśmy Azeroth, Kirin Tor powierzył naszej ekspedycji potężny artefakt – Symbol Krasusa. Bardzo nam pomógł w walce z orkami i może odegrać kluczową rolę w złamaniu zaklęcia, które mnie więzi.$B$BGdy jednak Kael\'thas odebrał mi moje rzeczy, oddał symbol zaklinaczce Maryanie, która została z garnizonem. Gdyby naprawdę rozumiał, co ma w rękach, nie oddałby go tak łatwo.', 'Odbierz Symbol Krasusa zaklinaczce Maryanie w Kuźni Many Coruu, na północny zachód od Purpurowej Wieży.', '', 'Użyj kostura arcymaga Vargotha, by wyświetlić wizerunek arcymaga Vargotha, i powiadom go o swoich postępach.$B$BJeśli zgubisz kostur arcymaga Vargotha, porozmawiaj z Ravandwyrem w Strefie 52, a dostaniesz nowy.', '', '', '', '', 0),
(10189, 'plPL', 'Kuźnia Many B\'naar', 'Być może po drodze $gzauważyłeś:zauważyłaś; jedną z kuźni many Kaela. Wiesz, te wielkie fioletowe budowle, które wysysają energię z nieba?$B$BSha\'tar przysłali nas tu, byśmy je zbadali. Możesz pomóc nam w zbieraniu informacji, zdobywając listę personelu. Wiedza o tym, kto tam jest i czym się zajmuje, okaże się bezcenna.$B$BSądzimy, że taką listę ma kapitan Arathyn, który dowodzi obsługą balisty tuż pod Kuźnią Many B\'naar. Zdobądź ją dla nas.', 'Mistrz szpiegów Thalodien ze Strefy 52 chce, żebyś $gudał:udała; się na obrzeża Kuźni Many B\'naar i $godebrał:odebrała; kapitanowi Arathynowi listę personelu B\'naar.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do mistrza szpiegów Thalodiena w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10190, 'plPL', 'Ładowanie baterii', 'Mam bardzo ważne zadanie: zebrać maszynerię z tych ruin, ale nie nadążam z ładowaniem wszystkich moich botów.$B$BŁowcy fazowi – te stwory przypominające wyrmy – mają mnóstwo energii! Znajdziesz ich wszędzie na skrajach tej wyspy, wpływają tu z Otchłani.$B$BNapełnij baterię tego blastera ładującego: użyj go na łowcy fazowym, gdy będzie bardzo osłabiony, a potem go dobij, by wchłonąć resztę jego energii.', 'Używaj blastera ładującego baterie na łowcach fazowych, aż poziom naładowania baterii wyniesie 10. Potem zanieś go specjalistce od botów Alley w Ruinach Enkaat w Burzy Otchłani.', '', 'Wróć do specjalistki od botów Alley w Ruinach Enkaat w Burzy Otchłani.', 'Poziom naładowania baterii', '', '', '', 0),
(10191, 'plPL', 'Mark V żyje!', 'Pozdrowienia, istoto. Jestem naładowany i w pełni sprawny.$B$BW tych ruinach są delikatne maszyny draenei, które muszę odzyskać. Mam precyzyjne serwa w siłownikach nadgarstków i najnowsze spalinowo-pneumatyczne amortyzatory wstrząsów. Ostrożne obchodzenie się z nimi nie będzie problemem.$B$BJednak duchy nawiedzające te ruiny najpewniej zaatakują, więc potrzebuję ochrony – twojej i twoich przyjaciół.', 'Eskortuj Maxxa A. Milliona Mk. V przez Ruiny Enkaat i z powrotem w bezpieczne miejsce. Potem porozmawiaj ze specjalistką od botów Alley tuż przy Ruinach Enkaat w Burzy Otchłani.', 'Bezpiecznie przeprowadź Maxxa A. Milliona Mk. V przez Ruiny Enkaat', 'Wróć do specjalistki od botów Alley w Ruinach Enkaat w Burzy Otchłani.', '', '', '', '', 0),
(10192, 'plPL', 'Kompendium Krasusa', 'Kirin Tor wysłał z naszą ekspedycją jeszcze jedną rzecz należącą do Krasusa. Była to jego księga zaklęć, zwana Kompendium Krasusa. Zawierała wszystkie zaklęcia, które opanował, i dała nam w wojnie bardzo potrzebną przewagę.$B$BZanim Kael\'thas i jego siły obległy Kirin\'Var, kompendium ukradł mi zbuntowany uczeń, który chciał zgłębiać nekromancję. Uczeń i jego zwolennicy podzielili tekst między siebie i studiowali go w tajemnicy, zamknąwszy się w swoich domach w południowej części miasta.', 'Odzyskaj Kompendium Krasusa – rozdział 1, Kompendium Krasusa – rozdział 2 i Kompendium Krasusa – rozdział 3 z Rynku Wioski Kirin\'Var.', '', 'Użyj kostura arcymaga Vargotha, by skontaktować się z arcymagiem.$B$BJeśli zgubisz kostur arcymaga Vargotha, porozmawiaj z Ravandwyrem w Strefie 52, a dostaniesz nowy.', '', '', '', '', 0),
(10193, 'plPL', 'Cenne cele', 'Z listy personelu wiemy, że mózgami operacji w kuźniach many są mistrzowie wypaczenia i inżynierowie wypaczenia. To oni nadzorują pozyskiwanie przez kuźnię many tak zwanej „energii wypaczenia” i przesyłanie jej w odległe miejsce systemem podziemnych rur.$B$BJedyni inni specjaliści w okolicy to geolodzy. Cała reszta to albo żołnierze, albo kumple magistrów; jednych i drugich łatwo zastąpić.$B$BIdź tam i zabij specjalistów Kaela; to go najbardziej zaboli.', 'Mistrz szpiegów Thalodien ze Strefy 52 chce, żebyś $gudał:udała; się do Kuźni Many B\'naar i $gzabił:zabiła; 2 mistrzynie wypaczenia Słonecznej Furii, 6 inżynierów wypaczenia Słonecznej Furii i 8 geologów Słonecznej Furii.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do mistrza szpiegów Thalodiena w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10194, 'plPL', 'Ukryty lot', 'Podczas twojej nieobecności moi ludzie odkryli kolejną kuźnię many. Leży na wschód stąd i nazywa się Kuźnia Many Coruu.$B$BDwoje moich najlepszych szpiegów przygotowało tajne lądowisko pod kuźnią many. Masz im pomóc przeniknąć do sił Kaela i zdobyć wszelkie informacje, jakie się da.$B$BPorozmawiaj z Veronią tuż za murami miasta; załatwiła wiwernę, która zabierze cię do Kuźni Many Coruu. Na miejscu porozmawiaj z Caledisem Jasnoświtem; wprowadzi cię w szczegóły misji.', 'Porozmawiaj z Veronią pod Strefą 52 i poleć do Kuźni Many Coruu.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', '', '', '', '', '', 0),
(10197, 'plPL', 'Przekonujące przebranie', 'Przeniknięcie w szeregi armii Kaela nie będzie łatwe. Dzięki znajomości magii iluzji mógłbym upodobnić cię do jednego z popleczników Kaela, ale pewnych szczegółów ich mundurów nie zdołam odtworzyć.$B$BPrzynieś mi komplet ich szat, parę ich rękawic i medalion gwardzisty Słonecznej Furii. Dzięki temu efekt mojej magii będzie znacznie bardziej przekonujący.', 'Zdobądź szaty arkanisty Słonecznej Furii, parę rękawic badacza Słonecznej Furii i medalion gwardzisty Słonecznej Furii, a potem zanieś je Caledisowi Jasnoświtowi w Kuźni Many Coruu w Burzy Otchłani.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do Caledisa Jasnoświta w Kuźni Many Coruu w Burzy Otchłani.', '', '', '', '', 0),
(10198, 'plPL', 'Zbieranie informacji', 'Przygotowałem mundur z części, które $gzdobyłeś:zdobyłaś;. Jest magicznie wzmocniony, by dopełnić iluzji.$B$BKilka minut temu widzieliśmy, jak dowódca Świtokuj wchodzi na spotkanie z arkanistą Ardonisem. Miał ze sobą pełną świtę strażników, więc cokolwiek omawiają, musi być niezwykle ważne; spróbuj coś podsłuchać.$B$BAch, prawie zapomniałem. Trzymaj się z dala od tajemnych golemów patrolujących kuźnię many. Przejrzą iluzję na wylot.', 'Użyj przebrania Słonecznej Furii, wejdź do Kuźni Many Coruu i podsłuchaj rozmowę dowódcy Świtokuja z arkanistą Ardonisem. Potem zdaj raport Caledisowi Jasnoświtowi w Kuźni Many Coruu.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', 'Zbieranie informacji', '', '', '', '', '', 0),
(10199, 'plPL', 'Mały dodatkowy kop', 'Brakuje mi tylko jednego składnika, który da mojej miksturze ten mały dodatkowy kop, jakiego jej trzeba.$B$BŻądło płaszczek Otchłani, które krążą w pobliżu łupkoskórych obdzieraczy, ma nie lada siłę. Przynieś mi trochę ich żądeł, a wyciągnę z nich jad!$B$BJestem pewien, że wynik będzie wybuchowy!', 'Zdobądź 5 żądeł płaszczek Otchłani dla Bootsa w Strefie 52 w Burzy Otchłani.', '', 'Wróć do Bootsa w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10200, 'plPL', 'Powrót do Thalodiena', 'Najlepiej będzie, jeśli te informacje jak najszybciej trafią do Thalodiena. Zostanę tu i zatrę nasze ślady.$B$BNie wyszłoby nam na dobre, gdyby Kael\'thas się dowiedział, co tu węszyliśmy. Tajne informacje są zawsze cenniejsze, jeśli wróg nie wie, że je masz.', 'Wróć do mistrza szpiegów Thalodiena w Strefie 52 w Burzy Otchłani.', '', '', '', '', '', '', 0),
(10202, 'plPL', 'Dezerter', 'Niedawno skontaktował się z nami magister Słonecznej Furii, który chce przejść na naszą stronę i przysięga, że ma potrzebne nam informacje. Sprawdziliśmy u naszych informatorów, czy nie jest podwójnym agentem, i wszystko się zgadza.$B$BStacjonuje w Kuźni Many Ara, co utrudnia komunikację. Porozmawiaj z nim i dowiedz się, co wie. Jeśli jest choć w połowie tak przydatny, jak twierdzi, znajdziemy dla niego dobre zastosowanie.', 'Udaj się do Kuźni Many Ara i porozmawiaj z magistrem Theledornem.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', '', '', '', '', '', 0),
(10203, 'plPL', 'Porażanie bezcennego mienia', 'Widzisz szczelinę biegnącą przez Strefę 52? To nasza robota! <szczerzy zęby>$B$BWydobywamy z niej przeróżne cudeńka dla Rakiety Otchłani X-52, ale zaczyna nam brakować sprzętu.$B$BProwadziliśmy prace w Ruinach Arklon na południowym wschodzie, dopóki nie wprowadził się tam Płonący Legion. Zabierz do ruin ten ultradekonsolidujący poraziciel. Użyj go, by przesłać nasz sprzęt z powrotem do głównego sapera Wybuchopsyka na dnie szczeliny.$B$B$GMłodszy techniku:Młodsza techniczko; 3. stopnia $N, to twoja szansa na awans. Tylko jej nie wysadź w powietrze!', 'Użyj ultradekonsolidującego poraziciela, by przesłać do Strefy 52 hiperobrotowy kopomat, serwopneumatyczny pazur pogłębiarki, wielospektralny analizator terenu i wielki wóz pełen materiałów wybuchowych. Potem zgłoś się do głównego sapera Wybuchopsyka we wschodnim końcu szczeliny biegnącej przez Strefę 52 w Burzy Otchłani.', '', 'Wróć do głównego sapera Wybuchopsyka w Strefie 52 w Burzy Otchłani.', 'Hiperobrotowy kopomat odzyskany', 'Serwopneumatyczny pazur pogłębiarki odzyskany', 'Wielospektralny analizator terenu odzyskany', 'Wielki wóz pełen materiałów wybuchowych odzyskany', 0),
(10204, 'plPL', 'Kryształy krwawego klejnotu', 'Magistrowie Kaela tak udoskonalili korzystanie z kryształów many, że w kilka sekund potrafią wyssać ogromne ilości energii.$B$BRobią to, dostrajając mniejsze odłamki kryształów krwawego klejnotu do większych, w pełni naładowanych.$B$BUdaj się do Kuźni Many B\'naar, zdobądź taki odłamek od magistra Słonecznej Furii i użyj go, by wyssać energię z jednego z większych kryształów.$B$BWróć do mnie, abym mogła zbadać działanie tej aury. Nie martw się; ewentualne skutki uboczne powinny być przejściowe.', 'Magistrix Larynna chce, żebyś $gudał:udała; się do Kuźni Many B\'naar i $gzdobył:zdobyła; odłamek krwawego klejnotu od magistra Słonecznej Furii. Użyj odłamka w pobliżu większych kryształów krwawego klejnotu i wróć do niej do Strefy 52.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', 'Wyssij energię z kryształu krwawego klejnotu', 'Wróć do magistrix Larynny w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10205, 'plPL', 'Najeźdźca wypaczenia Nesaad', 'Trzeba się rozprawić z najeźdźcą wypaczenia Nesaadem! Nie mam pojęcia, jak przeżył mój atak, ale nie można mu pozwolić dalej prowadzić tam swoich interesów.$B$BWróć tam i zlikwiduj Nesaada. Ma mały eteryczny obóz przy południowo-zachodnim krańcu Hałdy.$B$BNie zawiedź tak jak ja, $N.', 'Zabij najeźdźcę wypaczenia Nesaada, a potem wróć do tropiciela Otchłani Khay\'jiego w Strefie 52 w Burzy Otchłani.', '', 'Wróć do tropiciela Otchłani Khay\'jiego w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10206, 'plPL', 'Części do wzięcia', 'Ci eteryczni błaźni są tak samo wyrachowani jak my, to im przyznam. Ale nikt, i mówię NIKT, nie wchodzi na działkę B.U.M.!$B$BHałda na południu jest nasza!$B$BJeśli mamy skończyć Rakietę Otchłani X-52, będziemy potrzebować każdej nowej techniki, jaką zdołamy dorwać. A skoro eterycy nas okradają, to chyba sprawiedliwie, żebyśmy odpłacili im tym samym.$B$BMoże pójdziesz tam i spróbujesz podwędzić im trochę technologii sprzed nosa!', 'Zbierz 10 elementów eterycznej technologii i zanieś je Papie Wheelerowi w Strefie 52 w Burzy Otchłani.', '', 'Wróć do Papy Wheelera w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10209, 'plPL', 'Zdobycz przywoływacza Kanthina', 'Następnie musimy odzyskać mojego chowańca, Glaciusa, z rąk przywoływacza krwawych elfów, który go więzi. Przywoływacz Kanthin był jednym z najstarszych rangą magistrów w oddziałach, które Kael\'thas wysłał, by zdziesiątkować Kirin\'Var. Nic dziwnego, że zagarnął mojego chowańca jako swego rodzaju trofeum.$B$BJestem pewien, że Kanthin, głupiec, próbował zmusić Glaciusa do służby. Moje jasnowidzenie wykazało, że Kanthin stacjonuje teraz w „Kuźni Many Duro”, jeśli ta nazwa coś ci mówi.', 'Pokonaj przywoływacza Kanthina w Kuźni Many Duro, na wyspie na północ od Warowni Słonecznej Furii, i odbierz mu Kamień Glaciusa.', '', 'Użyj kostura arcymaga Vargotha, by skontaktować się z arcymagiem.$B$BJeśli zgubisz kostur arcymaga Vargotha, porozmawiaj z Ravandwyrem w Strefie 52, a dostaniesz nowy.', '', '', '', '', 0),
(10221, 'plPL', 'Doktor Huk!', '$N, mój dawny podopieczny, Sparky Superdysza, nie chciał nosić tu na dole hełmu i pewnego dnia zmienił się w osławionego Doktora Huka!$B$BI uciekł na północny wschód z większością naszego sprzętu saperskiego! Od tamtej pory on i jego hukoboty są zmorą Strefy 52.$B$BIdź do jego Obozu Bum tuż za miastem i skończ z nim! Załatw go tymi bombami „Zguba Huka”.$B$BI uważaj, żeby nie podchodzić za blisko ani do niego, ani do jego hukobotów!', 'Zabij Doktora Huka i wróć z dobrą wieścią do głównego sapera Wybuchopsyka w Strefie 52 w Burzy Otchłani.', '', 'Wróć do głównego sapera Wybuchopsyka w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10222, 'plPL', 'Garnizon Słonecznej Furii', 'Kiedy siły księcia Kael\'thasa zniszczyły wioskę i uwięziły arcymaga w Purpurowej Wieży, wycofały się do Warowni Słonecznej Furii na północnym wschodzie. Ci sami ludzie, którzy zniszczyli naszą wioskę i wymordowali naszych towarzyszy, wznoszą toasty za swoje „wspaniałe zwycięstwo”, a my nie jesteśmy w stanie pomścić poległych.$B$BNie możemy pozwolić, by te zbrodnie pozostały bez odpowiedzi! Bądź narzędziem naszej zemsty, $N. Idź do Warowni Słonecznej Furii i odbierz życie tym, którzy odpowiadają za tę zbrodnię.', 'Kustosz Dieworth z Wioski Kirin\'Var chce, żebyś $gzabił:zabiła; 10 łuczników Słonecznej Furii.', '', 'Wróć do kustosza Diewortha w Wiosce Kirin\'Var w Burzy Otchłani.', '', '', '', '', 0),
(10223, 'plPL', 'Precz z Daellisem', 'Nigdy nie zapomnę krwawego elfa, który prowadził atak. Na szkarłatnej zbroi nosił tabard z godłem, jakiego nigdy wcześniej nie widziałem.$B$BBył zaciekły i bezlitosny, prowadził z pierwszej linii, gdzie większości innych oficerów krwawych elfów nigdy się nie widuje. Tamtego dnia odpowiadał za śmierć wielu magów Kirin Toru, ale nie zabawił długo w Warowni Słonecznej Furii. Kael\'thas wysłał go do Kuźni Many Duro, by pomógł w próbie opanowania okolicy. Znajdź go, $N, i ucisz jego łuk na dobre.', 'Kustosz Dieworth z Wioski Kirin\'Var chce, żebyś $gzabił:zabiła; mistrza Daellisa Świtoboja.', '', 'Wróć do kustosza Diewortha w Wiosce Kirin\'Var w Burzy Otchłani.', '', '', '', '', 0),
(10224, 'plPL', 'Esencja dla silników', 'Jako szef działu inżynierii X-52 muszę dopilnować, by główne silniki rakiety były w doskonałym stanie.$B$BNiestety, jeszcze ich nie zbudowałem.$B$BJestem w tarapatach! Mam prawie wszystkie części. Brakuje mi tylko rdzenia silnika.$B$BNa szczęście chyba możemy wykorzystać esencję miejscowych upiorów many, by odpalić silniki.$B$BZnajdziesz je w pobliżu większości świecących rowów w północnej części wyspy. Oczywiście poza tym tutaj, w Strefie 52.', 'Zbierz 7 esencji upiorów many i zanieś je głównemu inżynierowi Trepowi w Strefie 52 w Burzy Otchłani.', '', 'Wróć do głównego inżyniera Trepa w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10225, 'plPL', 'Zgłoś się do działu inżynierii', '$N! Zanieś wszystkie te kryształy z eterolitu głównemu inżynierowi Trepowi, mojemu, eee, szefowi działu inżynierii.$B$BPowinien wiedzieć, co z nimi zrobić. A jeśli nie wie, dopilnuj, żeby się dowiedział!', 'Zanieś kryształy matrycy z eterolitu głównemu inżynierowi Trepowi w Strefie 52 w Burzy Otchłani.', '', '', '', '', '', '', 0),
(10226, 'plPL', 'Pozyskiwanie mocy żywiołów', 'Kurczę, to nie zadziałało!$B$BDobra, mam inny pomysł! Poprosiłem Xyrola, żeby sklecił ekstraktor mocy żywiołów. Nie wiem dokładnie, co ta moc zrobi, ale wiem, że mogę ją wykorzystać.$B$BRozdarte dudniacze i aberracje wypaczenia na krawędzi Kruszącego się Pustkowia na południu mają dokładnie to, czego potrzebuję do silników!$B$BEkstraktor przemieni ich moc w coś stałego, co zbierzesz, kiedy je pokonasz.', 'Pozyskaj 5 porcji mocy żywiołów dla głównego inżyniera Trepa w Strefie 52 w Burzy Otchłani.', '', 'Wróć do głównego inżyniera Trepa w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10232, 'plPL', 'Bójka o złom z Legionem', 'Płonący Legion wszedł na naszą działkę na Polu Złomu, w dół ścieżki i za mostem na wschodzie.$B$BTo może być dla nas ogromny problem! Z Legionem w Ruinach Arklon, a teraz jeszcze tam, sytuacja zaczyna źle wyglądać dla nas – i dla projektu rakiety – tu, w Strefie 52.$B$B$N, musisz tam iść i rozprawić się z tymi demonami! Zrobiłbym to sam, ale jestem kochankiem, nie wojownikiem.$B$BTak, będą z tego kłopoty, czuję to!', 'Zabij 5 mo\'argów kowali zagłady i 15 gan\'argów inżynierów. Potem wróć do Papy Wheelera w Strefie 52 w Burzy Otchłani.', '', 'Wróć do Papy Wheelera w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10233, 'plPL', 'Podpalenie Warowni Słonecznej Furii', 'Wybicie garnizonu Warowni Słonecznej Furii nie wystarczy, by powstrzymać krwawe elfy przed ponownym jej zajęciem. Poplecznicy Kael\'thasa są gorliwi i uparci. Zostawienie im w warowni czegokolwiek, co mogłoby się przydać, to w praktyce zaproszenie do powrotu.$B$BNie, wszystko musi zostać zniszczone. Dopilnuj, by ich namioty i artyleria spłonęły na popiół!$B$B<Duch zaciska pięści.>$B$BDo tego zadania ukradnij pochodnie strażnikom płomienia Słonecznej Furii, $N.', 'Za pomocą płonącej pochodni zniszcz 4 balisty Słonecznej Furii i 4 namioty Słonecznej Furii, a potem wróć do porucznika-czarownika Morrana w Wiosce Kirin\'Var.', '', 'Wróć do porucznika-czarownika Morrana w Wiosce Kirin\'Var w Burzy Otchłani.', 'Balista Słonecznej Furii zniszczona', 'Namiot Słonecznej Furii zniszczony', '', '', 0),
(10234, 'plPL', 'Co dla demona śmieciem...', 'Wyglądasz na $gzdolnego młodzieńca:zdolną młodą kobietę;! Może $gpomógłbyś:pomogłabyś; mi?$B$BNa wschodzie jest Pole Złomu, gdzie wprowadził się Płonący Legion. Pełno tam ogromnych części Grabieżców Spaczenia. Jest tam też cała masa mniejszych części, na których demonom chyba nie zależy.$B$BChcę, żebyś tam $gposzedł:poszła; i $gprzyniósł:przyniosła; mi mnóstwo tych mniejszych części Grabieżców Spaczenia!', 'Zbierz 10 części Grabieżcy Spaczenia i zanieś je Mamie Wheeler w Posterunku Środka w Ekokopule Środka w Burzy Otchłani.', '', 'Wróć do Mamy Wheeler w Ekokopule Środka w Burzy Otchłani.', '', '', '', '', 0),
(10235, 'plPL', 'Szpon Zagłady bez szponów', 'Wiesz, co mogłoby ich zniechęcić? Załatwienie ich przywódcy!$B$BZ tego, co słyszałam, wszędzie indziej to działa. A kiedy zobaczą, jak ktoś tak $gzaprawiony w bojach:twardy; jak ty załatwia ich przywódcę... założę się, że podkulą ogony i uciekną w góry!$B$BWracaj tam i załatw tego wielkiego, którego nazywają Szponem Zagłady. Podobno przesiaduje we wschodniej części Pola Złomu, pod rurą.$B$BPrzynieś mi też jego szpon! Może się do czegoś przyda.', 'Zdobądź dłoń Szponu Zagłady i zanieś ją Mamie Wheeler w Posterunku Środka w Ekokopule Środka w Burzy Otchłani.', '', 'Wróć do Mamy Wheeler w Ekokopule Środka w Burzy Otchłani.', '', '', '', '', 0),
(10237, 'plPL', 'Ostrzeż Strefę 52!', '$N, musisz natychmiast przekazać wieści do Strefy 52! Pospiesz się!$B$BPowiedz rakietowodzowi, że Płonący Legion idzie teraz na nas!', 'Przekaż złe wieści Rakietowodzowi Kadłubkowi w Strefie 52 w Burzy Otchłani.', '', '', '', '', '', '', 0),
(10239, 'plPL', 'Potencjalne źródło energii', 'Nie tylko my walczymy z napływem istot many. Krwawe elfy też mają z nimi kłopot, choć nie wiem dlaczego.$B$BCzymkolwiek się tam zajmują, nie zamierzają przestać. Widziałem za to, jak stosują różne metody zabijania tych stworzeń. Najskuteczniejsze są magiczne osłony zasilane jakąś skoncentrowaną energią.$B$BZdobądź trochę tych źródeł energii i przynieś mi je. Nie wahaj się pokrzyżować elfom planów, jeśli nadarzy się okazja.', 'Porucznik-czarownik Morran z Wioski Kirin\'Var chce, żebyś $gzdobył:zdobyła; 10 kostek izolacji energii z instalacji krwawych elfów w Kuźni Many Coruu.', '', 'Wróć do porucznika-czarownika Morrana w Wiosce Kirin\'Var w Burzy Otchłani.', '', '', '', '', 0),
(10240, 'plPL', 'Pierścień ochronny', 'Jesteśmy gotowi spróbować otoczyć wioskę pierścieniem ochronnym, wykorzystując źródło energii odebrane krwawym elfom. Nie mogę zagwarantować, że się uda, ale musimy spróbować.$B$BInaczej istoty many na pewno będą dalej pożerać duchy poległych magów Kirin Toru.$B$BUżyj tego urządzenia przy małych runach na obrzeżach miasta, by uwolnić tam energię. Jeśli dobrze utkałem pole, powinniśmy zauważyć różnicę, gdy użyjesz urządzenia w każdym punkcie.', 'Użyj urządzenia aktywującego runy w pobliżu wschodniej runy, północno-wschodniej runy i zachodniej runy. Runy znajdziesz na obrzeżach dwóch dzielnic Wioski Kirin\'Var: Alei Czarodziejów i Rynku. Po wykonaniu zadania wróć do porucznika-czarownika Morrana.', '', 'Wróć do porucznika-czarownika Morrana w Wiosce Kirin\'Var w Burzy Otchłani.', 'Aktywuj wschodnią runę', 'Aktywuj północno-wschodnią runę', 'Aktywuj zachodnią runę', '', 0),
(10241, 'plPL', 'Dywersja w Kuźni Many B\'naar', 'Sha\'tar przysłali nas tu, byśmy zbadali kuźnie many, które prowadzi tu armia Kael\'thasa. Niestety Widzący grożą, że wycofają się ze zbierania informacji, jeśli nie wesprzemy ich działaniami zbrojnymi.$B$BNie możemy narażać tej misji z powodu polityki, więc zgodziliśmy się osłabić obronę kuźni many, by Widzący mogli wykonać swoją pracę.$B$BDowiedź swojej lojalności wobec Aldorów i zabij magistrów i krwawych stróżów Słonecznej Furii, którzy strzegą Kuźni Many B\'naar.', 'Zabij 8 magistrów Słonecznej Furii i 8 krwawych stróżów Słonecznej Furii, a potem wróć do egzarchy Orelisa w Strefie 52.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do egzarchy Orelisa w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10243, 'plPL', 'Technologia naaru', 'Widzący zdobyli listę personelu Kuźni Many B\'naar i teraz mają używanie, wybierając cele zamachów.$B$BPrzeoczyli jedną drobną informację, nabazgraną na marginesie listy. Wyglądała na hasło lub kod, takie jak te, którymi uzyskuje się dostęp do technologii naaru, na przykład Exodaru czy Twierdzy Burz.$B$BWejdź do kuźni many i poszukaj panelu sterowania. Przepisz jak najdokładniej jego odczyty na ten zwój. Musimy potwierdzić nasze podejrzenia co do pochodzenia tej technologii.', 'Wejdź do Kuźni Many B\'naar i znajdź konsolę sterującą B\'naar.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', '', '', '', '', '', 0),
(10244, 'plPL', 'P.I.B.G.S.', 'Po złamaniu pieczęci na tej dość pokaźnej księdze nie potrafisz odczytać słów. Wyglądają na zapisane w języku demonów.$B$BRozumiesz jednak rysunki, które opowiadają własną historię.$B$BTo z pewnością instrukcja budowy Grabieżcy Spaczenia i wiesz na pewno, że Mama Wheeler zechce się jej przyjrzeć!', 'Zanieś instrukcję budowy Grabieżcy Spaczenia Mamie Wheeler w Posterunku Środka w Ekokopule Środka w Burzy Otchłani.', '', '', '', '', '', '', 0),
(10245, 'plPL', 'Zapis z konsoli B\'naar', 'Próbujesz przepisać kształty migające ci przed oczami. Wynik jest daleki od dokładności, ale powinien wystarczyć jako dowód, który potwierdzi lub obali podejrzenia Aldorów.', 'Zanieś zapis z konsoli B\'naar anachoretce Karji w Strefie 52 w Burzy Otchłani.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', '', '', '', '', '', 0),
(10246, 'plPL', 'Atak na Kuźnię Many Coruu', 'Twój sukces w Kuźni Many B\'naar był godny uwagi. Jestem pewien, że anachoretka Karja poprosi cię teraz o powtórkę w Kuźni Many Coruu.$B$BDowiedzieliśmy się, że trafia tam szczególnie ważny oddział arkanistów i badaczy Słonecznej Furii, i chciałbym, żebyś się nimi $gzajął:zajęła;. Jeśli ci się uda, zadasz siłom wroga miażdżący cios.', 'Udaj się do Kuźni Many Coruu i zabij 8 arkanistów Słonecznej Furii i 5 badaczy Słonecznej Furii. Po wykonaniu zadania wróć do egzarchy Orelisa.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do egzarchy Orelisa w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10247, 'plPL', 'Doktor Vomisa, Ph.T.', 'Na wschodnich obrzeżach miasta leży Poligon. Nasz najlepszy eksperymentator, doktor Vomisa, bawi się tam połączeniem technologii Grabieżców Spaczenia, eterycznej i oczywiście goblińskiej.$B$BTo w dużej mierze zasługa twojego zbieractwa, $gmłodszy techniku:młodsza techniczko; 3. stopnia $N!$B$BIdź do niego; wiem, że będzie miał sposób na ocalenie Strefy 52.$B$BA że pewnie zrobi z ciebie królika doświadczalnego, na twoim miejscu wziąłbym ze sobą kilku przyjaciół, tak na wszelki wypadek.', 'Porozmawiaj z doktorem Vomisą, Ph.T. na Poligonie w Burzy Otchłani.', '', '', '', '', '', '', 0),
(10248, 'plPL', 'Ty, robot', 'Doktor Vomisa, Ph.T., do usług. Proszę, weź ten sterownik. Chcę, żebyś go $gwłączył:włączyła; i $gwypróbował:wypróbowała; mojego świeżo wynalezionego złomowego grabieżcę X6000.$B$BTylko trzymaj się blisko! Sterownik jest połączony z moją konsolą i jeśli oddalisz się za bardzo, robot przestanie działać.$B$BWypróbuj wszystko... Będę obserwował i kalibrował jego serwa na podstawie twojej jazdy próbnej.', 'Włącz sterownik złomowego grabieżcy X6000 i przetestuj jego możliwości. Potem przekaż swoje uwagi doktorowi Vomisie, Ph.T. na Poligonie w Burzy Otchłani. Poradź sobie z wszelkimi problemami, które się pojawią.', '', 'Wróć do doktora Vomisy, Ph.T. na Poligonie w Burzy Otchłani.', 'Test złomowego grabieżcy X6000 zakończony', '', '', '', 0),
(10249, 'plPL', 'Z powrotem do szefa!', 'Jestem pewien, że rakietowódz będzie chciał zamienić z tobą słowo czy dwa!$B$BNa twoim miejscu bez wahania wróciłbym do Strefy 52 i z nim porozmawiał!', 'Natychmiast zgłoś się do Rakietowodza Kadłubka w Strefie 52 w Burzy Otchłani!', '', '', '', '', '', '', 0),
(10256, 'plPL', 'W poszukiwaniu klucznika', 'Z perspektywy czasu chyba powinienem był się spodziewać, że magia Kael\'thasa będzie tak potężna. Zawsze był utalentowanym magiem, ale nigdy nie widziałem czegoś takiego jak moc, którą władał podczas ataku na wieżę.$B$BBariera nie pozwala mi wypatrzyć jasnowidzeniem siły, która ją podtrzymuje, ale tobie w tym nie przeszkodzi.$B$BBędziesz jednak potrzebować ogniska. Po równinach na zachód od Kuźni Many Duro wędruje obrośnięty kryształami olbrzym zwany Apexem. Jeden z jego kryształów byłby doskonałym ogniskiem do jasnowidzenia.', 'Odszukaj Apexa i zdobądź od niego kryształowe ognisko Apexa. Wróć do Purpurowej Wieży i użyj kryształowego ogniska Apexa w pobliżu kuli arcymaga Vargotha, by odkryć, kto ma klucz do złamania klątwy wieży.', '', 'Wróć do arcymaga Vargotha w Purpurowej Wieży w Burzy Otchłani.', 'Odkryj tożsamość klucznika', '', '', '', 0),
(10257, 'plPL', 'Zdobycie zwornika', 'Nie dziwi mnie, że Kael\'thas powierzył klucz do tej bariery komuś takiemu jak dowódca Sarannis. Książę Kael\'thas jest wieloma rzeczami, ale z pewnością nie prostakiem.$B$BAby raz na zawsze złamać klątwę, musisz wejść do Twierdzy Burz i zdobyć zwornik.$B$BDopiero gdy zwornik zostanie zniszczony, odzyskam wolność.', 'Wypraw się do Botaniki w Twierdzy Burz i odbierz zwornik dowódcy Sarannis. Zanieś go arcymagowi Vargothowi w Purpurowej Wieży.', '', 'Wróć do arcymaga Vargotha w Purpurowej Wieży w Burzy Otchłani.', '', '', '', '', 0),
(10260, 'plPL', 'Otchłanolog Miedziogrosz', 'Na pewno $gprzeszedłeś:przeszłaś; głównym mostem z Gór Klingi do Burzy Otchłani. $GWidziałeś:Widziałaś; tam otchłanologa Miedziogrosza, który pracuje z tym całym swoim zwariowanym sprzętem?$B$BDziwne... Czekam na raport od niego, a jest już spóźniony. Pewnie zapomniał. Wiesz, jacy są ci „naukowcy”.$B$BWróć na most i przyciśnij go. Nie przyjmuj żadnych wymówek, po prostu przynieś mi ten raport.$B$BDzięki!', 'Porozmawiaj z otchłanologiem Miedziogroszem na moście prowadzącym z Gór Klingi do Burzy Otchłani.', '', '', '', '', '', '', 0),
(10261, 'plPL', 'Poszukiwane: serwo anihilatora!', 'POSZUKIWANE: 1 serwo anihilatora na wymianę psującego się w moim długoszyjnym analizatorze widma.$B$BTy i twoi przyjaciele możecie sprawdzić, czy krwawe elfy z Kuźni Many B\'naar na zachodzie nie mają zapasowych. Chyba kręci się tam kilka tajemnych anihilatorów.$B$BProszę dostarczyć serwo w nienagannym stanie Papie Wheelerowi w Strefie 52.', 'Zdobądź serwo anihilatora i zanieś je Papie Wheelerowi w Strefie 52 w Burzy Otchłani.', '', 'Wróć do Papy Wheelera w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10262, 'plPL', 'Hałda eteryków', 'Jest jeszcze coś, w czym chcę twojej pomocy.$B$BGrupa eteryków zwana Zaxxis zerwała z Konsorcjum i zaczęła działać na własny rachunek. Zawarli nawet układy z krwawymi elfami ze Słonecznej Furii. Nie będziemy tego tolerować!$B$BPrzeniknąłem do ich grupy na Hałdzie na południu. Ale gdy zlikwidowałem ich przywódcę, musiałem uciekać tutaj, do Strefy 52.$B$B$N, idź tam i przynieś ich insygnia. Oczywiście nie wszyscy je noszą, bo to tchórze.', 'Zbierz 10 insygniów Zaxxis i zanieś je tropicielowi Otchłani Khay\'jiemu w Strefie 52 w Burzy Otchłani.', '', 'Wróć do tropiciela Otchłani Khay\'jiego w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10263, 'plPL', 'Pomoc dla Konsorcjum', 'Naaru z Shattrath próbują znaleźć sposób, by przekonać Konsorcjum do swojego punktu widzenia.$B$BSzczęśliwym trafem stosunki handlowe między eterykami a krwawymi elfami w Burzy Otchłani ostatnio się popsuły.$B$BW mieście jest przedstawiciel Konsorcjum, tropiciel Otchłani Khay\'ji, który niedawno wpadł w kłopoty przez bandę eteryków renegatów. Jako przedstawicielka Aldorów chciałabym, żebyś mu $gpomógł:pomogła;, jak tylko zdołasz.', 'Porozmawiaj z tropicielem Otchłani Khay\'jim w Strefie 52 w Burzy Otchłani.', '', '', '', '', '', '', 0),
(10264, 'plPL', 'Pomoc dla Konsorcjum', 'Naaru z Shattrath próbują znaleźć sposób, by przekonać Konsorcjum do swojego punktu widzenia.$B$BSzczęśliwym trafem stosunki handlowe między eterykami a krwawymi elfami w Burzy Otchłani ostatnio się popsuły.$B$BW mieście jest przedstawiciel Konsorcjum, tropiciel Otchłani Khay\'ji, który niedawno wpadł w kłopoty przez bandę eteryków renegatów. Jako przedstawiciel Widzących chciałbym, żebyś mu $gpomógł:pomogła;, jak tylko zdołasz.', 'Porozmawiaj z tropicielem Otchłani Khay\'jim w Strefie 52 w Burzy Otchłani.', '', '', '', '', '', '', 0),
(10265, 'plPL', 'Kryształowa zbiórka dla Konsorcjum', 'Nasz przywódca, książę Nexusa Haramad, polecił mi zdobyć kryształowy artefakt z Ruin Arklon na południowym wschodzie.$B$BTo stare ruiny draenei. Niestety, zarówno dla mnie, jak i dla tutejszych goblinów, Płonący Legion postanowił się tam wprowadzić i prowadzić własne wykopaliska.$B$BJeśli zechcesz mi pomóc, idź do ruin i odbierz kryształowy artefakt upiornemu władcy imieniem Pentatharon.', 'Zdobądź kryształowy artefakt z Arklon i zanieś go tropicielowi Otchłani Khay\'jiemu w Strefie 52 w Burzy Otchłani.', '', 'Wróć do tropiciela Otchłani Khay\'jiego w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10266, 'plPL', 'Prośba o pomoc', 'Podczas twojego pobytu w Ruinach Arklon otrzymałem prośbę o pomoc od jednego z naszych przedstawicieli w terenie. Wygląda na to, że Konsorcjum ma pewne „trudności” z odzyskaniem od krwawych elfów towaru, za który te odmawiają zapłaty.$B$BWyjdź ze Strefy 52 na wschód i przejdź przez most na sąsiednią wyspę. Mojego wspólnika, Gahruja, znajdziesz w Posterunku Środka, tuż za wejściem do Ekokopuły Środka.', 'Odszukaj Gahruja i zaoferuj mu swoje usługi. Znajdziesz go w Posterunku Środka w Ekokopule Środka w Burzy Otchłani.', '', '', '', '', '', '', 0),
(10267, 'plPL', 'Odzyskanie mienia', 'Nasze stosunki handlowe z krwawymi elfami chyba dobiegły końca. Kilka tygodni temu dostarczono im do Kuźni Many Duro duży transport sprzętu mierniczego. Odmówili zapłaty.$B$B$N, proszę, złóż wizytę krwawym elfom z Kuźni Many Duro na wschodzie. Wygląda na to, że mają tam kłopot z plagą istot many, więc wykorzystaj to, że są zajęci.$B$BNie obchodzi mnie, co się z nimi stanie, ale bardzo chciałbym odzyskać naszą własność.', 'Zbierz 10 skrzynek ze sprzętem mierniczym i zanieś je Gahrujowi w Posterunku Środka w Ekokopule Środka w Burzy Otchłani.', '', 'Wróć do Gahruja w Ekokopule Środka w Burzy Otchłani.', '', '', '', '', 0),
(10268, 'plPL', 'Audiencja u księcia', 'Książę Nexusa Haramad dał mi znać, że życzy sobie natychmiastowego zwrotu tej własności do rąk własnych. Byłbym bardzo wdzięczny, gdybyś $gdostarczył:dostarczyła; ją w moim imieniu.$B$BAudiencja u księcia Nexusa to wielki zaszczyt, a jestem pewien, że z zainteresowaniem wysłucha opowieści o twoich przygodach tu, w Burzy Otchłani.$B$BOdszukaj jego komnatę na szczycie Burzowej Iglicy na północy. Często jest tam obecny jako holograficzny obraz, do którego możesz się zwrócić.', 'Dostarcz sprzęt mierniczy wizerunkowi księcia Nexusa Haramada w Burzowej Iglicy w Burzy Otchłani.', '', '', '', '', '', '', 0),
(10269, 'plPL', 'Pierwszy punkt triangulacyjny', 'Jest jeszcze inny powód odzyskania sprzętu mierniczego. Pewien kryształ z legend draenei ma dla mnie wielkie znaczenie.$B$BPodobno obdarza swojego posiadacza boską mocą! Grozi jednak, że wydobędą go inni – mianowicie Płonący Legion.$B$B$N, weź sprzęt i użyj go, by znaleźć pierwszy punkt triangulacyjny. Wiemy, że jest gdzieś na wschodzie, w pobliżu Kuźni Many Ultris.$B$BPotem zgłoś się do mojego agenta, handlarza Hazzina, na wyspie Kuźni Many Ultris.', 'Użyj urządzenia triangulacyjnego, by wskazało ci drogę do pierwszego punktu triangulacyjnego. Gdy go znajdziesz, zgłoś jego położenie handlarzowi Hazzinowi w Strażnicy Protektoratu na wyspie Kuźni Many Ultris w Burzy Otchłani.', 'Pierwszy punkt triangulacyjny odkryty', 'Porozmawiaj z handlarzem Hazzinem w Strażnicy Protektoratu w Burzy Otchłani.', '', '', '', '', 0),
(10270, 'plPL', 'Nie tak skromna propozycja', 'Po twojej minie widzę, że jesteś kimś, kto docenia dobry zysk.$B$BZdobyłem renomę jako handlarz egzotycznymi towarami i zamierzam rozkręcić nowe przedsięwzięcie.$B$BPotrzebuję solidnego podwykonawcy, który zdobędzie towar z Niebiańskiej Grani.$B$BNajpierw trzeba będzie ponownie zasilić platformę teleportacyjną. W Szybie Dostępowym Zeon, po południowej stronie Kuźni Many Ultris, jest zapasowy zasilacz. Działa tam Protektorat, więc może dojdziesz do celu, idąc za jego znacznikami.', 'Zdobądź zasilacz teleportera i zanieś go do eterycznej platformy teleportacyjnej na Niebiańskiej Grani na wschód od Kuźni Many Ultris. Aktywuj platformę i oddaj zasilacz teleportera wizerunkowi handlarza wiatru Marida, aby mógł go zainstalować.', '', 'Porozmawiaj z wizerunkiem handlarza wiatru Marida, używając eterycznej platformy teleportacyjnej na Niebiańskiej Grani w Burzy Otchłani.', '', '', '', '', 0),
(10271, 'plPL', 'Przejdźmy do interesów', 'Jak zapewne $gzauważyłeś:zauważyłaś;, okolica roi się od smoków Otchłani w różnych stadiach wzrostu. Wszystkie smoki Otchłani, młode i stare, zawierają esencję, której bardzo pożąda K... eee, pewien mój klient.$B$BMało kto chce ryzykować życie, by ją zbierać, więc mamy to miejsce dla siebie. Możesz zacząć od zbierania esencji z dowolnych tutejszych stworzeń, ale koniecznie musimy od razu zacząć gromadzić zapasy. Wróć do mnie, gdy będziesz $gmiał:miała; pierwszą partię.', 'Zbierz 8 esencji smoków Otchłani, a potem wróć w okolice eterycznej platformy teleportacyjnej. Esencję smoka Otchłani można zdobyć ze smokowców Otchłani lub smoków Otchłani.', '', 'Wróć w okolice eterycznej platformy teleportacyjnej na Niebiańskiej Grani w Burzy Otchłani. Porozmawiaj ze spowitą postacią, która czai się w pobliżu.', '', '', '', '', 0),
(10272, 'plPL', 'Obiecujący początek', 'Przybyliśmy tu, by zbadać pogłoski o dziwnej odmianie smoków, być może nawet potomków samego Śmiercioskrzydłego. Wyraźnie nie są to jednak zwykłe czarne smoki.$B$BDowiemy się więcej, gdy zbadamy ich jaja. Nienawidzą mojego stada tak głęboko, że nie mogę podejść dość blisko, by zebrać jaja. Zgodzisz się pomóc?', 'Zbierz 15 jaj drakaninów Otchłani, a potem wróć do Tyri i Jorada na Niebiańskiej Grani.', '', 'Wróć do Tyri na Niebiańskiej Grani w Burzy Otchłani.', '', '', '', '', 0),
(10273, 'plPL', 'Kłopotliwe przeszkody', 'Twój były pracodawca, handlarz wiatru Marid, musiał zwęszyć, że teraz nam pomagasz. Dzięki mojej projekcji widziałam, jak jego tropiciele Otchłani wkraczają na ten teren w nadziei, że nas wytropią.$B$BNa razie udaje nam się ich unikać, ale trzeba rozprawić się z Maridem, zanim problem się pogłębi.$B$BJeśli dobrze oceniasz Marida, zrobi niemal wszystko, by zabezpieczyć dostawy swojego towaru. Wróć do niego i powiedz, że masz dla niego ofertę. Odciągnij go na bok i zabij.', 'Porozmawiaj z handlarzem wiatru Maridem i odciągnij go od jego punktu handlowego. Rozpraw się z nim, a potem wróć do Tyri i Jorada na Niebiańskiej Grani.', '', 'Wróć do Tyri na Niebiańskiej Grani w Burzy Otchłani.', '', '', '', '', 0),
(10274, 'plPL', 'Zabezpieczenie Niebiańskiej Grani', 'Smoki Otchłani mają tak samo dziki temperament jak ich przodkowie, czarne smoki, ale jest w nich coś zupełnie obcego. Szybko się wykluwają i dojrzewają, czerpiąc z dziwnych energii, które ukształtowały ich rodzaj podczas zagłady Draenoru.$B$BChcę się o nich dowiedzieć o wiele więcej, ale sądzę, że ich moce mogą się przydać mojemu stadu. Jeśli pokazem dominacji zdołamy obalić przywódcę tych smokowców, Veraku, zmusimy resztę do uległości.', 'Użyj Wyzwania Błękitnego Stada, by sprowokować Veraku na południowym skraju Niebiańskiej Grani. Pokonaj go i wróć do Tyri i Jorada na Niebiańskiej Grani.', '', 'Wróć do Tyri na Niebiańskiej Grani w Burzy Otchłani.', 'Zabij Veraku', '', '', '', 0),
(10275, 'plPL', 'Drugi punkt triangulacyjny', 'Przekalibrowałem urządzenie triangulacyjne na podstawie informacji z pierwszego punktu. Użyjesz go dokładnie tak samo, by odkryć drugi.$B$BMogę ci tylko powiedzieć, że drugi punkt jest gdzieś daleko na zachodzie.$B$BGdy go zlokalizujesz, porozmawiaj z handlarzem wiatru Tulumanem, kolejnym agentem księcia Nexusa. Udaje handlarza bronią w małym punkcie handlowym przy moście prowadzącym na wyspę, na której stoi Kuźnia Many Ara.', 'Użyj urządzenia triangulacyjnego, by wskazało ci drogę do drugiego punktu triangulacyjnego. Gdy go znajdziesz, zgłoś jego położenie handlarzowi wiatru Tulumanowi na Przystani Tulumana, tuż po drugiej stronie mostu od wyspy Kuźni Many Ara w Burzy Otchłani.', 'Drugi punkt triangulacyjny odkryty', 'Porozmawiaj z handlarzem wiatru Tulumanem na Przystani Tulumana w Burzy Otchłani.', '', '', '', '', 0),
(10276, 'plPL', 'Pełny trójkąt', 'Dzięki danym z pierwszego i drugiego punktu jestem już pewien, że kryształ jest na szczycie Ruin Farahlonu na północnym wschodzie.$B$BNiestety dane wskazują, że kryształ się przemieszcza, co oznacza, że ktoś już go odkrył, prawdopodobnie Płonący Legion!$B$BNa wszelki wypadek radzę zabrać ze sobą kilku przyjaciół.$B$BZabij demona, który ma kryształ, i zwróć go księciu Nexusa Haramadowi.', 'Odzyskaj Kryształ Ata\'mal i dostarcz go wizerunkowi księcia Nexusa Haramada w Burzowej Iglicy w Burzy Otchłani.', '', 'Wróć do wizerunku księcia Nexusa Haramada w Burzowej Iglicy w Burzy Otchłani.', '', '', '', '', 0),
(10281, 'plPL', 'Oficjalna prezentacja', 'Witaj, $N. Nie lękaj się. To tylko projekcja mojej obecnej postaci. Tylko w ten sposób mój towarzysz i ja mogliśmy obserwować okolicę, nie ujawniając się.$B$BEteryk, który się do ciebie zwrócił, Marid, jest niewiele lepszy od oszusta udającego uczciwego kupca. Chciałabym, żebyś zamiast tego $grozważył:rozważyła; współpracę ze mną. Jestem tu, by dowiedzieć się więcej o niezwykłych drakaninach z tej grani. Spotkaj się ze mną na północnym krańcu grani, a porozmawiamy o tym dokładniej.', 'Odnajdź Tyri na północnym krańcu Niebiańskiej Grani i porozmawiaj z nią.', '', '', '', '', '', '', 0),
(10290, 'plPL', 'W poszukiwaniu farahlitu', 'Na północnym wschodzie jest miejsce zwane Kamieniem Otchłani – punkt, którego nie było, gdy ta kraina była bujna i zielona. Nowo odsłonięte formacje kryształów ukazały nam minerał, który na pamiątkę dawnej tożsamości tej ziemi nazwaliśmy farahlitem.$B$BNiewielka ilość wydobytego farahlitu już zyskała popularność u naszych klientów. Minerał najwyższej jakości nie pochodzi jednak ze stałych złóż, lecz z olbrzymów wokół Kamienia Otchłani. Mogę zaoferować ci udział w zyskach, jeśli pomożesz w dostawach farahlitu wyższej jakości.', 'Zbierz 4 bryły surowego farahlitu i wróć do Zubena Elgenubiego w Burzowej Iglicy.', '', 'Wróć do Zubena Elgenubiego w Burzowej Iglicy w Burzy Otchłani.', '', '', '', '', 0),
(10292, 'plPL', 'Więcej mocy!', 'Zbieranie cennego towaru w małych partiach ma swój chałupniczy urok, ale na dzisiejszym rynku po prostu nie jest konkurencyjne.$B$BNie, potrzebujemy metody masowej produkcji farahlitu! Wtedy ilość na rynku będzie całkowicie pod naszą kontrolą.$B$BMam pomysł, ale będzie wymagał potężnego, skupionego źródła energii. Jest tylko jedno miejsce, gdzie można znaleźć dość silne źródło energii. Udaj się do obozów Legionu na północ od nas i „pozyskaj” trochę ich dział.', 'Zuben Elgenubi chce, żebyś $gzdobył:zdobyła; 8 dział Legionu i $gprzyniósł:przyniosła; je do Burzowej Iglicy.', '', 'Wróć do Zubena Elgenubiego na Kruszącym się Pustkowiu w Burzy Otchłani.', '', '', '', '', 0),
(10293, 'plPL', 'Żyła złota', 'Skoro mamy już dobry produkt bazowy, potrzebujemy czegoś wyższej jakości. Farahlit, który do tej pory zebraliśmy, jest oczywiście niezły, ale wiem, że gdzieś jest lepszy.$B$BMusimy zdobyć próbkę bezpośrednio od Cragskaara, patriarchy olbrzymów z Farahlonu! Znajdziesz go wśród innych olbrzymów w okolicy Kamienia Otchłani. Z grzbietu sterczą mu ogromne bryły farahlitu i właśnie tego potrzebujemy. Powal olbrzyma i zabierz mu rdzeń z farahlitu.', 'Zuben Elgenubi z Burzowej Iglicy chce, żebyś $gzdobył:zdobyła; rdzeń z farahlitu.', '', 'Wróć do Zubena Elgenubiego w Burzowej Iglicy w Burzy Otchłani.', '', '', '', '', 0),
(10299, 'plPL', 'Wyłączenie Kuźni Many B\'naar', 'Nie możemy wyłączyć kuźni many siłą, bo ryzykowalibyśmy wybuch, który wstrząsnąłby Rubieżą w posadach.$B$BWedług twojego zapisu istnieje procedura awaryjnego wyłączenia, która trwale unieruchamia tę technologię – zabezpieczenie typowe dla konstrukcji naaru.$B$BAby ją przeprowadzić, musisz zdobyć kryształ, który pozwoli ci porozumieć się z konsolą. Według naszych informacji ten kryształ dostępu ma nadzorca Theredis.', 'Wróć do Kuźni Many B\'naar i odbierz nadzorcy Theredisowi kryształ dostępu do B\'naar. Użyj go przy konsoli Kuźni Many B\'naar, by ją wyłączyć, i zdaj raport anachoretce Karji.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do anachoretki Karji w Strefie 52 w Burzy Otchłani.', '', 'Kuźnia Many B\'naar wyłączona', '', '', 0),
(10300, 'plPL', 'Odbudowa kostura', '<Ravandwyr ogląda kostur i zauważa, że brakuje części głowicy.>$B$BCo za barbarzyństwo! Ekkorash musiał zabrać kryształową głowicę kostura do jakiegoś innego świecidełka, nie zdając sobie sprawy, że działa ona w harmonii z resztą kostura.$B$BDopóki kostur jest uszkodzony, jego moc jest znacznie osłabiona. Z odpowiednim kryształem draenei powinienem zdołać go naprawić. Słyszałem, jak gobliny wspominały o kryształach, które noszą duchy w Ruinach Enkaat na północy.', 'Zdobądź 4 nieskazitelne odłamki kryształu od duchów w Ruinach Enkaat i zanieś je Ravandwyrowi w Strefie 52.', '', 'Wróć do Ravandwyra w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10301, 'plPL', 'Otwarcie kompendium', 'Choć cieszę się, że odzyskałem większość Kompendium Krasusa, bez heliotropowego okulusa jest ono bezużyteczne. Widzisz, Krasus doskonale zdawał sobie sprawę z ogromnej mocy zaklęć zapisanych w księdze i zadbał o to, by chronić je przed wścibskimi oczami.$B$BTylko obeznany mag może użyć okulusa, by odkryć tajemnice kompendium.$B$BPodczas ataku Kael\'thasa jedna z jego zastępczyń, żniwiarka zaklęć Marathelle, zagrabiła go i zabrała do Warowni Słonecznej Furii na północny wschód od wieży. Bez wątpienia uznała go za ładne świecidełko.', 'Odbierz heliotropowy okulus żniwiarce zaklęć Marathelle w Warowni Słonecznej Furii.', '', 'Użyj kostura arcymaga Vargotha, by skontaktować się z arcymagiem.$B$BJeśli zgubisz kostur arcymaga Vargotha, porozmawiaj z Ravandwyrem w Strefie 52, a dostaniesz nowy.', '', '', '', '', 0),
(10305, 'plPL', 'Wypędzaczka Belmara', 'Ta zniszczona, solidna księga nie jest księgą zaklęć, jaką można by się spodziewać u maga Kirin Toru. Jej strony pokrywają ręcznie przepisane opowieści z barwnymi ilustracjami.$B$BKsięga wydaje się znacznie starsza od swojej dawnej właścicielki i mogła być nawet rodzinną pamiątką. Silne przywiązanie do niej mogło być ostatnią nicią wiążącą ducha Belmary z ruinami Kirin\'Var. Odłożenie księgi na właściwe miejsce na regale w jej kwaterze może pomóc ukoić niespokojnego ducha.', 'Odszukaj kwaterę wypędzaczki Belmary w Alei Czarodziejów i odłóż księgę na regał. Potem porozmawiaj z kustoszem Dieworthem w Wiosce Kirin\'Var.', '', 'Wróć do kustosza Diewortha w Wiosce Kirin\'Var w Burzy Otchłani.', 'Ukój ducha Belmary', '', '', '', 0),
(10306, 'plPL', 'Zaklinacz Luminrath', 'Płaszcz, bez wątpienia wyrób wysokich elfów, jest bogato uszyty, nawet jak na standardy Kirin Toru. Symbole i znaki wszyte w jego tkaninę nic ci nie mówią, ale wyraźnie nadają szacie magiczne właściwości.$B$BByć może ten przedmiot wiąże ducha dawnego właściciela z tym planem istnienia. Jeśli tak, odłożenie go do komody w kwaterze zaklinacza Luminratha może zerwać więź ducha z tym światem i pozwolić mu spocząć.', 'Odszukaj kwaterę zaklinacza Luminratha w Alei Czarodziejów i odłóż płaszcz do jego komody. Potem porozmawiaj z kustoszem Dieworthem w Wiosce Kirin\'Var.', '', 'Wróć do kustosza Diewortha w Wiosce Kirin\'Var w Burzy Otchłani.', 'Ukój ducha Luminratha', '', '', '', 0),
(10307, 'plPL', 'Cohlien Tkacz Mrozu', 'Patrząc na czapkę, zastanawiasz się, czy jakikolwiek mag Kirin Toru nosiłby takie nakrycie głowy. Sądząc po jej zużyciu, gnom chyba nigdzie się bez niej nie ruszał.$B$BPrzymierzasz ją na chwilę i nie odkrywasz żadnych magicznych właściwości poza lekką ochotą do tańca.$B$BTa cenna rzecz może być źródłem więzi zmarłego maga z wioską. Włożenie czapki do kufra w kwaterze Cohliena może uwolnić jego ducha.', 'Odszukaj kwaterę Cohliena Tkacza Mrozu w Alei Czarodziejów i odłóż czapkę do jego kufra. Potem porozmawiaj z kustoszem Dieworthem w Wiosce Kirin\'Var.', '', 'Wróć do kustosza Diewortha w Wiosce Kirin\'Var w Burzy Otchłani.', 'Ukój ducha Cohliena', '', '', '', 0),
(10308, 'plPL', 'Kolejna hałda eteryków', '', '', '', 'Wróć do tropiciela Otchłani Khay\'jiego w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10309, 'plPL', 'To Grabieżca Spaczenia, ale z sercem', 'Widzisz tam na południu tego złomowanego Grabieżcę Spaczenia? Czyż nie jest piękny?$B$BChcę jego serce!$B$BCo? Tak, oczywiście, że ma serce... a co go nie ma?$B$B<N. D. przez chwilę wygląda na oburzonego.>$B$BIdź tam, podważ go, przynieś, czego chcę, a w zamian dam ci niezłe znaleźne.$B$BA, na twoim miejscu wziąłbym ze sobą przyjaciela czy dwóch. Ci eterycy Zaxxis to niezła banda wrednych typów!$B$BWeź ten spaczony poraziciel, żeby pobudzić jego serce, kiedy będziesz $ggotów:gotowa; zacząć.', 'Odzyskaj Serce Grabieżcy Spaczenia i dostarcz je N. D. Meancampowi na Hałdzie w Burzy Otchłani.', '', 'Wróć do N. D. Meancampa na Hałdzie w Burzy Otchłani.', '', '', '', '', 0),
(10310, 'plPL', 'Sabotaż bramy wypaczenia!', 'Płonący Legion jest tuż obok, na złomowisku Grabieżców Spaczenia, musimy więc zrobić, co w naszej mocy, by powstrzymać napływ demonów w te okolice.$B$BNa południu mają bramę wypaczenia, w miejscu, które sprytnie nazwali Punkt Inwazji: Niszczyciel.$B$BChcę, żebyś $gposzedł:poszła; tam ze mną i $gpilnował:pilnowała; mojego bezpieczeństwa, gdy będę ją sabotował.$B$BPotem idź do Posterunku Środka na północy, w Ekokopule Środka, i powiadom Gahruja o naszym sukcesie.$B$BPrzyda się do tego jeden czy dwóch twoich przyjaciół.', 'Eskortuj Drijyę do bramy wypaczenia w Punkcie Inwazji Niszczyciel i dopilnuj, by nic mu się nie stało, gdy będzie próbował ją sabotować. Potem porozmawiaj z Gahrujem w Posterunku Środka w Ekokopule Środka w Burzy Otchłani.', 'Brama wypaczenia Płonącego Legionu zsabotowana', 'Wróć do Gahruja w Ekokopule Środka w Burzy Otchłani.', '', '', '', '', 0),
(10311, 'plPL', 'Drijya potrzebuje twojej pomocy', 'Dobrze widzieć tu kogoś chętnego do pomocy, $N.$B$BPłonący Legion z pobliskiego złomowiska Grabieżców Spaczenia coraz bardziej się zuchwali i zaczynam się obawiać o nasze bezpieczeństwo. Demony wciąż dostają posiłki z Punktu Inwazji Niszczyciel na południu.$B$BMój rodak, Drijya, poszedł tam na zwiad, żeby sprawdzić, czy da się coś zrobić z bramą wypaczenia Płonącego Legionu.$B$BOdszukaj go i pomóż mu, jak tylko możesz.', 'Porozmawiaj z Drijyą w pobliżu Punktu Inwazji Niszczyciel w Burzy Otchłani.', '', '', '', '', '', '', 0),
(10312, 'plPL', 'Kroniki Kirin\'Var', 'Uciszenie duchów nie pozbawiło ich agresji, jak mieliśmy nadzieję. Złowrogie duchy, które $gpokonałeś:pokonałaś;, znów pojawiły się na ulicach osady.$B$BMusimy odkryć, co jest tego przyczyną. Zniszczenie Kirin\'Var było tylko początkiem, inaczej duchy już dawno by się uspokoiły.$B$BRatusz w południowej części Kirin\'Var prowadził księgę wszystkich mieszkańców. Z tego, co ostatnio słyszałem, miał ją pod opieką mag bojowy Dathric. Może jego duch wciąż ją ma.', 'Odzyskaj Kroniki Kirin\'Var z ratusza w Wiosce Kirin\'Var i zanieś je kustoszowi Dieworthowi.', '', 'Wróć do kustosza Diewortha w Wiosce Kirin\'Var w Burzy Otchłani.', '', '', '', '', 0),
(10313, 'plPL', 'Pomiar energii wypaczenia', 'Jeśli przeczucie nas nie myli i te kuźnie many zbudowano przy użyciu technologii z Twierdzy Burz, cała Rubież może być w wielkim niebezpieczeństwie.$B$BMechanizmy ładowania energii Twierdzy Burz nigdy nie miały działać tak blisko ziemi. Energie wypaczenia mogą zniszczyć tę krainę, nawet gdy są zamknięte w rurociągach Kaela.$B$BZanieś tę kulę do Kuźni Many B\'naar; jest dostrojona do pomiaru energii wypaczenia. Użyj jej na końcach rurociągów, tam gdzie wchodzą w ziemię.', 'Egzarcha Orelis w Strefie 52 chce, żebyś $gzaniósł:zaniosła; kulę dostrojoną do wypaczenia do Kuźni Many B\'naar i $gużył:użyła; jej na końcach jej czterech rurociągów.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do egzarchy Orelisa w Strefie 52 w Burzy Otchłani.', 'Północny rurociąg zmierzony', 'Wschodni rurociąg zmierzony', 'Południowy rurociąg zmierzony', 'Zachodni rurociąg zmierzony', 0),
(10314, 'plPL', 'Uporczywe podejrzenie', 'To dziwne magiczne urządzenie nie przypomina niczego, co kiedykolwiek $gwidziałeś:widziałaś;. Z pewnością nie jest dziełem krwawych elfów.$B$BGdy wyczuwasz duchy zbliżające się do budynku, kula świeci jaśniej, a kiedy duchy się oddalają, blask przygasa. Nie ma wątpliwości, że ma ona udział w spaczeniu duchów.$B$BJak działa, pozostaje zagadką. Może kustosz Dieworth coś zrozumie, jeśli dostarczysz mu szczątki kilku duchów wraz ze swoimi obserwacjami.', 'Zbierz 10 odrażających pozostałości z wypaczonych duchów na Dziedzińcu Kaplicy w Wiosce Kirin\'Var i zanieś je kustoszowi Dieworthowi.', '', 'Wróć do kustosza Diewortha w Wiosce Kirin\'Var w Burzy Otchłani.', '', '', '', '', 0),
(10315, 'plPL', 'Unieszkodliwienie otchłanomantów', 'Krwawe elfy to głupcy! Cieszę się, że nasze stosunki handlowe z nimi się rozpadły. W całych moich podróżach po kosmosie nie spotkałem równie samolubnych istot.$B$BWciąż niszczą otaczającą nas krainę swoimi kuźniami many, zobaczmy więc, czy zdołamy nadszarpnąć ich działania za mostem, w Kuźni Many Ara.$B$BIch otchłanomanci przesyłają energię do krwawych klejnotów i z powrotem, by ustabilizować przepływ mocy. Idź tam i wybij ich!', 'Zabij 15 otchłanomantów Słonecznej Furii i wróć do tropiciela Otchłani Oazula na Przystani Tulumana w Burzy Otchłani.', '', 'Wróć do tropiciela Otchłani Oazula na Przystani Tulumana w Burzy Otchłani.', '', '', '', '', 0),
(10316, 'plPL', 'W poszukiwaniu dowodów', 'Ktokolwiek stoi za przemianą duchów, działa z pełnym rozmysłem i dba o to, by najpierw uderzać w najpotężniejszych magów, ale dlaczego? Magia zdolna wpływać na duchy poległych magów Kirin Toru musi być bardzo potężna.$B$BPo co potężny mag miałby zadawać sobie tyle trudu? Skłaniam się ku temu, że to kolejny spisek Kael\'thasa, mający sprowadzić tu jeszcze więcej nieszczęść. Jeśli są tu krwawe elfy, pewnie ukrywają się w domach za krytym mostem.', 'Przeszukaj Dziedziniec Kaplicy w Wiosce Kirin\'Var w poszukiwaniu wskazówek, kto stoi za manipulowaniem duchami.', '', '', '', '', '', '', 0),
(10317, 'plPL', 'Rozprawa z brygadzistą', 'Krwawe elfy nazywają kopalnię pod Kuźnią Many Ara Kopalnią Trelleum. Odkąd straciły tę pod Kuźnią Many Ultris, tylko stąd czerpią materiał do zasilania kuźni.$B$BNie trzeba chyba mówić, że sparaliżowanie ich wydobycia bardzo by nam pomogło. Może nawet zdołalibyśmy tam wkroczyć i przejąć ją dla siebie?$B$BTak czy inaczej, chcę, żebyś tam $gposzedł:poszła; i $grozprawił:rozprawiła; się z brygadzistą Sundownem. Kopalnia jest z tyłu wyspy, po lewej.', 'Rozpraw się z brygadzistą Sundownem w Kopalni Trelleum pod Kuźnią Many Ara w Burzy Otchłani.', '', '', '', '', '', '', 0),
(10318, 'plPL', 'Rozprawa z nadmistrzem', 'Byłem tu brygadzistą. Ale teraz, kiedy mnie zdegradowano, zrozumiałem, że nasza pielgrzymka z Quel\'Thalas do Rubieży była jednym wielkim kłamstwem.$B$BKłamstwem, którym Kael\'thas posłużył się, by wzmocnić swoje siły tu, w Burzy Otchłani.$B$BPróbowałem przekonać braci, że powinniśmy odejść, zwłaszcza że jest tu Płonący Legion, ale wszyscy są zbyt uparci.$B$BZrobisz coś dla mnie? Zabij nadmistrza Grindgarra. Potem wróć do swojego eteryka i powiedz mu, że nie jestem już jego wrogiem.', 'Zabij nadmistrza Grindgarra. Potem wróć do handlarza wiatru Tulumana na Przystani Tulumana w Burzy Otchłani.', '', 'Wróć do handlarza wiatru Tulumana na Przystani Tulumana w Burzy Otchłani.', '', '', '', '', 0),
(10319, 'plPL', 'Przejęcie filakterii', 'Chyba należą ci się wyjaśnienia. $GPoznałeś:Poznałaś; jednego z uczniów arcymaga, Ravandwyra, ale był też drugi, imieniem Naberius.$B$BBył gorliwym uczniem, ale ciągnęło go do nekromancji. Gdy pojawił się Kael\'thas ze swoimi siłami, Naberius skorzystał z okazji, by zdradzić arcymaga, i wydał mu sekrety obrony wieży.$B$BTeraz, jak się zdaje, stał się liszem. Jeśli mamy go powstrzymać, musimy przejąć jego filakterię. Znając go, zakopał ją gdzieś w ukryciu na swoim terenie.', 'Odzyskaj filakterię Naberiusa z Dziedzińca Kaplicy w Wiosce Kirin\'Var i zanieś ją kustoszowi Dieworthowi.', '', 'Wróć do kustosza Diewortha w Wiosce Kirin\'Var w Burzy Otchłani.', '', '', '', '', 0),
(10320, 'plPL', 'Zniszcz Naberiusa!', 'Arcymag Vargoth dostrzegał niebezpieczeństwo w tym, że Naberius zgłębia nekromancję, ale chyba nigdy nie przewidział, że jego własny uczeń sprowadzi na Kirin Tor takie zniszczenie.$B$BMusisz go pokonać, $N, inaczej dalej będzie zniewalał duchy naszych poległych braci, odbierał im należny spoczynek i niszczył to, co zostało z Kirin\'Var.$B$BSkoro mamy jego filakterię, może się z nim zmierzyć dwóch lub trzech wojowników, ale kto wie, co jego magia zrobiłaby z większą liczbą przeciwników?', 'Kustosz Dieworth z Wioski Kirin\'Var chce, żebyś $gstawił:stawiła; czoła Naberiusowi i $gpokonał:pokonała; go na Dziedzińcu Kaplicy.', '', 'Wróć do kustosza Diewortha w Wiosce Kirin\'Var w Burzy Otchłani.', '', '', '', '', 0),
(10321, 'plPL', 'Wyłączenie Kuźni Many Coruu', 'Twój sukces w B\'naar dał nam wiele nadziei, $N.$B$BPodzieliliśmy się naszymi odkryciami z Widzącymi, a oni w zamian przekazali nam więcej informacji o pozostałych kuźniach many.$B$BWciąż stoją trzy inne kuźnie many, w pełni kontrolowane przez armię Słonecznej Furii.$B$BKuźnię Many Coruu znajdziesz na wschodzie. Kryształ dostępu ma tam nadzorczyni Seylanna. Zdobądź go i użyj na konsoli sterującej kuźni many, by rozpocząć awaryjne wyłączenie.$B$BWszyscy na ciebie liczymy, $N.', 'Udaj się do Kuźni Many Coruu na wschód od Strefy 52 i zdobądź kryształ dostępu do Coruu od nadzorczyni Seylanny. Użyj go na konsoli Kuźni Many Coruu, by ją wyłączyć, i wróć do anachoretki Karji.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do anachoretki Karji w Strefie 52 w Burzy Otchłani.', '', 'Kuźnia Many Coruu wyłączona', '', '', 0),
(10322, 'plPL', 'Wyłączenie Kuźni Many Duro', 'Dostaliśmy wieści z jednej z dwóch wciąż działających kuźni many. Armia Słonecznej Furii traci kontrolę nad Kuźnią Many Duro.$B$BZwiększona produkcja energii przyciągnęła do niej chmary zbłąkanych istot many – w kuźni panuje chaos.$B$BWybuch w Duro może wywołać reakcję łańcuchową, która zagroziłaby całej Rubieży. Kryształ dostępu, którego potrzebujesz, by bezpiecznie unieruchomić kuźnię many, ma nadzorca Athanel.', 'Anachoretka Karja chce, żebyś $gudał:udała; się do Kuźni Many Duro i $gzdobył:zdobyła; kryształ dostępu do Duro od nadzorcy Athanela. Użyj go na konsoli Kuźni Many Duro, by ją wyłączyć.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do anachoretki Karji w Strefie 52 w Burzy Otchłani.', '', 'Kuźnia Many Duro wyłączona', '', '', 0),
(10323, 'plPL', 'Wyłączenie Kuźni Many Ara', 'Już tylko jedna kuźnia many utrzymuje Twierdzę Burz w działaniu. Gdy unieruchomimy Kuźnię Many Ara, Kael będzie musiał sięgnąć po resztki zgromadzonej energii.$B$BUdaj się do Kuźni Many Ara na północnym zachodzie i zadaj ostateczny cios, którego potrzebujemy – wyłącz ją.$B$BOstatni kryształ dostępu ma nadzorca Azarad. Uprzedzam, że w ostatniej działającej kuźni many Kaela spodziewamy się silnego oporu. Pewnie przyda ci się pomoc zaufanych przyjaciół.', 'Udaj się do Kuźni Many Ara i zdobądź kryształ dostępu do Ara od nadzorcy Azarada. Użyj go na konsoli Kuźni Many Ara, by ją wyłączyć.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do anachoretki Karji w Strefie 52 w Burzy Otchłani.', '', 'Kuźnia Many Ara wyłączona', '', '', 0),
(10328, 'plPL', 'Odprawy Słonecznej Furii', 'Coś w tych kuźniach many nie daje mi spokoju, $N. Technologia naaru jest niezwykle zaawansowana; Kael\'thas powinien potrzebować lat, by w ogóle zacząć ją rozumieć.$B$BZbieranie informacji na ten temat idzie opornie, bo armia Kaela jest dobrze zdyscyplinowana i niszczy wszelkie ślady pisemnej korespondencji.$B$BDoniesiono nam, że Kuźnię Many Duro atakują istoty many. Możliwe, że jej obrońcy nie zdążyli jeszcze zniszczyć swoich odpraw. Zdobądź je i przynieś mi.', 'Udaj się do Kuźni Many Duro i odbierz odprawę wojskową Słonecznej Furii oraz odprawę magiczną Słonecznej Furii stacjonującym tam oddziałom Słonecznej Furii. Po wykonaniu zadania wróć do egzarchy Orelisa.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do egzarchy Orelisa w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10329, 'plPL', 'Wyłączenie Kuźni Many B\'naar', 'Gdy cię nie było, odbyłem przyjacielską pogawędkę z Aldorami. Kuźnie many rzeczywiście wyglądają na przerobioną technologię naaru z Twierdzy Burz. Podobno większość konstruktów naaru ma zabezpieczenia, które w razie zagrożenia pozwalają je trwale unieruchomić.$B$BProcedurę zwykle uruchamia się na konsoli sterującej za pomocą kryształu dostępu. I proszę, według listy, którą $gzdobyłeś:zdobyłaś;, taki kryształ ma niejaki nadzorca Theredis. Zdobądź go i zobacz, co da się zrobić.', 'Wróć do Kuźni Many B\'naar i zdobądź kryształ dostępu do B\'naar od nadzorcy Theredisa. Użyj go na konsoli sterującej B\'naar, by ją wyłączyć, a potem złóż raport mistrzowi szpiegów Thalodienowi.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do mistrza szpiegów Thalodiena w Strefie 52 w Burzy Otchłani.', '', 'Kuźnia Many B\'naar wyłączona', '', '', 0),
(10330, 'plPL', 'Wyłączenie Kuźni Many Coruu', 'Thalodien opowiedział nam, jak $gunieruchomiłeś:unieruchomiłaś; Kuźnię Many B\'naar. Liczy na powtórkę tutaj i poprosił nas, byśmy wypatrywali każdego, kto użyje kryształu, by dostać się do konsoli w środku. Kryształ dostępu ma nadzorczyni Seylanna, jesteśmy tego pewni.$B$BWróć tam i dokończ operację. Nie musisz się już skradać; zdobądź kryształ, rozpocznij wyłączanie, zabij techników, którzy będą próbowali cię powstrzymać, i uciekaj.$B$BPośpiesz się, niedługo pieski Kaela nas wywęszą.', 'Zdobądź kryształ dostępu do Coruu od nadzorczyni Seylanny. Użyj go na konsoli sterującej Coruu, by wyłączyć kuźnię many, i wróć do Caledisa Jasnoświta.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do Caledisa Jasnoświta w Kuźni Many Coruu w Burzy Otchłani.', '', 'Kuźnia Many Coruu wyłączona', '', '', 0),
(10331, 'plPL', 'Niezbędne narzędzia', 'Nie $gwidziałeś:widziałaś; przypadkiem gdzieś ciężkiego młota kowalskiego? Wziąłem go tu ze sobą, żeby dokończyć podkowy dla kilku koni starego Amorlina, ale nie mogę go znaleźć.$B$BPrzeszukałem stodołę co najmniej sześć razy i nigdzie go nie ma. Może któryś z pozostałych uczniów go wziął i odniósł do kuźni? $GZechciałbyś:Zechciałabyś; tam zejść i poszukać? Warsztat jest na południowy wschód od wieży, na Rynku.', 'Odbierz młot kowalski uczniom z Kirin\'Var i przynieś go uczniowi Andrethanowi w Wiosce Kirin\'Var.', '', 'Wróć do ucznia Andrethana w Wiosce Kirin\'Var w Burzy Otchłani.', '', '', '', '', 0),
(10332, 'plPL', 'Mistrz kowalski Rhonsus', 'Wreszcie moje dzieło czeladnicze jest ukończone! Nie mogę się doczekać, aż oficjalnie przedstawię je mistrzowi Rhonsusowi.$B$B<Uczeń przygląda ci się, gdy opowiadasz, co cię spotkało przy odzyskiwaniu młota.>$B$BZaatakowali cię? Wszyscy? Na Światłość, oszaleli!$B$BCo mamy zrobić, $N? Przykro mi to mówić, ale być może trzeba będzie zabić mistrza Rhonsusa. Zostałbym wtedy jedynym kowalem w Kirin\'Var, ale sądzę, że moje wyszkolenie wystarczy, by zaspokoić potrzeby osady.', 'Uczeń Andrethan z Wioski Kirin\'Var chce, żebyś $gzabił:zabiła; ducha Rhonsusa, mistrza kowalskiego osady.', '', 'Wróć do ucznia Andrethana w Wiosce Kirin\'Var w Burzy Otchłani.', '', '', '', '', 0),
(10333, 'plPL', 'Pomóż Mamie Wheeler', 'Słuchaj, $N, może $gzrobiłbyś:zrobiłabyś; mi jeszcze jedną przysługę?$B$BMojej wspólniczce w terenie przydałaby się pomoc. Może $gzajrzałbyś:zajrzałabyś; do niej?$B$BJestem pewien, że Mama Wheeler doceni pomoc. Tylko nie przejmuj się jej ciętym językiem.$B$BPilnuje naszych interesów na wschodzie. Znajdziesz ją tuż za wejściem do Ekokopuły Środka, w Posterunku Środka.', 'Porozmawiaj z Mamą Wheeler w Posterunku Środka w Ekokopule Środka w Burzy Otchłani.', '', '', '', '', '', '', 0),
(10334, 'plPL', 'Potrzeba więcej krowiego dzwonka', 'Gdzie, ach, gdzie się podziała moja Bessy? Po ataku szukałem jej na polach i na Dziedzińcu Kaplicy, ale nigdzie jej nie było!$B$BZostał mi po niej tylko ten stary krowi dzwonek. Zwykle przybiega, gdy go usłyszy, ale te słabe stare kości pewnie nie potrafią nim dość mocno potrząsnąć.$B$BPożyczę ci dzwonek Bessy, jeśli zechcesz pójść na pola i zadzwonić nim najmocniej, jak zdołasz. Może Bessy czeka tylko na trochę więcej krowiego dzwonka.', 'Odnajdź Bessy na polach w pobliżu Wzgórza Kaplicy w Wiosce Kirin\'Var w Burzy Otchłani.', '', '', '', '', '', '', 0),
(10335, 'plPL', 'Pomiary w ruinach', 'Muszę się dostać do Ruin Farahlonu i zacząć wykopaliska! Kłopot w tym, że zaroiło się tam od demonów!$B$BMoże $gwykonałbyś:wykonałabyś; dla mnie wstępne prace?$B$BW ruinach na północnym wschodzie są trzy miejsca, w których chcę, żebyś $grozstawił:rozstawiła; znaczniki miernicze. Każde jest przy sztandarze draenei.$B$BWróć do mnie, gdy uda ci się rozstawić wszystkie trzy znaczniki.', 'Rozstaw trzy znaczniki miernicze, a potem wróć do Zephyriona w Burzowej Iglicy w Burzy Otchłani.', '', 'Wróć do Zephyriona w Burzowej Iglicy w Burzy Otchłani.', 'Pierwszy znacznik mierniczy rozstawiony', 'Drugi znacznik mierniczy rozstawiony', 'Trzeci znacznik mierniczy rozstawiony', '', 0),
(10336, 'plPL', 'Sługi Culuthasa', 'Kilka tygodni temu Płonący Legion zajął Ruiny Farahlonu i pokrzyżował nam plany wydobycia stamtąd artefaktów.$B$BA dziś rano dowiedziałem się, że jeden z ich upiornych władców, Culuthas, jakimś sposobem wybił całą resztę Płonącego Legionu. Od tamtej pory przyzywa demony, które mu służą.$B$B$N, idź do tych ruin na północnym wschodzie i oczyść je z demonów.', 'Zabij 10 ogarów Culuthasa i 5 oczu Culuthasa. Potem wróć do tropiciela Otchłani Nauthisa w Burzowej Iglicy w Burzy Otchłani.', '', 'Wróć do tropiciela Otchłani Nauthisa w Burzowej Iglicy w Burzy Otchłani.', '', '', '', '', 0),
(10337, 'plPL', 'Aż krowy wrócą do domu', 'Widząc, że Bessy wciąż się na ciebie gapi, wskazujesz w stronę, gdzie czeka Thadell. Przyłapujesz się na tym, że obiecujesz krowie ochronę w drodze do domu. Kończąc zdanie, uświadamiasz sobie, że krowa w żaden sposób nie mogła zrozumieć niczego, co $gpowiedziałeś:powiedziałaś;.$B$BWzruszasz ramionami i szykujesz się, by strzec krasuli w drodze powrotnej do Thadella.', 'Bezpiecznie odprowadź Bessy do jej właściciela, Thadella.', 'Odprowadź Bessy do domu.', 'Wróć do Thadella w Wiosce Kirin\'Var w Burzy Otchłani.', '', '', '', '', 0),
(10338, 'plPL', 'Wyłączenie Kuźni Many Duro', 'A więc Kuźnia Many Duro jest atakowana, a siły Słonecznej Furii straciły nad nią kontrolę? Cóż za dylemat! Jeśli padnie Duro, padnie też Twierdza Burz. Jedyny minus... jeśli Twierdza Burz zostanie zniszczona, wybuch pewnie pociągnie za sobą to, co zostało z tej przeklętej krainy.$B$BMartwy Kael\'thas – dobrze. Martwi wszyscy pozostali – no... chyba nie najlepiej. Przykro mi o to prosić, ale idź do Kuźni Many Duro i wyłącz ją, zanim pójdzie z dymem. Kryształ dostępu ma nadzorca Athanel.', 'Wróć do Kuźni Many Duro i zdobądź kryształ dostępu do Duro od nadzorcy Athanela. Użyj go na konsoli sterującej Duro, by ją wyłączyć, i złóż raport mistrzowi szpiegów Thalodienowi.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do mistrza szpiegów Thalodiena w Strefie 52 w Burzy Otchłani.', '', 'Kuźnia Many Duro wyłączona', '', '', 0),
(10339, 'plPL', 'Eterium', 'Tuż na południe stąd znajdziesz Plac Zborny Eterium. Eterium coś tam szykuje... Być może atak na Ultris.$B$BNie możemy jednak ryzykować, $N. Przebij się przez ich zewnętrzną obronę i zniszcz ich ośrodek szkoleniowy.$B$BGdy wybijesz ich żołnierzy i zabijesz kapitana Zovaxa, odszukaj transponder Eterium Zeta i użyj go, by nawiązać ze mną kontakt i otrzymać kolejne rozkazy.', 'Dowódca Ameer chce, żebyś $gzabił:zabiła; 5 zabójców Eterium, 5 szturmowców Eterium, 2 badaczy Eterium i kapitana Zovaxa, a potem $guruchomił:uruchomiła; transponder Eterium Zeta.', '', 'Porozmawiaj z wizerunkiem dowódcy Ameera za pomocą transpondera Eterium Zeta na Placu Zbornym Eterium w Burzy Otchłani.', '', '', '', '', 0),
(10341, 'plPL', 'Bij leżącego', 'Wieści, które $godkryłeś:odkryłaś;, są pomyślne, $N. Nie tylko możesz bez przeszkód wkroczyć do Kuźni Many Duro, ale to także świetna okazja, by zadać cios armii Kaela.$B$BWykorzystaj atak istot many na swoją korzyść i wybij wszystkich maruderów Słonecznej Furii, na których się natkniesz.$B$BW przeciwieństwie do Thalodiena nie czerpię szczególnej radości z bezsensownej rzezi własnych pobratymców, ale korzyść taktyczna jest tu zbyt duża, by ją przepuścić.', 'Zabij 8 zaklinaczy Słonecznej Furii, 6 strzelców Słonecznej Furii i 4 centurionów Słonecznej Furii. Po wykonaniu zadania wróć do magistrix Larynny w Strefie 52.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do magistrix Larynny w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10342, 'plPL', 'Łupek łupkoskórych', 'Nieźle zarabiam, sprzedając trunki tutejszym pijaczynom. Ale chcę czegoś więcej!$B$BRakietowódz ciągle mi opowiada, że nie może dopracować paliwa rakietowego, dzięki któremu X-52 oderwie się od ziemi.$B$BMożemy rozwiązać za niego ten drobny problem.$B$BNa początek muszę wydobyć olej z łupka tutejszych łupkoskórych obdzieraczy! Stanie się skoncentrowaną, choć wybuchową, bazą mieszanki, którą mam na myśli.$B$BObdzieraczy i ich łupek znajdziesz wszędzie w okolicy purpurowych skał.', 'Zbierz 5 łupków łupkoskórego i daj je Bootsowi w Strefie 52 w Burzy Otchłani.', '', 'Wróć do Bootsa w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10343, 'plPL', 'Niekończąca się inwazja', 'Atak Kael\'thasa na Kirin\'Var zaczął się od ogłuszającego huku i jasnego błysku w kwaterach oficerskich na północnym zachodzie. Tam zniszczenia były największe, a po wycofaniu się krwawych elfów zaczęło się dziać coś dziwnego.$B$BDo wioski zaczęły napływać z całej okolicy istoty z czystej many. Na razie powstrzymujemy je, jak możemy, ale mając więcej informacji o broni, której użył Kael\'thas, mam nadzieję całkowicie odciąć napływ istot many.', 'Przeszukaj opanowaną przez istoty many część Wioski Kirin\'Var w poszukiwaniu odłamka bomby many i zanieś go porucznikowi-czarownikowi Morranowi.', '', 'Wróć do porucznika-czarownika Morrana w Wiosce Kirin\'Var w Burzy Otchłani.', '', '', '', '', 0),
(10345, 'plPL', 'Ciało kłamie...', 'Widzisz te zwłoki? Odpowiada za tę rzeź Arconus. Wyssał je do cna i zostawił tylko cielesne łupiny. Ale nie daj się zwieść ciałom! Wewnątrz tych zwłok czają się bestie z mięsa, gotowe skoczyć na każdego nieostrożnego głupca, który podejdzie za blisko.$B$BMam rozkazy. Muszę tu zostać, dopóki nie przybędą posiłki. Ale nic nie stoi na przeszkodzie, żebyś $gwziął:wzięła; mój zapalnik i $gzniszczył:zniszczyła; uschnięte zwłoki zaścielające kopalnie. Tak czy inaczej, misja musi zostać wykonana.', 'Użyj zapalnika Protektoratu na 12 uschniętych zwłokach. Po wykonaniu zadania zwróć zapalnik Protektoratu agentowi Araxesowi przed Szybem Dostępowym Zeon.$B', '', 'Wróć do agenta Araxesa przed Szybem Dostępowym Zeon w Burzy Otchłani.', 'Uschnięte zwłoki spalone', '', '', '', 0),
(10348, 'plPL', 'Nowe możliwości', 'Podobno grupa „druidów” z Azeroth bardzo zainteresowała się działaniem naszej technologii ekokopuł.$B$BPrzedstawiciele Ekspedycji Cenariońskiej chętnie zdobyliby dostęp do roślin rosnących w kopułach, zwłaszcza do jednej, zwanej dzwonem z kości słoniowej, znanej z właściwości leczniczych. Rośnie w kępach zarośli wokół większych roślin w Ekokopule Środka.$B$BPodzielę się z tobą zyskiem, jeśli zechcesz zebrać zioła na moją pierwszą dostawę.', 'Zbierz 15 dzwonów z kości słoniowej i wróć do Mehrdada w Posterunku Środka.', '', 'Wróć do Mehrdada w Ekokopule Środka w Burzy Otchłani.', '', '', '', '', 0),
(10353, 'plPL', 'Arconus Nienasycony', 'Araxesa i mnie wysłano do Ultris dwa dni temu. Nasza misja: odnaleźć i zlikwidować władcę Pustki Arconusa. Wytropiliśmy go w tej kopalni i odkryliśmy, że żywił się energią tutejszych istot.$B$BWywiązała się strzelanina, w której rozdzieliliśmy się z Araxesem. Teraz utknąłem tutaj, ciężko ranny. Misja legła w gruzach!$B$BJeśli zdołasz zlikwidować Arconusa, dowództwo będzie ci wdzięczne. Jeśli przyjmiesz tę misję, pomogę ci, dając ci do ochrony swoje odbicie.', 'Agent Ya-six przy Szybie Dostępowym Zeon w Burzy Otchłani poprosił cię, żebyś $gzabił:zabiła; Arconusa Nienasyconego i $gwrócił:wróciła; do dowódcy Ameera w Strażnicy Protektoratu w Burzy Otchłani.', '', 'Wróć do dowódcy Ameera w Strażnicy Protektoratu w Burzy Otchłani.', '', '', '', '', 0),
(10365, 'plPL', 'Wyłączenie Kuźni Many Ara', 'Poszło ci o wiele lepiej, niż ktokolwiek z nas się spodziewał. Kuźnia Many Ara to ostatnia działająca kuźnia many Kaela. Znajdziesz ją na północny zachód stąd, choć pewnie trzeba będzie nadłożyć drogi, żeby się do niej dostać. Chcemy, żebyś ją $gwyłączył:wyłączyła;.$B$BOstatni kryształ dostępu ma nadzorca Azarad. O ile wiemy, to ostatnie źródło energii Kaela, więc spodziewaj się silnego oporu. Na twoim miejscu zabrałbym ze sobą paru przyjaciół.$B$BHmm... Azarad. Cóż za dziwne imię jak na sin\'dorei.', 'Udaj się do Kuźni Many Ara i zdobądź kryształ dostępu do Ara od nadzorcy Azarada. Użyj go na konsoli Kuźni Many Ara, by ją wyłączyć.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do mistrza szpiegów Thalodiena w Strefie 52 w Burzy Otchłani.', '', 'Kuźnia Many Ara wyłączona', '', '', 0),
(10380, 'plPL', 'Mroczny pakt', 'Byliśmy tak ślepi, $N, że sojusz dwóch naszych najgroźniejszych wrogów zupełnie umknął naszej uwadze.$B$BNie zdziwiłbym się, gdyby Widzący maczali palce w ukrywaniu przed nami tej informacji, ale teraz musimy stawić czoła rzeczywistości. Płonący Legion i armia Słonecznej Furii Kael\'thasa służą pod tym samym sztandarem.$B$BTylko dzięki tym demonom Kael\'thas w ogóle zdołał wykorzystać technologię Twierdzy Burz. Z rozkazu Orelisa muszę ci polecić, byś je $gzniszczył:zniszczyła;.', 'Kaylaan na Przystani Tulumana w Burzy Otchłani chce, żebyś $gzabił:zabiła; 6 gan\'argów majsterkowiczów wypaczenia, 3 córy przeznaczenia i 3 mo\'argów mistrzów wypaczenia.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do Kaylaana na Przystani Tulumana w Burzy Otchłani.', '', '', '', '', 0),
(10381, 'plPL', 'Koniec z Aldorami', 'Moja misja tutaj jest skończona. Zrobiłem to, co kazał mi Orelis – nigdy go nie zawiodłem.$B$BKoniec z tym. Przewiduję wielką rzeź – krucjatą ją nazwą – gdy rozejdą się wieści o sojuszu Kael\'thasa z Płonącym Legionem.$B$BNajpierw oddają nasze najświętsze miasto naszym wrogom, a potem każą nam ginąć w walce z ich wrogami. Wróć do Orelisa; powiedz mu, że od teraz naaru mogą toczyć swoje walki sami.', 'Złóż raport egzarsze Orelisowi w Strefie 52.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', '', '', '', '', '', 0),
(10384, 'plPL', 'Dane Eterium', 'Rozejrzyj się, istoto z mięsa. Bardzo blisko tego transpondera powinno być ogniwo danych Eterium. Znajdź je, otwórz i wydobądź zawartość.$B$BNatychmiast przynieś ją do tego transpondera!', 'Wizerunek dowódcy Ameera na Placu Zbornym Eterium – przy transponderze Eterium Zeta – chce, żebyś $godzyskał:odzyskała; ogniwo danych Eterium.', '', 'Wróć do wizerunku dowódcy Ameera za pomocą transpondera Eterium Zeta na Placu Zbornym Eterium w Burzy Otchłani.', '', '', '', '', 0),
(10385, 'plPL', 'Ryzyko uszkodzenia mózgu = wysokie', 'Używają przekaźników, by przesyłać informacje po całym placu zbornym.$B$BJest tylko jeden sposób, byś $gzobaczył:zobaczyła; te przekaźniki i $gwydobył:wydobyła; z nich informacje. Niestety, może to spowodować nieodwracalne uszkodzenie mózgu.$B$BJeśli nadal jesteś $gzainteresowany:zainteresowana;, musisz zabijać członków Eterium tu, na placu zbornym, i zabierać ich esencje. Gdy zdobędziesz esencję, wypij ją. Pozwoli ci na chwilę zobaczyć przekaźnik z eterium – na tyle długo, byś $gzdążył:zdążyła; go zniszczyć i wydobyć z niego informacje.', 'Wizerunek dowódcy Ameera na Placu Zbornym Eterium – przy transponderze Eterium Zeta – chce, żebyś $godzyskał:odzyskała; 15 porcji danych przekaźnika z eterium.', '', 'Porozmawiaj z wizerunkiem dowódcy Ameera za pomocą transpondera Eterium Zeta na Placu Zbornym Eterium w Burzy Otchłani.', '', '', '', '', 0),
(10405, 'plPL', 'S-A-B-O-T-A-Ż', 'Musimy zniszczyć maszynerię, dzięki której powstają te wynaturzone tropiciele Nexusa. Uderzenie w ich protoakcelerator byłoby daremne, bo to eteryczny wytwór. Zamiast tego musimy zniszczyć rurę energetyczną kuźni many, której używają jako przewodu.$B$BMam wszystko, czego potrzebuję, by zbudować urządzenie przeciążające przewód, z wyjątkiem jednej rzeczy. Do kalibracji urządzenia potrzebuję owijacza archonta albo nadrządcy, który może niedługo przejść przemianę.', 'Wizerunek dowódcy Ameera na Placu Zbornym Eterium – przy transponderze Eterium Zeta – chce, żebyś $gzdobył:zdobyła; 1 przygotowany owijacz Eterium.', '', 'Porozmawiaj z wizerunkiem dowódcy Ameera za pomocą transpondera Eterium Zeta na Placu Zbornym Eterium w Burzy Otchłani.', '', '', '', '', 0),
(10406, 'plPL', 'Dostarczenie wiadomości', 'Wysyłam jednego z moich burzycieli, by umieścił urządzenie zakłócające. Dopilnuj tylko, by nic mu się nie stało, gdy będzie montował zakłócacz.$B$BChroń go! Nie będzie się bronił, jeśli wrogowie go zaatakują, bo jest tylko holograficznym obrazem, ale obraz można zniszczyć!$B$BWróć do mnie, gdy zadanie zostanie wykonane.$B', 'Wizerunek dowódcy Ameera na Placu Zbornym Eterium – przy transponderze Eterium Zeta – chce, żebyś $godprowadził:odprowadziła; burzyciela Protektoratu do przewodu Kuźni Many Ultris i $gchronił:chroniła; go, gdy będzie sabotował rurociąg.', 'Przewód Eterium zsabotowany', 'Porozmawiaj z wizerunkiem dowódcy Ameera za pomocą transpondera Eterium Zeta na Placu Zbornym Eterium w Burzy Otchłani.', '', '', '', '', 0),
(10407, 'plPL', 'Cień Socrethara', 'Niesławny eredar Socrethar dowodzi Płonącym Legionem w Burzy Otchłani. Samo wspomnienie jego imienia wystarczy, by większość draenei przeszedł dreszcz. Wydaje rozkazy z wyspy na północnym zachodzie, do której dostęp mają tylko jego najbardziej zaufani poplecznicy.$B$BAby się tam dostać, musisz zdobyć kamień teleportacyjny, co nie będzie łatwe. Pierwsza połowa kamienia jest w posiadaniu mistrza kuźni Moruga w Bazie Kuźniczej Zapomnienie. Drugą połowę ma Silroth w Bazie Kuźniczej Gehenna.', 'Anachoretka Karja w Strefie 52 chce, żebyś $gzdobył:zdobyła; pierwszą połowę Kamienia Socrethara od mistrza kuźni Moruga w Bazie Kuźniczej Zapomnienie i drugą połowę Kamienia Socrethara od Silrotha w Bazie Kuźniczej Gehenna.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do anachoretki Karji w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10408, 'plPL', 'Król Nexusa Salhadaar', 'Mam jeszcze jeden dezintegrator, zdolny zniszczyć trzy przewodniki otaczające Salhadaara. Gdy przewodniki zostaną zniszczone, ochronne pola siłowe Salhadaara opadną. Za ten czyn uderzy na ciebie z furią, jakiej nigdy dotąd nie $gwidziałeś:widziałaś;, $N.$B$BJeśli chcesz uwolnić świat od Salhadaara, dam ci dezintegrator.', 'Wizerunek dowódcy Ameera na Placu Zbornym Eterium – przy transponderze Eterium Zeta – chce, żebyś $gzniszczył:zniszczyła; dezintegratorem Protektoratu pola siłowe Salhadaara, a potem $gzgładził:zgładziła; Króla Nexusa Salhadaara.', '', 'Porozmawiaj z wizerunkiem dowódcy Ameera za pomocą transpondera Eterium Zeta na Placu Zbornym Eterium w Burzy Otchłani.', '', '', '', '', 0),
(10411, 'plPL', 'Elektrowstrząsowa rozkosz!', 'Wokół zrujnowanej kuźni many znajdziesz pozostałości po dziele Dimensiusa. Sączący się szlam wypełnia sadzawki otaczające Ultris. Tuż pod tymi sadzawkami, gdzie stoi teraz Plac Zborny Eterium, znajdziesz jeszcze więcej odcieków w postaci odpadów Pustki.$B$BNajlepszym sposobem na ich usunięcie jest rozbicie szlamów elektrowstrząsem na grudki. Użyj tego eliksiru, by wzmocnić swoje ataki elektrycznością. Wyładowanie rozbije szlamy na surową postać. Zniszcz grudki!', 'Badacz Navuud w Strażnicy Protektoratu w Burzy Otchłani prosi, żebyś $gzniszczył:zniszczyła; 30 grudek odpadu Pustki i 30 grudek sączącego się szlamu.$B', '', 'Wróć do badacza Navuuda w Strażnicy Protektoratu w Burzy Otchłani.', '', '', '', '', 0),
(10413, 'plPL', 'Poczwary skażenia', 'Ostrożnie napełniasz fiolkę szlamem pokonanej poczwary Pustki.$B$BBadacz Navuud w Strażnicy Protektoratu byłby bardzo zainteresowany takim znaleziskiem! Natychmiast mu je zanieś!', 'Zanieś fiolkę szlamu poczwary Pustki badaczowi Navuudowi w Strażnicy Protektoratu w Burzy Otchłani.', '', '', '', '', '', '', 0),
(10417, 'plPL', 'Uruchom diagnostykę!', 'Gdziekolwiek Konsorcjum się osiedla, przywozimy naszą technologię ekokopuł. Pola pozwalają nam pracować w kontrolowanej atmosferze, która podtrzymuje życie, bo często trafiamy do wrogich środowisk.$B$BNiestabilne warunki i stworzenia Burzy Otchłani zaczęły niszczyć urządzenia podtrzymujące nasze kopuły, zwłaszcza generator na wschód stąd. Uruchomiona tam diagnostyka ma pomóc ustalić, jak przeciwdziałać uszkodzeniom. Możesz zebrać wyniki i mi je przynieść?', 'Odbierz wyniki diagnostyki i zanieś je Mehrdadowi w Posterunku Środka.', '', 'Wróć do Mehrdada w Ekokopule Środka w Burzy Otchłani.', '', '', '', '', 0),
(10418, 'plPL', 'Rozpraw się z sabotażystami', 'Szukając w okolicy tropów, co uszkadza nasz sprzęt, można dostrzec części generatorów osłon na dnie małego jeziora na północy. Nie wiem, czemu krokoliszki zainteresowały się sprzętem, ale musimy położyć temu kres.$B$BKonsorcjum stawia sprawę jasno. Jeśli trzeba wybierać między sprzętem a krokoliszkami, zwierzęta muszą zniknąć. Opłaci ci się, jeśli się nimi zajmiesz.', 'Mehrdad w Posterunku Środka chce, żebyś $gzabił:zabiła; 8 kolcołuskich krokoliszków.', '', 'Wróć do Mehrdada w Ekokopule Środka w Burzy Otchłani.', '', '', '', '', 0),
(10422, 'plPL', 'Kapitan Tyralius', 'Kapitan Tyralius zabrał pluton żołnierzy na południe, w stronę Placu Zbornego Eterium, 10 dni temu. Od tamtej pory nie mamy wieści ani od niego, ani od jego ludzi.$B$BNajpewniej wpadli w zasadzkę i zginęli, ale moje instrumenty wychwytują dziwny odczyt.$B$BChyba to sygnał alarmowy, ale te urządzenia już się myliły. Jeśli Tyralius żyje, trzymają go w jednym ze swoich więzień. Musisz odnaleźć to więzienie i otworzyć je kluczem, który pewnie ma przy sobie strażnik.', 'Treser mięsobestii Viridius w Strażnicy Protektoratu w Burzy Otchłani prosi, żebyś $godnalazł:odnalazła; i $guwolnił:uwolniła; kapitana Tyraliusa.$B', '', 'Wróć do tresera mięsobestii Viridiusa w Strażnicy Protektoratu w Burzy Otchłani.', 'Uwolnienie kapitana Tyraliusa', '', '', '', 0),
(10423, 'plPL', 'Do Burzowej Iglicy', 'Mistrz inżynier Ghabar będzie chciał poznać wyniki diagnostyki. Jeśli czegoś uczą, to tego, że musimy uważnie pilnować pracy naszych generatorów kopuł. Im bardziej niestabilne stają się pola, tym trudniej będzie zapanować nad ich działaniem. To mogłoby oznaczać katastrofę dla naszej wyprawy i wszystkiego, co mieszka pod kopułami.$B$BGhabara znajdziesz w Burzowej Iglicy. Po prostu idź drogą na północ od tej ekokopuły i przejdź przez most. Doprowadzi cię do windy u podnóża iglicy.', 'Porozmawiaj z Ghabarem w Burzowej Iglicy w Burzy Otchłani.', '', '', '', '', '', '', 0),
(10424, 'plPL', 'Diagnoza: stan krytyczny', 'Jeśli wyniki Mehrdada są prawidłowe – a nie mam powodu sądzić, że są błędne – pozostałe kopuły mogą mieć kłopoty.$B$BSądzę jednak, że Mehrdadowi nie udało się ustalić źródłowej przyczyny awarii. Od czasu do czasu stworzenia uszkadzają generatory, ale nigdy tak poważnie.$B$BDla pewności chciałbym, żebyś $gprzeprowadził:przeprowadziła; diagnostykę głównego generatora kopuły Burzowej Iglicy, który stoi w Ekokopule Sutheron, na samym wschodnim skraju kopuły.', 'Użyj urządzenia diagnostycznego w pobliżu generatora ekokopuły Sutheron i zanieś wyniki diagnostyki Ghabarowi w Burzowej Iglicy.', '', 'Wróć do Ghabara w Burzowej Iglicy w Burzy Otchłani.', '', '', '', '', 0),
(10425, 'plPL', 'Ucieczka z Placu Zbornego', 'Chwała K\'aresh! Rozszarpałby mnie!$B$BJestem żołnierzem Protektoratu, istoto z mięsa. Mój pluton wysłano na zwiad jakieś 10 dni temu. Gdy przemieszczaliśmy się po górnych półkach tej wyspy, napadła nas grupa z Eterium. Przynajmniej tak mi się wydaje. Mieli tę samą barwę energii, ale ich owijacze wyglądały na przesiąknięte Pustką.$B$BOszczędzili tylko Tyraliusa. Chyba wtrącili go do celi.$B$BMuszę wrócić do Strażnicy Protektoratu! Odeskortujesz mnie?$B', 'Odeskortuj pojmanego awangardzistę Protektoratu z powrotem do Strażnicy Protektoratu w Burzy Otchłani.', 'Eskorta pojmanego awangardzisty Protektoratu', 'Wróć do dowódcy Ameera w Strażnicy Protektoratu w Burzy Otchłani.', '', '', '', '', 0),
(10426, 'plPL', 'Flora ekokopuł', 'Tylko się rozejrzyj, $N! Czyż to nie zdumiewające? Oczywiście to niezwykłe odrodzenie życia jest ubocznym skutkiem działania kopuł eterycznych, ale wyobraź sobie, co mogłoby zdziałać w rękach ekspedycji.$B$BPrzygotowuję się do negocjacji z eterycznymi w sprawie dostępu do ich technologii, ale chciałabym lepiej poznać jej wpływ na życie roślinne.$B$BZbudowałam urządzenie, które skupia energię kopuły na tutejszych smagaczach. Czy zechcesz je dla mnie wypróbować i podzielić się wynikami?', 'Użyj modulatora pola energii na smagaczach z Farahlonu. Obserwuj wyniki, a po przeprowadzeniu 10 testów zdaj relację Aurine Księżycożar w Burzowej Iglicy.', '', 'Wróć do Aurine Księżycożar w Burzowej Iglicy w Burzy Otchłani.', 'Test modulatora energii', '', '', '', 0),
(10427, 'plPL', 'Stworzenia ekokopuł', 'Twoja praca ze smagaczami przyniosła zdumiewające informacje, ale zastanawiam się, czy to samo dotyczy zwierząt.$B$BObawiam się, że zebranie informacji o talbukach żyjących pod tą kopułą będzie trudniejsze niż badanie smagaczy.$B$BTym urządzeniem do znakowania możesz uśpić osłabionego talbuka i założyć mu znacznik, dzięki któremu będę śledzić zwierzę, gdy będzie dorastać. Mechanizm znakujący nie zadziała, dopóki talbuk nie zużyje większości sił.', 'Oznacz 12 talbuków dla Aurine Księżycożar w Burzowej Iglicy. Znakownicą talbuków możesz oznaczać zarówno reproduktory talbuków, jak i łanie talbuków.', '', 'Wróć do Aurine Księżycożar w Burzowej Iglicy w Burzy Otchłani.', '', 'Oznaczenie talbuka', '', '', 0),
(10429, 'plPL', 'Gdy natura posuwa się za daleko', 'Technologia kopuł ma taką moc! Z pewnością są jednak granice, których nie wolno nam przekroczyć, $N.$B$BStworzenia, którym pozwoli się rosnąć za bardzo lub zbyt szybko, mogą być równie złe jak jałowy krajobraz.$B$BSłyszałam pogłoski o właśnie takim stworzeniu w sadzawce na wschodzie. Słyszałam, jak eteryczni kupcy zmawiają się, by dla zabawy schwytać wyrośniętą hydrę, ale ja mam wobec tego olbrzyma inne plany. Przynieś mi serce tego stworzenia, żebym mogła je zbadać.', 'Aurine Księżycożar w Burzowej Iglicy chce, żebyś $gprzyniósł:przyniosła; jej serce potężnej hydry.', '', 'Wróć do Aurine Księżycożar w Burzowej Iglicy w Burzy Otchłani.', '', '', '', '', 0),
(10430, 'plPL', 'Test prototypu', 'Pracuję nad przenośnym zestawem naprawczym do generatorów, przeznaczonym do niektórych surowszych klimatów, w których działa Konsorcjum. Co prawda nie projektowano go z myślą o Burzy Otchłani, ale nie powinno być z nim problemów.$B$BUmówiłem już test z jednym z moich najlepszych techników w Ekokopule Dalekiego Pola, za Kamieniem Otchłani na północnym wschodzie. Zanieś ten prototyp Tasharowi. Będzie wiedział, co z nim zrobić. Jeśli zadziała, użyjemy go do wzmocnienia generatorów osłon w większych kopułach.', 'Zanieś aparat naprawczy Tasharowi w Ekokopule Dalekiego Pola w Burzy Otchłani.', '', '', '', '', '', '', 0),
(10431, 'plPL', 'Pomoc z zewnątrz', 'Meldunki Słonecznej Furii potwierdzają teorię, że Kael\'thas otrzymuje pomoc z zewnątrz przy budowie i obsłudze tych kuźni many. Kto mu pomaga, pozostaje pewną tajemnicą, choć zapewne dowiemy się tego w Kuźni Many Ara.$B$BWysłałem grupę moich ludzi na zwiad po okolicy. Idź do Przystani Tulumana na północ stąd i porozmawiaj z Kaylaanem. Dowiedz się, co odkrył w Kuźni Many Ara. Ustal, kto pomaga armii Słonecznej Furii, i zajmij się nimi.', 'Idź do Przystani Tulumana na północ od Strefy 52 i porozmawiaj z Kaylaanem.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', '', '', '', '', '', 0),
(10432, 'plPL', 'Obciążające dowody', 'Jak pewnie $gzauważyłeś:zauważyłaś;, w całej Kuźni Many Ara roi się od sług Płonącego Legionu. Kael\'thas zawarł sojusz z Płonącym Legionem. Musiał się zwiedzieć, że Illidan popada w obłęd, i odpowiednio zmienił mocodawców.$B$BJeśli Widzący zdobędą na to niezbite dowody, uzyskają znaczną przewagę polityczną. Wiem na pewno, że siły Legionu w tej kuźni many mają rozkazy opatrzone pieczęcią Kaela.$B$BZdobądź te rozkazy i zanieś je Thalodienowi.', 'Zdobądź od demonów w Kuźni Many Ara 8 rozkazów od Kael\'thasa i zanieś je mistrzowi szpiegów Thalodienowi w Strefie 52.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do mistrza szpiegów Thalodiena w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10433, 'plPL', 'Zachowywanie pozorów', 'Eterycy są sprytni i bardzo spostrzegawczy, więc nie bez powodu udaję tu zwykłego kuśnierza. Tak naprawdę przysłano mnie ze Strefy 52, żebym ocenił technologię, której eterycy używają do wytwarzania ekokopuł.$B$BChciałbym cię zwerbować, $N. Poproszono nas, żebyśmy w miarę możliwości korzystali z agentów, którzy nie są goblinami.$B$BChcę, żebyś pod przykrywką myśliwego $gprzyniósł:przyniosła; mi trochę futer rysiów szarpikłów. Rysie znajdziesz w całej Ekokopule Środka.', 'Przynieś 10 futer rysia szarpikła Shauly\'emu Pore\'owi w Posterunku Środka.', '', 'Wróć do Shauly\'ego Pore\'a w Ekokopule Środka w Burzy Otchłani.', '', '', '', '', 0),
(10434, 'plPL', 'Dynamiczny duet', 'Świetna robota.$B$B<Shauly puszcza do ciebie oko.>$B$BChyba to łykają. Teraz, kiedy wyślę cię na górę do moich wspólników w Burzowej Iglicy, nikt niczego nie będzie podejrzewał.$B$BPoszukaj tam Action Jaxona i Audi Igły. Powiedzą ci wszystko, co musisz wiedzieć. Powiedz im, że przysyła cię Shauly.', 'Porozmawiaj z Audi Igłą w Burzowej Iglicy w Burzy Otchłani.', '', '', '', '', '', '', 0),
(10435, 'plPL', 'Odzyskanie towaru', '<Audi rozgląda się, a potem zniża głos.>$B$BShauly pewnie opowiedział ci trochę o naszej pracy tutaj. Kiedy z Jaxonem jesteśmy w terenie na „polowaniu”, zbieramy części generatorów eterycznych ekokopuł i chowamy je w gniazdach naszej zwierzyny, raptorów w Ekokopule Dalekiego Pola.$B$BTo odludna okolica na północny wschód od Burzowej Iglicy, blisko Kamienia Otchłani. Nie sądzę, żeby było tam wielu eteryków, ale czy zechcesz nam pomóc zebrać części generatorów kopuł?', 'Audi Igła w Burzowej Iglicy chce, żebyś $gprzyniósł:przyniosła; jej 10 segmentów generatora kopuły.', '', 'Wróć do Audi Igły w Burzowej Iglicy w Burzy Otchłani.', '', '', '', '', 0),
(10436, 'plPL', 'Teren czysty!', 'Zanim zaczniemy test, musimy się upewnić, że w okolicy nie ma niczego, co mogłoby przeszkodzić. W naszym przypadku chodzi o te wyrośnięte jaszczury.$B$B<Tashar wskazuje na kosozębe raptory.>$B$BNie wiadomo, co by się stało, gdyby któryś z nich postanowił porządnie ugryźć generator podczas ładowania. Przez wszystkie lata pracy jako technik widziałem wiele dziwnych rzeczy, w tym niejedno plugastwo, które zaczynało jako skromne zwierzę.', 'Tashar, stacjonujący w Ekokopule Dalekiego Pola, chce, żebyś $gzabił:zabiła; 12 kosozębych raptorów.', '', 'Wróć do Tashara w Ekokopule Dalekiego Pola w Burzy Otchłani.', '', '', '', '', 0),
(10437, 'plPL', 'Przepis na zniszczenie', 'Na szczycie Kuźni Many Ultris znajduje się rozdarcie w Otchłani, przez które przeszedł władca Pustki Dimensius. To rozdarcie łączy Dimensiusa z Pustką, przez co jest odporny na obrażenia fizyczne. Jeśli namierzymy przewodnik, dzięki któremu Dimensius pozostaje przesunięty w fazie poza ten plan istnienia, zniszczymy go, a potem zniszczymy samego Dimensiusa.$B$BAby to zrobić, najpierw musisz zebrać fragmenty Dimensiusa od stworzeń Pustki, które wysyła do brudnej roboty.', 'Profesor Dabiri w Strażnicy Protektoratu w Burzy Otchłani chce, żebyś $godzyskał:odzyskała; 8 fragmentów Dimensiusa.', '', 'Wróć do profesora Dabiriego w Strażnicy Protektoratu w Burzy Otchłani.', '', '', '', '', 0),
(10438, 'plPL', 'Na otchłannych skrzydłach', 'Oto on, $N. Weź ten dezintegrator fazowy i wsiadaj! Smokowiec Otchłani Protektoratu zawiezie cię dość blisko Ultris, żebyś $gmógł:mogła; zrzucić dezintegrator na przewodnik Pustki.$B$BZrzuć jak najwięcej ładunków dezintegratora, żeby zapewnić całkowite unicestwienie!$B$BGdy będziesz $ggotów:gotowa;, porozmawiaj ze smokowcem Otchłani, a zabierze cię w górę.$B$BJeśli chybisz, zanim znów polecisz, będziesz $gmusiał:musiała; wziąć ode mnie więcej bomb.', 'Profesor Dabiri w Strażnicy Protektoratu w Burzy Otchłani chce, żebyś $gużył:użyła; dezintegratora fazowego, gdy znajdziesz się w zasięgu przewodnika Pustki spoczywającego na szczycie Ultris. Zrzuć jak najwięcej ładunków dezintegratora fazowego, żeby zapewnić całkowite unicestwienie. Ładunki dezintegratora fazowego same naprowadzą się na przewodnik Pustki, o ile będziesz dość blisko, by go użyć.$B$BJeśli ci się uda, wróć do profesora Dabiriego!$B', '', 'Wróć do profesora Dabiriego w Strażnicy Protektoratu w Burzy Otchłani.', 'Zniszczenie przewodnika Pustki', '', '', '', 0),
(10439, 'plPL', 'Dimensius Wszechpożeracz', 'Twoje odważne czyny zmusiły Ameera do działania! Wysłał kapitana Saeeda i Mścicieli!$B$BTeraz pozostało już tylko zniszczyć Dimensiusa.$B$BGdy będziesz $ggotów:gotowa;, wezwę Saeeda. Jeśli akurat nie toczy innej bitwy, będzie czekał na twoje rozkazy – dokładnie na wschód stąd.$B$BDaj mu znać, kiedy będziesz $ggotów:gotowa; do walki, a ruszy ze swoimi oddziałami!$B$BŻyczę ci powodzenia, istoto z mięsa! Polujemy na Dimensiusa od tysiąca lat!', 'Profesor Dabiri w Strażnicy Protektoratu w Burzy Otchłani chce, żebyś $gporozmawiał:porozmawiała; z kapitanem Saeedem, a potem $gpodążył:podążyła; za jego armią do Kuźni Many Ultris i $gzabił:zabiła; Dimensiusa Wszechpożeracza!', '', 'Wróć do profesora Dabiriego w Strażnicy Protektoratu w Burzy Otchłani.', '', 'Rozmowa z kapitanem Saeedem', '', '', 0),
(10440, 'plPL', 'Sukces!', 'Test zakończył się pełnym sukcesem! Z pewnością możemy użyć tego urządzenia, żeby zacząć naprawiać kopuły.$B$BZanieś wieść o wynikach testu do Burzowej Iglicy i daj znać Ghabarowi, że znalazłem też prawidłowość w uszkodzeniach generatorów osłon. W wielu miejscach zniknęły kluczowe części generatorów. To nie przypadek, $N, ani awaria techniczna. Ktoś nas okrada.', 'Wróć do Ghabara w Burzowej Iglicy w Burzy Otchłani.', '', '', '', '', '', '', 0),
(10441, 'plPL', 'Upłynnianie towaru', '<Audi znów zniża głos.>$B$BSkoro mamy już towar, większość części wyślę do Strefy 52. Jest tu dość na więcej niż jeden generator, a to dla nas doskonała okazja do interesu.$B$BWidziałam, jak przedstawicielka Ekspedycji Cenariońskiej próbuje negocjować. Chcę, żebyś $gdał:dała; jej znać, że możemy dostarczyć to, czego szuka, po bardzo rozsądnej cenie. Nie ma powodu, żeby dalej układała się z tymi dwulicowymi eterykami.', 'Porozmawiaj z Aurine Księżycożar u podnóża Burzowej Iglicy w Burzy Otchłani.', '', '', '', '', '', '', 0),
(10508, 'plPL', 'Prezent dla Voren\'thala', 'Nie chcę wysyłać cię do Voren\'thala z pustymi rękami. Rozczarowywanie to nie w moim stylu.$B$BAby dostać się do Siedziby Socrethara na północy, musimy skorzystać z jego własnych teleporterów – zablokowanych kamieniem teleportacyjnym Socrethara. Pierwsza połowa kamienia jest w posiadaniu mistrza kuźni Moruga w Bazie Kuźniczej Zapomnienie. Drugą połowę ma demon Silroth w Bazie Kuźniczej Gehenna.$B$BZdobądź je, a Voren\'thal będzie pod wrażeniem, którego nie da się opisać słowami.', 'Mistrz szpiegów Thalodien w Strefie 52 chce, żebyś $gzdobył:zdobyła; pierwszą połowę Kamienia Socrethara od mistrza kuźni Moruga w Bazie Kuźniczej Zapomnienie i drugą połowę Kamienia Socrethara od Silrotha w Bazie Kuźniczej Gehenna.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do mistrza szpiegów Thalodiena w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10652, 'plPL', 'Za liniami wroga', 'Wszystko już przygotowane, by zabrać cię tam, gdzie ukrywają się nasi szpiedzy. Przyjdź do mnie, gdy będziesz $ggotów:gotowa;, a wyprawimy cię w drogę.', 'Porozmawiaj z Veronią, gdy będziesz $ggotów:gotowa; do wyruszenia do Kuźni Many Coruu. Na miejscu porozmawiaj z Caledisem Jasnoświtem.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', '', '', '', '', '', 0),
(10701, 'plPL', 'Rozbicie Otchłanioskała', 'Do każdego, komu zależy na terminowej budowie Rakiety Otchłani X-52 –$B$BKról miejscowych górskich olbrzymów, Otchłanioskał, terroryzuje Kruszące się Pustkowie. Przeszkadza w pracach wzdłuż całej południowej krawędzi wyspy!$B$BWeź przyjaciół i rozpraw się z nim! Potem wróć do mnie, tutaj, do Strefy 52.$B$BRakietowódz Kadłubek', 'Zabij Otchłanioskała, a potem zamelduj się u rakietowodza Kadłubka w Strefie 52 w Burzy Otchłani.', '', 'Wróć do Rakietowodza Kadłubka w Strefie 52 w Burzy Otchłani.', '', '', '', '', 0),
(10850, 'plPL', 'Gaz Otchłani w silniku na spaczony ogień', '', '', '', 'Wróć do nieaktywnego Grabieżcy Spaczenia w Burzy Otchłani.', '', '', '', '', 0),
(10855, 'plPL', 'Grabieżcy Spaczenia? Nie, dziękuję!', 'Ach, tak – Grabieżca Spaczenia! Z pewnością najstraszliwszy mechaniczny twór Legionu. Na Burzową Iglicę wymierzone są co najmniej trzy te plugastwa.$B$BNa szczęście nie są jeszcze aktywne. Dzięki temu możemy się z nimi rozprawić sabotażem zamiast brutalnej siły.$B$BZdobądź skondensowany gaz Otchłani od gan\'argów w Bazie Kuźniczej Zapomnienie i napełnij nim zbiornik paliwa pobliskiego Grabieżcy Spaczenia. Przeczuwam, że jego silnik nie zniesie tego zbyt dobrze.', 'Zdobądź 5 porcji skondensowanego gazu Otchłani od gan\'argów mechinżynierów w Bazie Kuźniczej Zapomnienie, na północny zachód od Burzowej Iglicy, i załaduj je do pobliskiego nieaktywnego Grabieżcy Spaczenia. Po wykonaniu tego zadania wróć do tropiciela Otchłani Nauthisa.', '', 'Wróć do tropiciela Otchłani Nauthisa w Burzowej Iglicy w Burzy Otchłani.', '', 'Zniszczenie nieaktywnego Grabieżcy Spaczenia', '', '', 0),
(10856, 'plPL', 'Najlepsza obrona', 'Odważne akty sabotażu przemysłowego zaprowadzą nas tylko do pewnego momentu, $N. Tak jak Baza Kuźnicza Zapomnienie służy za montownię Grabieżców Spaczenia, tak Baza Kuźnicza Gehenna jest dla ich armii punktem zbornym, bo znajduje się tam większość urządzeń teleportacyjnych Legionu.$B$BChcę, żebyś tam $gwszedł:weszła; i $gprzetrzebił:przetrzebiła; ich szeregi. Muszą już mieć pełny regiment gniewonośców, a na to po prostu nie możemy pozwolić.', 'Tropiciel Otchłani Nauthis chce, żebyś $gzabił:zabiła; 12 gniewonośców w Bazie Kuźniczej Gehenna, na północ od Burzowej Iglicy.', '', 'Wróć do tropiciela Otchłani Nauthisa w Burzowej Iglicy w Burzy Otchłani.', '', '', '', '', 0),
(10857, 'plPL', 'Teleportuj to sobie!', 'Zabijanie demonów może i jest zabawne, ale na niewiele się zda, skoro Legion może dalej używać teleporterów, by zastąpić każdego, kogo zabijemy.$B$BNiestety nie mam pod ręką żadnych silnych materiałów wybuchowych... ale mo\'argowie, którzy obsługują teleportery, mają.$B$BWeź ten pręt... Dostroiłem jego moc tak, by zakłócała częstotliwości mózgowe mo\'argów. Wróć do Bazy Kuźniczej Gehenna i użyj go na każdym mo\'argu, którego zobaczysz. Nie będziesz mieć wiele czasu, ale zdołasz użyć ich ładunków burzących na pobliskich teleporterach.', 'Tropiciel Otchłani Nauthis chce, żebyś $gużył:użyła; pręta zakłóceń umysłowych na mo\'argach w Bazie Kuźniczej Gehenna, a potem ich zdolności Zdetonowanie teleportera na trzech teleporterach w obozie kuźni.', '', 'Wróć do tropiciela Otchłani Nauthisa w Burzowej Iglicy w Burzy Otchłani.', 'Zniszczenie zachodniego teleportera', 'Zniszczenie środkowego teleportera', 'Zniszczenie wschodniego teleportera', '', 0),
(10924, 'plPL', 'Krwawa chochlikada!', 'Krew tutejszych ścigaczy wypaczenia to potężny i rzadki odczynnik. Jeden z moich najlepiej sprzedających się towarów.$B$BZwykle zabieram do pomocy przy jej zbieraniu mojego chochlika Zeppita. Krew ścigacza wypaczenia jest zbyt żrąca, by ktoś taki jak ty czy ja mógł bezpiecznie się z nią obchodzić, ale Zeppitowi to nie przeszkadza.$B$BW sklepie robi się coraz tłoczniej, więc jeśli poślę z tobą Zeppita, pomożesz zebrać krew? Uwaga Zeppita lubi błądzić, więc musisz być blisko ścigacza, kiedy ten zginie, żeby Zeppit mógł zrobić swoje.', 'Przynieś 8 fiolek krwi ścigacza wypaczenia Sab\'aothowi w Kosmokluczu.', '', 'Wróć do Sab\'aotha w Kosmokluczu w Burzy Otchłani.', '', '', '', '', 0),
(10969, 'plPL', 'Odszukaj Ameera', 'Wygląda na to, że ktoś z zewnątrz zainteresował się praktykami handlowymi Konsorcjum. W ciągu ostatnich dwóch dni zaginęło pięciu handlarzy Konsorcjum. Mamy powody sądzić, że stoi za tym Eterium. Jeśli chcesz pomóc, odszukaj dowódcę Ameera w Strażnicy Protektoratu.$B$BStrażnicę Protektoratu znajdziesz dokładnie na wschód stąd, na sąsiedniej wyspie.$B', 'Odszukaj dowódcę Ameera w Strażnicy Protektoratu.', '', '', '', '', '', '', 0),
(10970, 'plPL', 'Misja miłosierdzia', 'Tę kulę więzienną odzyskaliśmy podczas naszego ostatniego zwiadu na terytorium Eterium. Nigdy byśmy jej nie znaleźli, gdyby nie sygnał alarmowy, który słabo wysyłała.$B$BSądzimy, że ktoś z naszych może być w niej zamknięty, ale nie da się otworzyć kuli, nie krzywdząc tego, kto jest w środku.$B$BWiemy o Eterium tyle, że każdy z jego członków może w dowolnej chwili mieć przy sobie klucz do otwarcia kuli. Zdobądź jeden i wróć, żebyśmy mogli odkryć tajemnice tej kuli.', 'Zdobądź odzyskany klucz do więzienia z eterium dla dowódcy Ameera w Strażnicy Protektoratu w Burzy Otchłani.', '', 'Wróć do dowódcy Ameera w Strażnicy Protektoratu w Burzy Otchłani.', '', '', '', '', 0),
(10971, 'plPL', 'Sekrety Eterium', '<Ameer unosi identyfikator.>$B$BZnalazłem ten identyfikator więźnia przy szczątkach poległego awangardzisty. Mogę tylko przypuszczać, że wszyscy ich więźniowie są oznaczani w ten sam sposób.$B$BZacznę katalogować identyfikatory w nadziei, że zrozumiem ich system więzienny. Jeśli podczas swoich przygód znajdziesz więcej kluczy do więzień Eterium, możesz nimi otwierać więzienia z eterium na Placu Zbornym Eterium – dokładnie na południe stąd. Przynoś mi wszystkie identyfikatory, jakie znajdziesz.', 'Dowódca Ameer w Strażnicy Protektoratu w Burzy Otchłani chce, żebyś $gprzyniósł:przyniosła; mu identyfikator więźnia Eterium.', '', 'Wróć do dowódcy Ameera w Strażnicy Protektoratu w Burzy Otchłani.', '', '', '', '', 0),
(10972, 'plPL', 'Katalog identyfikatorów więźniów Eterium', 'Potrzebuję więcej identyfikatorów, $N. Jak dotąd odkryłem, że to nie tylko sposób na katalogowanie więźniów, ale i zapis miejsc!$B$BGdy złamiemy ten szyfr, ustalimy dokładnie, gdzie są przetrzymywani wszyscy nasi sojusznicy, i uwolnimy ich przy jak najmniejszym oporze wroga.', '', '', 'Wróć do dowódcy Ameera w Strażnicy Protektoratu w Burzy Otchłani.', '', '', '', '', 0),
(10973, 'plPL', 'Tysiąc światów', 'Złamałem szyfr! Każdy identyfikator dzieli się na kilka części. Przód zawsze jest taki sam i głosi: „Tysiąc światów...”. Nie wiem, co to zdanie znaczy, ale brzmi złowieszczo.$B$BNa odwrocie są najważniejsze dane. Pierwszy zestaw run oznacza miejsce, a drugi rodzaj więźnia. Co więcej, wygląda na to, że klucze można połączyć w specjalny klucz, który otwiera inny rodzaj więzienia. Teraz potrzebuję tylko więcej kluczy...', 'Dowódca Ameer w Strażnicy Protektoratu w Burzy Otchłani chce, żebyś $gprzyniósł:przyniosła; mu 5 kluczy do więzienia z eterium.', '', 'Wróć do dowódcy Ameera w Strażnicy Protektoratu w Burzy Otchłani.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(10173, 'plPL', 'Ach, więc udało ci się odzyskać kostur. Imponujące, $N. Być może to ciebie szukałem.$B$BA tak, twoja nagroda...$B$B<Ravandwyr wciska ci w dłoń kilka monet.>$B$BZapewne $gspodziewałeś:spodziewałaś; się więcej, ale i to przyjdzie z czasem. Na razie za prawdziwą nagrodę uznaj samą szansę.', 0),
(10174, 'plPL', '<Wizerunek arcymaga Vargotha przygląda ci się, gdy przekazujesz wiadomość od Ravandwyra.>$B$BRavandwyr jest wszystkim, czego mistrz może oczekiwać od ucznia. Gdy dałem mu kostur i kazałem uciekać, miałem nadzieję, że użyje go, by znaleźć pomoc i uwolnić mnie, kiedy siły Kael\'thasa wycofają się z wieży. Od tamtej pory wiele się dowiedziałem o naturze klątwy.$B$BMożna ją złamać, $N, ale potrzebuję do tego twojej pomocy.', 0),
(10176, 'plPL', 'Dobra robota, $N. Zniszczenie pola tłumiącego znacznie ułatwi mi przygotowanie czaru, który wreszcie zdejmie z wieży klątwę.', 0),
(10182, 'plPL', 'Dobra robota, $N. Nie wyczuwam już niepokoju w duchu Dathrica. Wiele bym dał, by móc jeszcze raz z nim porozmawiać, ale wystarczy, że wreszcie zaznał spokoju.', 0),
(10183, 'plPL', 'O, Miedziogrosz w końcu raczył zdać raport ze swoich odkryć, tak? Leniwi naukowcy!$B$BCo to?$B$B<Szef kilka razy przerzuca notatki z wyraźnym niedowierzaniem.>$B$BPisze tu, że gwałtowne energie Otchłani przepływające przez Burzę Otchłani już za kilka miesięcy rozerwą wszystko na strzępy.$B$BTo niewygodne – teraz trzeba będzie przyspieszyć harmonogram budowy statku rakietowego!', 0),
(10184, 'plPL', 'Nie na to zasłużyli, ale nic więcej nie możemy zrobić.', 0),
(10185, 'plPL', '<Kustosz wygląda na strapionego.>$B$BJuż widzę następną falę nadciągającą zza horyzontu. Przetrzebianie ich na razie wystarczy, ale potrzebne są trwalsze rozwiązania.', 0),
(10186, 'plPL', 'Ech! Kiepsko wyglądają. Może przydadzą się w trzeciorzędnej komorze kolektora silnika?$B$BMimo wszystko dobra robota, $gmłodszy techniku:młodsza techniczko; 3. stopnia! Ani się obejrzysz, a awansujesz na 2. stopień.', 0),
(10188, 'plPL', 'Ach, jest tak wspaniały, jak go zapamiętałem. Czy nie czujesz bijącej od niego mocy?$B$BOczywiście wiele jeszcze przed nami, ale z głębi serca dziękuję ci za odzyskanie symbolu.', 0),
(10189, 'plPL', 'Doskonale! Dzięki tej liście będziemy mogli rozważniej wybierać cele spośród popleczników Kaela w kuźniach many.$B$BSzkoda, zaczynało mi się podobać zabijanie jego pachołków jak popadnie.', 0),
(10190, 'plPL', 'Hej, uważaj, gdzie tym celujesz! Masz ustawione na „Zabij”!!!$B$BWygląda na to, że $gnaładowałeś:naładowałaś; baterię, i to z nawiązką. To bardzo pomoże utrzymać tych gości na chodzie.', 0),
(10191, 'plPL', 'Udało się! Udało się! Mogłabym cię wyściskać!$B$BOch, kurczę... Maxx A. Million Mk. V znowu ma pustą baterię. Trudno, starczyło mu prądu, żeby wykonać robotę, i to się liczy!$B$BRakietowódz Kadłubek się ucieszy, kiedy podłączy te maszyny draenei w Rakiecie Otchłani X-52! To oznacza dla mnie awans! Jestem taka szczęśliwa, że po prostu muszę dać ci nagrodę!$B$BProszę, wybierz sobie coś z tego.', 0),
(10192, 'plPL', '<Wizerunek arcymaga Vargotha zdaje się oglądać kompendium.>$B$BJest trochę sfatygowane, ale zważywszy na to, co przeszło, to cud, że przetrwało w całości. Strzeż go, $N. Bez niego mamy marne szanse na przełamanie bariery wieży.', 0),
(10193, 'plPL', 'Można na tobie polegać, $N. Jeśli coś lubię bardziej od zabijania piesków Kaela, to to, że ktoś robi to za mnie.$B$BMniej krwi na ubraniu.', 0),
(10194, 'plPL', 'Załatwienie twojego lotu nie było tanie. Miejmy nadzieję, że masz to, czego trzeba, by wykonać zadanie.', 0),
(10197, 'plPL', 'Doskonale! Kiedy z tobą skończę, wmieszasz się niezauważenie w szeregi Słonecznej Furii.', 0),
(10198, 'plPL', 'Kuźnia Many Duro ma kłopoty? Thalodien z pewnością chętnie o tym usłyszy. Najpierw jednak dokończmy robotę tutaj.', 0),
(10199, 'plPL', 'Rany! No, teraz to rozumiem!$B$BDaj mi tylko te ślicznotki, a wycisnę z nich całe paskudztwo. Z tego powinien wyjść rakietowy wywar paliwowy, od którego wszystkim kapcie pospadają!$B$BCzekaj, tylko zmieszam olej łupkowy z tym jadem z żądeł i zobaczymy, co się stanie...', 0),
(10200, 'plPL', 'Nie przestajesz mnie zadziwiać, $N. To był nie lada popis skradania się w Kuźni Many Coruu.', 0),
(10202, 'plPL', 'Najwyższy czas, żebyś się $gzjawił:zjawiła;. Zaczynałem się zastanawiać, czy Widzący w ogóle są zainteresowani.', 0),
(10203, 'plPL', 'To pewnie ty $gprzesłałeś:przesłałaś; nam tu z ruin cały ten sprzęt saperski! Hura!$B$BJuż rozesłałem sprzęt do naszych pozostałych punktów. Teraz przyspieszymy prace w szczelinach na całej wyspie o rząd wielkości! Rakieta Otchłani będzie gotowa w mgnieniu oka!$B$BHmmm, to dziwne. Chwileczkę, mówisz, że $gwysłałeś:wysłałaś; nam cztery rzeczy? Dotarły tylko trzy...', 0),
(10204, 'plPL', 'Hmmm... tak jak podejrzewałam.$B$BKontakt z tak silną, surową energią znacznie potęguje nasze wrodzone uzależnienie od magii.$B$BNic dziwnego, że Kaelowi uchodzi na sucho to, co robi; wszyscy jego podwładni są tym po prostu upojeni.', 0),
(10205, 'plPL', 'Ulga słyszeć, że z tą szumowiną wreszcie koniec. Dobrze się spisujesz, $N... mogę być tak śmiały i mówić ci po imieniu?$B$BJeśli zechcesz, mam kolejne zadanie. Bardzo ważne, a ktoś o twoich oczywistych umiejętnościach powinien sobie z nim łatwo poradzić.', 0),
(10206, 'plPL', 'Hehe, frajerzy z tych eteryków!$B$BDzięki, że $gzdobyłeś:zdobyłaś; dla nas te części, $N. Założę się, że te maleństwa da się podłączyć prosto w rakiecie. Ciekawe, do czego służą? Sprawdzanie będzie niezłą zabawą!$B$BHmm, zobaczmy, czy znajdę trochę drobnych, żeby ci rzucić.', 0),
(10209, 'plPL', '<Nie masz pewności, czy to tylko zakłócenia, czy arcymag naprawdę się uśmiecha.>$B$BSkoro odzyskałem ostatnią z moich rzeczy, mam wszystko, czego potrzebuję, by przełamać magię Kael\'thasa. Natychmiast zabieram się do zaklęcia.', 0),
(10221, 'plPL', 'Zawsze będę tęsknił za Sparkym. <pociąga nosem> Ale teraz wszyscy będziemy spać spokojniej, wiedząc, że jako Doktor Huk już nas nie terroryzuje!$B$BNiech to będzie dla ciebie nauczka. Nie schodź tu bez hełmu chroniącego przed Otchłanią!$B$BA teraz, jak mogę ci się odwdzięczyć?', 0),
(10222, 'plPL', 'To, czego dziś $gdokonałeś:dokonałaś;, nigdy nie przywróci poległych, ale może pomoże ukoić ich dusze. Choć prawdę mówiąc, żadna ilość krwi nie ugasi mojego gniewu za czyny Kael\'thasa.', 0),
(10223, 'plPL', '<Nie masz pewności, ale wydaje się, że kustosz Dieworth jest bliski łez.>$B$BWreszcie koniec. Gdybym mógł siłą woli przestać istnieć, zrobiłbym to, ale prawda jest taka, że nie wiem, jak odejść. Tym w wiosce jest ciężko, ale przynajmniej ich droga jest prosta. Przypuszczam, że to cena, jaką płacimy za tak silne więzi z tym miejscem.', 0),
(10224, 'plPL', 'Rany, ale dużo esencji!$B$BDobra, zobaczmy, co się stanie, jak zmieszam ją z kryształami matrycy z eterolitu.', 0),
(10225, 'plPL', 'Ooo, kryształy matrycy z eterolitu. No, brzmi poważnie!$B$BPołóżmy je tutaj, zaraz się zabiorę do ich rozgryzania.', 0),
(10226, 'plPL', 'To rozumiem! Dobra, teraz chyba możemy działać.$B$BTylko wrzucę to do tego czegoś', 0),
(10232, 'plPL', 'Cóż, to dobra i zła wiadomość zarazem, prawda? Zadaliśmy im cios, ale z Płonącym Legionem, który hasa sobie po całej Burzy Otchłani – i podchodzi do nas coraz bliżej – no, nie wiem, jak to się potoczy.$B$BMam przeczucie, że przez jakiś czas trzeba będzie zmienić bieg. Mam nadzieję, że nam pomożesz, $N.', 0),
(10233, 'plPL', 'Kirin Tor nie gustuje w niszczeniu dla samego niszczenia, ale nie mamy skrupułów, gdy trzeba wystąpić przeciw wrogom, nawet po śmierci.', 0),
(10234, 'plPL', 'Na razie muszą wystarczyć. Gdybyśmy tylko mogli ich przepłoszyć.$B$BHej, to podsuwa mi pewien pomysł!', 0),
(10235, 'plPL', 'On, eee... powiedział co? PÓJDĄ NA STREFĘ 52?!$B$BOch, to niedobrze... bardzo niedobrze!', 0),
(10237, 'plPL', 'He, żartujesz, prawda? Płonący Legion obwinia nas o to wszystko?$B$BPrzecież to TY to $gzrobiłeś:zrobiłaś;!$B$BOj, boli mnie głowa, i to wielka jak ta rakieta. Dobra, dobra, trzeba zmienić plany.$B$BJeśli Płonący Legion myśli, że przyjdzie tu, zniszczy nasze miasto i zrujnuje moje marzenie o podróży przez Wypaczoną Otchłań, to się grubo myli.$B$BI znam właściwego goblina, który nam pomoże.', 0),
(10239, 'plPL', 'Chyba nigdy nie widziałem czegoś takiego. Jest tu uwięzione mnóstwo energii, ale w surowej postaci. Trzeba się z nią obchodzić ostrożnie, ale chyba znajdziemy sposób, by przystosować ją do odpierania istot many.', 0),
(10240, 'plPL', 'Świetna robota. Trzymaj kciuki, $N. Aktywuję tarczę.', 0),
(10241, 'plPL', 'Świetna robota, $N. Dzięki twojej dywersji Widzący zdobyli cenne informacje. Może tym razem naprawdę się nimi z nami podzielą.', 0),
(10243, 'plPL', 'Rozwijasz zwój i przygotowujesz się do przepisania dziwnych symboli.', 0),
(10245, 'plPL', 'Dobra robota, $N. Daj mi chwilę na przejrzenie twojego zapisu.$B$BKapłaństwo jest ci wdzięczne, $N.', 0),
(10246, 'plPL', 'Świetna robota, $N. Dzięki twojemu oddaniu na pewno pokonamy wroga.', 0),
(10247, 'plPL', 'No, no, wygląda na to, że mamy szczęście, $gmłodzieńcze:moja panno;.$B$BWłaśnie niedawno ukończyłem budowę mojego najnowszego wynalazku, złomowego grabieżcy X6000!$B$BA ty będziesz $gmiał:miała; zaszczyt pomóc mi go przetestować, by mógł posłużyć do obrony Strefy 52!', 0),
(10248, 'plPL', 'No, $gmój chłopcze:moja droga;, to było naprawdę ekscytujące! I moim zdaniem złomowy grabieżca X6000 spisał się znakomicie, mimo żółtodzioba za sterami.$B$BHehe, nie, nie obrażaj się, tylko żartowałem. W końcu właśnie $guratowałeś:uratowałaś; Strefę 52 i Rakietę Otchłani X-52 przed pewną zgubą!', 0),
(10249, 'plPL', '$N! A może powinienem powiedzieć: $gmłodszy techniku:młodsza techniczko; 1. stopnia $N?! A, do diabła, kogo ja oszukuję? Przeskoczenie stopnia to za mała nagroda za to, czego $gdokonałeś:dokonałaś;. Mianuję cię moim pierwszym oficerem!$B$B$GUratowałeś:Uratowałaś; nas wszystkich, a co ważniejsze, Rakietę Otchłani X-52! Mógłbym cię wycałować... ale tego nie zrobię.$B$BZamiast tego pozwól, że przekażę ci wdzięczność Strefy 52. Wybieraj!', 0),
(10256, 'plPL', 'Dowódca Sarannis, powiadasz? Hmm...$B$BTo jedna z doradczyń Kael\'thasa, ale z pewnością nie magini. Pamiętam ją z ataku na Wioskę Kirin\'Var. Myślę, że twoje wrażenia są słuszne, $N. Nie podtrzymuje klątwy osobiście, ale ma do niej klucz.', 0),
(10257, 'plPL', 'Niesamowite! Po tym, co widziałem z losu Farahlonu, nie jestem pewien, czy chcę wychodzić na zewnątrz, ale to i tak znacznie lepsze niż tkwić tu uwięzionym do końca moich dni.', 0),
(10261, 'plPL', 'Hura! Wiesz, jak trudno zdobyć te rzeczy? Nie dostaję tu regularnych dostaw części.$B$BWiesz co, w ramach zapłaty weź sobie coś z mojej skrzyni z rupieciami. Na pewno znajdziesz tam coś przydatnego. A jak nie, to sprzedaj.$B$BDobra, pozwól, że to od ciebie wezmę i wstawię do mojego długoszyjnego analizatora widma, zanim to psujące się serwo w nim wybuchnie!', 0),
(10262, 'plPL', 'Te insygnia to dobry początek.$B$BNiestety podczas twojego pobytu na Hałdzie jeden z moich innych agentów wśród Zaxxis dał mi znać, że najeźdźca wypaczenia Nesaad wciąż żyje!', 0),
(10263, 'plPL', 'Witaj.$B$BCzy przypadkiem nie masz czasu na dość ważną misję odzyskania pewnej rzeczy?', 0),
(10264, 'plPL', 'Witaj.$B$BCzy przypadkiem nie masz czasu na dość ważną misję odzyskania pewnej rzeczy?', 0),
(10265, 'plPL', 'Pozwól mi to obejrzeć.$B$BHmm, nie widać w nim nic szczególnego. Wątpię, żeby to był ten, choć z tego, jak opisujesz działania Płonącego Legionu w ruinach, wygląda na to, że oni też szukają czegoś konkretnego.$B$BMiejmy nadzieję, że nie kryształu, którego tak bardzo pragnie książę Nexusa.', 0),
(10266, 'plPL', 'Tak, to prawda. Krwawe elfy wycofały się z kolejnego zakupu towarów, które już zostały dostarczone.$B$BSkoro tropiciel Otchłani Khay\'ji za ciebie poręczył, mam nadzieję, że pomożesz mi w tej sprawie.', 0),
(10267, 'plPL', 'Cóż, ja w każdym razie cieszę się, że ta drobna sprawa jest już za nami. Nie pamiętam, by Konsorcjum kiedykolwiek miało do czynienia z tak prostackimi i niegodnymi zaufania istotami.$B$BTobie natomiast chyba można bardzo ufać, $N. Może nie odmówisz mi jeszcze jednej przysługi?', 0),
(10268, 'plPL', 'Witam cię w Burzowej Iglicy, $N. Korzystaj z gościnności Konsorcjum.$B$BMożesz odłożyć ten sprzęt gdziekolwiek. Podejrzewam, że wkrótce znów go podniesiesz.', 0),
(10269, 'plPL', '<Handlarz Hazzin zniża głos do szeptu.>$B$BAch, wiem o twojej misji. Ma ona wielkie znaczenie dla księcia Nexusa Haramada!$B$BSkoro znamy już położenie pierwszego punktu triangulacyjnego, musisz szybko znaleźć drugi!', 0),
(10270, 'plPL', 'To ogniwo zasilające wystarczy na nasze potrzeby. Gdy zaczną płynąć pieniądze, jeszcze je ulepszymy.$B$BDość o tym. Każda chwila spędzona na rozmowie to stracony zysk.', 0),
(10271, 'plPL', 'I pomyśleć, że ten nędzny eteryk zamierzał sprzedawać te esencje krwawym elfom jak cukierki...', 0),
(10272, 'plPL', 'Świetnie się nadadzą, $N. Dziękuję, że $gzgodziłeś:zgodziłaś; się nam pomóc.$B$BZanim jednak pójdziemy dalej, musimy zająć się jeszcze jedną sprawą.', 0),
(10273, 'plPL', 'Skoro kłopotliwy eteryk nie stoi nam już na drodze, możemy skupić się na zrozumieniu tych smoków Otchłani. Zdążyłam zbadać jaja i dokonałam kilku odkryć.', 0),
(10274, 'plPL', 'Dobra robota, $N. Naprawdę dobra robota. Drakanie Otchłani z początku nie zaakceptują wśród siebie błękitnej smoczycy, ale z czasem, gdy stanowczo zademonstruję swoją władzę, pogodzą się z tym. Są rozproszeni, odizolowani i nie mają wyraźnego przywódcy, więc musimy czujnie pilnować, by nie ulegli wpływowi złowrogiej mocy, i cały czas trzymać ich w ryzach.', 0),
(10275, 'plPL', 'Doskonale. Książę Nexusa będzie zadowolony!$B$BMamy teraz drugi punkt, który powie nam, gdzie jest trzeci, a także gdzie mniej więcej leży kryształ!', 0),
(10276, 'plPL', 'Nawet w najśmielszych snach nie myślałem, że zdołasz odzyskać kryształ!$B$BA do tego naprawdę mi go oddać! Czy masz pojęcie, jaki jest potężny?$B$BTwoja bezinteresowność jest inspirująca i bez zarzutu, $N! $GDałeś:Dałaś; mi wiele do myślenia.', 0),
(10281, 'plPL', 'Nazywam się Tyrygosa, z rodu Malygosa, ale większość mówi na mnie „Tyri”. Mój towarzysz to Jorad Mace.$B$BWieści o tych dziwnych drakaninach rozeszły się już daleko i obawiam się, że zbyt wielu rzuci się, by czerpać z nich zyski, nie rozumiejąc prawdziwej natury tego, z czym ma do czynienia. Z twoją pomocą liczymy, że poznamy te stworzenia, zanim inni odkryją ich obecność.', 0),
(10290, 'plPL', 'Ach, tak. To dokładnie ta jakość, na którą liczyłem. Jeśli zapewnimy sobie dostawy od olbrzymów, może w ogóle zrezygnujemy z wydobycia w formacjach kryształów.', 0),
(10292, 'plPL', '<Zuben Elgenubi posyła ci coś, co można by uznać za eteryczny uśmiech.>$B$BPrzysięgam używać tej niesamowitej siły ognia wyłącznie w dobrym celu. Dla dobra mojej marży zysku, rzecz jasna.', 0),
(10293, 'plPL', 'Dobra robota! Nie mogę się doczekać, żeby to wypróbować.', 0),
(10299, 'plPL', 'Światło ci sprzyja, $N. Wszyscy modliliśmy się o twój sukces.', 0),
(10300, 'plPL', '<Ravandwyr uważnie ogląda kryształy, po czym wybiera jeden.>$B$BTen kryształ powinien się nadać. Przerobię oprawę kostura, by umocować nową głowicę.$B$BGdy arcymag Vargoth to zobaczy, będzie rozczarowany, ale zniosę rozczarowanie mistrza, jeśli dzięki temu go uwolnimy.', 0),
(10301, 'plPL', 'Doskonale, $N. Teraz mamy większość tego, czego potrzebujemy, by spróbować przełamać magię Kael\'thasa.$B$BA jeśli krwawe elfy ucierpią przez utratę miejscowej dowódczyni, tym lepiej.', 0),
(10305, 'plPL', 'Ach, tak. Słyszałem, że wypędzaczka Belmara miała starą księgę opowieści, ale nie wiedziałem, że zabrała ją ze sobą do Rubieży. Jestem pewien, że jej duch zazna więcej spokoju, wiedząc, że $godnalazłeś:odnalazłaś; księgę i $godniosłeś:odniosłaś; ją do jej domu.', 0),
(10306, 'plPL', 'Zawsze żartowaliśmy, że Luminrath nosiłby ten płaszcz niemal do wszystkiego. Według niego czerwień pasowała równie dobrze do bieli, czerni, fioletu, błękitu, żółci, pomarańczu i zieleni. Nigdy nie nosił tej samej szaty dwa dni z rzędu, ale płaszcz był zawsze...', 0),
(10307, 'plPL', '<Kustosz uśmiecha się na dźwięk imienia Cohliena.>$B$BMasz całkowitą rację co do czapki. Nosił ją cały czas i nie spuszczał jej z oka.$B$BParę razy pewien kolega mag, którego imienia nie wymienię, „pożyczył” czapkę i schował ją dla żartu. Nie trzeba dodawać, że groźba jednego z lodowych pocisków Cohliena szybko zmieniła jego zdanie.$B$BBędzie mi brakowało małego Cohliena. Miał niezłe podejście do elfek.', 0),
(10308, 'plPL', 'Zdrajcy, wszyscy co do jednego!$B$BDobra robota, $N! Jeśli jeszcze kiedyś tam trafisz, zawsze chętnie powiększę swoją kolekcję ich insygniów!', 0),
(10309, 'plPL', 'Rany, spójrz tylko... bijące serce Grabieżcy Spaczenia! No, nie tyle „bijące”, ale wiesz, o co mi chodzi.$B$BNie mogę się doczekać, aż zrobię z niego dobry użytek. Albo może je sprzedam. Znam paru frajer... eee, klientów, którzy mogą być zainteresowani.$B$BProszę, $gzarobiłeś:zarobiłaś; swoją zapłatę, i to z nawiązką!', 0),
(10310, 'plPL', 'To wspaniałe wieści, $gprzyjacielu:przyjaciółko;!$B$BTy i Drijya oddaliście nam wielką przysługę. Skoro ta brama wypaczenia nie działa, pobliskie demony nie dostaną już żadnych posiłków.$B$BPozwól, że wynagrodzę cię tak, jak przystało w Konsorcjum.', 0),
(10311, 'plPL', 'Mam nadzieję, że Gahruj przysłał cię, byś $gpomógł:pomogła; mi w mojej misji.', 0),
(10312, 'plPL', 'Hmm...$B$BWygląda na to, że miałem rację. Jest tu pewna prawidłowość.$B$BNajbardziej agresywne i niebezpieczne duchy to najpotężniejsi i najwyżej postawieni członkowie Kirin Toru, którzy mieszkali w wiosce. Mieszczanie i rzemieślnicy wydają się przy nich pomijani. Co to może znaczyć?', 0),
(10313, 'plPL', 'To poważne wieści, $N. Energie wypaczenia płynące z rurociągów są niebezpiecznie wysokie.$B$BMusimy znaleźć sposób, by wyłączyć kuźnie many, inaczej to, co zostało z Rubieży, rozpadnie się na kawałki.', 0),
(10314, 'plPL', '<Kustosz Dieworth ogląda pozostałości.>$B$BUrządzenie, które opisujesz, wygląda na nekromancki skupiacz... Powinienem był wiedzieć, że ten nicpoń, uczeń arcymaga, zniży się do czegoś takiego. Myślałem, że wyszkolenie powstrzyma go przed posunięciem się tak daleko, ale najwyraźniej się myliłem.', 0),
(10315, 'plPL', 'Wszystko, co może ich skłonić do zaprzestania tego, co robią w kuźniach many, jest dobre.$B$BZ pewnością nie da się z nimi rozsądnie rozmawiać. I jasne jest dla mnie, że cokolwiek zamierzają ich przywódcy, to szaleńcy.$B$BW zamian za wierną służbę celom Konsorcjum chciałbym ci zaoferować monety twojego świata, jeśli cię to nie urazi.', 0),
(10316, 'plPL', 'Na kwadratowym postumencie spoczywa świecąca kula. Na pierwszy rzut oka wygląda na zbiornik energii magicznej, ale jakiej energii i komu ma ona służyć?', 0),
(10317, 'plPL', '<Brygadzista mówi przyciszonym głosem.>$B$B$GPrzyszedłeś:Przyszłaś; tu, żeby mnie zabić? Hmf. No cóż, najwyraźniej eterycy nie wiedzą wszystkiego, co?$B$BTo nie mnie szukasz, uwierz mi.', 0),
(10318, 'plPL', 'Strażnik Zagłady jako nadmistrz? To dziwne! Co Płonący Legion tam robi?$B$BA więc część krwawych elfów dezerteruje. Będziemy o tym pamiętać, jeśli kiedyś spróbujemy zdobyć to miejsce siłą. Przynajmniej wyszło z tego wszystkiego coś dobrego, prawda?$B$BProszę, $N, przyjmij to z moją najgłębszą wdzięcznością.', 0),
(10319, 'plPL', 'Świetna robota, $N. Filakteria będzie kluczem do naszego zwycięstwa. Gdy staniesz do walki z Naberiusem, roztrzaskam ją i wystawię go na twoje ataki.', 0),
(10320, 'plPL', 'Pokonanie Naberiusa to wielkie osiągnięcie, $N. Nie mogę się oprzeć myśli, że mielibyśmy szansę z siłami Kael\'thasa, gdyby tamtego dnia uczeń był lojalny wobec właściwej strony.', 0),
(10321, 'plPL', 'Świetna robota. Działają już tylko dwie kuźnie many.$B$BWkrótce Kael\'thas zostanie odcięty od swojego głównego źródła mocy.', 0),
(10322, 'plPL', 'Naaru ci błogosławią, $N. Twoje oddanie sprawie nie pozostanie niezauważone ani nienagrodzone.', 0),
(10323, 'plPL', 'Płonący Legion? W sojuszu z Kael\'thasem Słońcobieżcą?$B$BTo straszne wieści. Wiele wyjaśniają z tego, co widzieliśmy tutaj i w Dolinie Cienistego Księżyca.$B$BMusimy natychmiast wysłać wiadomość do Shattrath.', 0),
(10328, 'plPL', 'Świetna robota, $N! Zobaczmy, czego można się dowiedzieć z tych odpraw.', 0),
(10329, 'plPL', 'Oczywiście, że zadziałało! Jestem mistrzem szpiegów; moje informacje są zawsze dokładne.$B$BTak czy owak, mam dla ciebie zupełnie nowe, ekscytujące zadanie. Chcesz o nim usłyszeć? Oczywiście, że chcesz.', 0),
(10330, 'plPL', 'Słyszeliśmy całe to zamieszanie i właśnie mieliśmy się zbierać. Dobrze widzieć, że nie $gdostałeś:dostałaś; zbyt mocno w kość.', 0),
(10331, 'plPL', 'Dzięki niebiosom! Teraz mogę wrócić do pracy. Wiem, że masz mnie za wariata, skoro pracuję nad dziełem, które da mi tytuł czeladnika, z dala od właściwej kuźni, ale nie mogę ryzykować, że któryś z pozostałych uczniów skopiuje mój projekt.', 0),
(10332, 'plPL', 'Mistrz Rhonsus nauczył mnie wszystkiego, co wiem o swoim fachu. Uczczę jego pamięć, służąc swoimi umiejętnościami mieszkańcom Kirin\'Var.', 0),
(10333, 'plPL', 'Co?! Nazwał mnie swoją „wspólniczką”? Jestem jego żoną!$B$BI powiedział, że mam cięty język! Och, jak tylko wrócę do Strefy 52, natrę mu te jego wielkie zielone uszy!$B$BAle cieszę się, że tu jesteś. W jednym miał rację: pomoc naprawdę mi się przyda!', 0),
(10334, 'plPL', '<Wyjmujesz dzwonek z plecaka, dzwonisz nim kilka razy i pokazujesz go Bessy, która chyba go rozpoznaje. Krowa pozwala zawiązać sobie sznurek dzwonka na szyi i patrzy na ciebie wyczekująco.>', 0),
(10335, 'plPL', 'Nie nabijasz mnie w bandaż, co? To wspaniałe wieści!$B$BSkoro $godwaliłeś:odwaliłaś; czarną robotę przy pomiarach, mogę zabrać swoją ekipę do ruin i zobaczyć, co da się tam zdobyć.$B$BDziękuję ci, $N.', 0),
(10336, 'plPL', 'Naprawdę wyjątkowa robota.$B$BSkoro demony Culuthasa nie żyją, Zephyrion będzie mógł bezpiecznie zabrać swoją ekipę wykopaliskową do Ruin Farahlonu.$B$BPrzyjmij te monety w dowód mojej wdzięczności.', 0),
(10337, 'plPL', 'Bessy, to ty?$B$BDziękuję, że $gsprowadziłeś:sprowadziłaś; moją Bessy, $N. Nie mógłbym bez niej żyć!', 0),
(10338, 'plPL', 'To już trzy kuźnie many, które $gwyłączyłeś:wyłączyłaś;, $N. Kael\'thas musi teraz dostawać prawdziwego szału.', 0),
(10339, 'plPL', 'Musimy zebrać wszelkie dane, jakie zgromadzili w tej okolicy.', 0),
(10341, 'plPL', 'Dobra robota, $N. Armia Kaela nie otrząśnie się łatwo z ciosu, który dziś $gzadałeś:zadałaś;.', 0),
(10342, 'plPL', 'Dobra! Składnik numer jeden mamy.$B$BA teraz, jeśli dasz radę, przejdziemy do czegoś, co doda olejowi łupkowemu tego małego kopa, którego potrzebuje, żeby wystrzelić rakietę w Wypaczoną Otchłań... albo w niebyt, zależnie od tego, co będzie pierwsze.', 0),
(10343, 'plPL', 'Bomba many?$B$B<Morran obraca odłamek w dłoniach.>$B$BTo niemal nie do pomyślenia! Nawet najtęższe umysły Dalaranu nie wymyśliłyby takiej broni. Sama skala zaburzenia musiała rozedrzeć szczelinę w Otchłani i otworzyć tym istotom drogę do naszych ziem.', 0),
(10345, 'plPL', '$GUratowałeś:Uratowałaś; moje owijacze, $N. Protektorat dowie się, czego dziś $gdokonałeś:dokonałaś;, $gprzyjacielu:przyjaciółko;.', 0),
(10348, 'plPL', 'Ciekawy wybór, prawda? Te właściwości lecznicze lepiej, żeby były cudowne. Liczę sobie mnóstwo pieniędzy za dość zwyczajnie wyglądający kwiatek.', 0),
(10353, 'plPL', 'A Ya-six? Przeżył?$B$BMiejmy, do licha, nadzieję. Nie zdołałem wysłać im posiłków... Eterium obstawia teraz cały teren.$B$BWybacz, prawie zapomniałem o twojej nagrodzie.', 0),
(10365, 'plPL', 'Płonący Legion w zmowie z Kaelem? Ha! Voren\'thal będzie miał używanie z tą informacją.$B$BMyślisz, że tysiące pielgrzymów, którzy przybyli z Azeroth, chcą być sprzymierzeńcami Płonącego Legionu? Nie sądzę!', 0),
(10380, 'plPL', 'A więc stało się. Przychodzimy tu, tropimy ich i zabijamy na rozkaz naszych panów. Nikt nie daje pardonu ani go nie oczekuje.$B$BCzasem daje to do myślenia.', 0),
(10381, 'plPL', 'Złe wieści, które przynosisz, napełniają moje serce smutkiem. Dwóch naszych najgroźniejszych wrogów łączy siły, a jeden z najdroższych synów Shattrath zszedł z właściwej drogi.', 0),
(10384, 'plPL', '<Trzymasz ogniwo danych tak, by Ameer mógł odczytać plany.>$B$BNic... Niech ich szlag! Są sprytni, ale nie tak sprytni jak Ameer!$B$BTo, o co zaraz cię poproszę, jest dość niebezpieczne. Zrozumiem, jeśli nie zechcesz kontynuować, istoto z mięsa.', 0),
(10385, 'plPL', 'Racja bytu Protektoratu w pełni się teraz potwierdziła.$B$BEterium nie przybyło tu, by polować na Dimensiusa! Przybyło, by stać się Pustką!$B$BManipulują energią Pustki w tej kuźni many, by związać własną energię z istotą zwaną tropicielem Nexusa.$B$BBez wątpienia używają protoakceleratora, by dokończyć przemianę.', 0),
(10404, 'plPL', '$GZadałeś:Zadałaś; potężny cios wrogom Światłości, $N. Dziękuję ci w imieniu własnym i Aldorów.', 0),
(10405, 'plPL', 'Świetnie! Teraz trzeba skalibrować urządzenie.', 0),
(10406, 'plPL', 'Dzięki tobie ich plany legły w gruzach! Teraz została już tylko jedna sprawa... Salhadaar.', 0),
(10407, 'plPL', 'Twoje oddanie naszej sprawie jest wzorowe, $N. Skoro mamy już kamień teleportacyjny Socrethara, pozostała do zrobienia tylko jedna rzecz.', 0),
(10408, 'plPL', 'Minęło tysiąc lat, może więcej, odkąd Salhadaar rozpoczął swoją krucjatę, by wytępić wszystko, co stanie mu na drodze. Trudno mi uwierzyć, że więcej go nie zobaczymy... $GOddałeś:Oddałaś; nam wszystkim wielką przysługę, $N, i za to zostaniesz $gnagrodzony:nagrodzona;.', 0),
(10411, 'plPL', 'Mam nadzieję, że nie jest za późno. $GZauważyłeś:Zauważyłaś; jakieś nienormalnie duże szlamy tam, gdzie spływają odpady Pustki, albo w pobliżu?', 0),
(10413, 'plPL', 'CO!? $GStanąłeś:Stanęłaś; do walki z poczwarą Pustki? I $gprzeżyłeś:przeżyłaś;?! Niesamowite!$B$BTa próbka jest warta tyle złota, ile waży. Takie znalezisko zasługuje na nagrodę.', 0),
(10417, 'plPL', 'To niepokojące. Uszkodzenia są znacznie poważniejsze, niż się wydawało. Mogę posłać do Burzowej Iglicy po narzędzia, by rozpocząć naprawy, ale to na nic, dopóki nie ustalimy, co w ogóle niszczy sprzęt.', 0),
(10418, 'plPL', 'Okolica już wygląda czyściej. Kopuły są bardzo przydatne, ale ich główną wadą jest bujny rozrost, który w niektórych miejscach wywołują, przyspieszając wzrost i rozmnażanie rodzimych gatunków.', 0),
(10422, 'plPL', 'Dziękuję, $N. Tyralius odniósł ciężkie obrażenia, ale chyba z tego wyjdzie.$B$BWspominał o polach pełnych więzień, podobnych do tego, z którego go $guwolniłeś:uwolniłaś;. Więzień pełnych stworzeń z całego wszechświata!$B$BOdezwiemy się, gdyby trzeba było je rozbić. Konsorcjum już wyraziło chęć wysłania tam kilku drużyn i pracuje nad technologią, która pokona zamki Eterium.', 0),
(10423, 'plPL', '<Przedstawiasz się i przekazujesz wyniki diagnostyki Mehrdada z Ekokopuły Środka.>$B$BMehrdad jest niewiele więcej niż technikiem, ale ma bystre oko do szczegółów. Jeśli jego obserwacje są trafne, musimy jak najszybciej przeprowadzić diagnostykę pozostałych generatorów kopuł.', 0),
(10424, 'plPL', 'Te wyniki są dokładnie takie same jak Mehrdada, ale dlaczego? Jedyne wyjaśnienie, jakie przychodzi mi do głowy, to że część sprzętu wytwarzającego kopuły uległa awarii albo zaginęła. Przez to kopuły znacznie by osłabły i straciły równowagę, tak jak pokazuje diagnostyka.', 0),
(10425, 'plPL', '<Dowódca Ameer wydaje się zadowolony.>$B$BDobra robota, istoto z mięsa! Ten żołnierz może być kluczem do rozbicia całej operacji Eterium.', 0),
(10426, 'plPL', 'Ojej! Skupienie energii kopuły najwyraźniej przyspiesza wzrost dalej, aż do punktu, w którym rodzi skrajną agresję. Jeśli zdobędziemy możliwość korzystania z tej technologii, musimy pamiętać, żeby prawidłowo ją skalibrować.', 0),
(10427, 'plPL', 'Świetna robota. Będę uważnie obserwować oznaczone przez ciebie talbuki i sprawdzę, czy dorastają tak szybko jak inne formy życia pod kopułą.$B$BGdybyśmy właściwie nad nią panowali, moglibyśmy użyć tej technologii, by przywrócić życie zniszczonym obszarom Rubieży i Azeroth.', 0),
(10429, 'plPL', 'Nawet jak na stworzenie tych rozmiarów to serce jest o wiele za duże. Z trudem nadążało za olbrzymim cielskiem. Nie wątpię, że hydra padłaby, zanim dożyłaby połowy normalnego wieku.$B$BMimo takiego ryzyka jestem zdecydowana przekonać Konsorcjum, by podzieliło się swoją technologią. Za wiele tu obietnic, by teraz się poddać.', 0),
(10430, 'plPL', 'Wygląda trochę dziwnie. Ghabar z pewnością nie myślał o Burzy Otchłani, kiedy go projektował.$B$BNie rób takiej zdziwionej miny, $N. Burza Otchłani to nic w porównaniu z niektórymi miejscami, w których pracowałem. Mimo to słabnąca kopuła zawsze budzi niepokój.', 0),
(10431, 'plPL', 'To ty jesteś całą pomocą, jaką przysyła Orelis? Musi mieć o tobie bardzo wysokie mniemanie.$B$BMiejmy to już z głowy.', 0),
(10432, 'plPL', 'To poważna sprawa, $N. Bardzo poważna!$B$BVoren\'thal będzie chciał się o tym dowiedzieć jak najszybciej.', 0),
(10433, 'plPL', 'Wspaniałe, po prostu wspaniałe! Zapłacę ci za nie najlepszą cenę! Ile chcesz za dalsze usługi?', 0),
(10434, 'plPL', '<Przedstawiasz się i mówisz Audi, że przysłał cię Shauly.>$B$BAch, tak, czekaliśmy na kogoś, kto pomoże nam, eee, przenieść trochę, hm, towaru.', 0),
(10435, 'plPL', 'Świetna robota! Najtrudniejsza część przedsięwzięcia za nami. Teraz potrzebujemy tylko sposobu, żeby przewieźć to do Strefy 52 i przy okazji zainteresować tym Ekspedycję Cenariońską. Powinno tego starczyć na nasze potrzeby i jeszcze na mały zarobek na boku.', 0),
(10436, 'plPL', 'Dobra robota. Wygląda na to, że wszystko w porządku. Możemy zaczynać.', 0),
(10437, 'plPL', 'Doskonale. Dzięki tym fragmentom skalibrujemy bombę, która zniszczy przewodnik Pustki na szczycie Ultris. Gdy przewodnik zostanie zniszczony, połączenie Dimensiusa z Pustką zostanie zerwane, a on sam będzie bezbronny!', 0),
(10438, 'plPL', 'Nadszedł czas, by uderzyć! Skoro rozdarcia już nie ma, Dimensius jest podatny na ataki fizyczne i magiczne!', 0),
(10439, 'plPL', 'Od tysiąca lat znamy tylko wojnę. Broniliśmy naszego ludu przed atakami zarówno stworzeń Pustki, jak i eteryków.$B$BTeraz jeden z naszych najbardziej znienawidzonych wrogów nie żyje – nareszcie.$B$BPrzekazuję ci podziękowania stu milionów eteryków, istoto z mięsa.', 0),
(10440, 'plPL', 'Każę moim technikom od razu zabrać się do tych napraw.$B$BNiepokoją mnie jednak podejrzenia Tashara o sabotaż. Nie przychodzi mi do głowy nikt na tyle zuchwały, by kraść naszą technologię. W każdym razie nikt, kto wie, do czego jesteśmy zdolni. Może czas zamknąć Burzową Iglicę na cztery spusty.', 0),
(10508, 'plPL', 'Nie przestajesz mnie zadziwiać, $N! Dobrze, że jesteś po naszej stronie.', 0),
(10652, 'plPL', 'Witaj, $N. Postaraj się nie zdradzić naszej kryjówki.$B$BNie przetrwalibyśmy długo, gdyby poplecznicy Kaela nas wywęszyli.', 0),
(10701, 'plPL', 'Och! Och... $gzałatwiłeś:załatwiłaś; Otchłanioskała. To dobra wiadomość!$B$BSkoro ten kłopotliwy górski olbrzym zniknął z pola widzenia, łatwiej nam będzie eksploato... eee, gospodarować zasobami Kruszącego się Pustkowia.$B$BCieszę się, że te biedne, niewinne żywiołaki na dole nie będą już przez niego rozgniatane.$B$BJakże mogę ci się odwdzięczyć?', 0),
(10850, 'plPL', 'Silnik Grabieżcy Spaczenia zaczyna dudnić i się krztusić, gdy podajesz mu niewłaściwe paliwo.', 0),
(10855, 'plPL', 'To doskonała wiadomość, $N. Skoro wiemy już, jak sobie z nimi radzić, mogę zlecić najemnikom sabotaż pozostałych grabieżców.', 0),
(10856, 'plPL', 'Dobra robota, $N. Tak trzymaj, a szepnę o tobie dobre słowo księciu Nexusa.', 0),
(10857, 'plPL', 'Dzięki tobie, $N, odetchnę trochę swobodniej. To tylko taka przenośnia, rzecz jasna!$B$BPewnie chcesz teraz jakiejś nagrody.', 0),
(10899, 'plPL', 'Świetna robota, $N! Te transmutacje są doskonałe pod każdym względem!$B$BTeraz nauczę cię, jak alchemiczny proces transmutacji może wyczarować materię z powietrza! Zrób dobry użytek ze swojej wiedzy, $gmistrzu:mistrzyni; transmutacji.$B$BA teraz wybacz, muszę się spotkać z kupcem zainteresowanym pierwotną potęgą.', 0),
(10924, 'plPL', 'To powinien być dość duży zapas na moje potrzeby.$B$BMam nadzieję, że chochlik nie sprawiał ci zbyt wielu kłopotów. Ma dość niewyparzoną gębę.', 0),
(10969, 'plPL', 'Tak, to prawda, ale Konsorcjum nie jest jedynym, kto ponosi straty.', 0),
(10970, 'plPL', 'Odsuń się, $N. To może być pułapka Eterium.', 0),
(10971, 'plPL', 'Wygląda na to, że to coś więcej niż zwykły identyfikator. Na tych plakietkach jest zapisany jakiś szyfr. Jestem o krok od jego złamania. Może gdybym miał jeszcze kilka sztuk.', 0),
(10972, 'plPL', 'Jesteśmy blisko prawdy, $N.', 0),
(10973, 'plPL', '<Ameer zręcznie łączy klucze i zaczyna odczytywać znaki na nowo powstałej tabliczce klucza.>$B$B„Tysiąc światów zgruchotanych, tysiąc kolejnych do pokonania... Taka jest wola Króla Nexusa”.$B$B<Ameer odwraca tabliczkę i zaczyna czytać z drugiej strony.>$B$BKomory stazy Bash\'ira?', 0),
(11759, 'plPL', 'Zbezcześć wielkie ognisko Przymierza w Burzy Otchłani!', 0),
(11799, 'plPL', 'Zbezcześć wielkie ognisko Hordy w Burzy Otchłani!', 0),
(11830, 'plPL', 'Uczcij płomień Burzy Otchłani!', 0),
(11835, 'plPL', 'Uczcij płomień Burzy Otchłani!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(10173, 'plPL', 'Nie spocznę, dopóki arcymag Vargoth nie odzyska swojego kostura. Udało ci się wyrwać go z łap demona?', 0),
(10176, 'plPL', 'Wreszcie się spotykamy.', 0),
(10182, 'plPL', 'Co $gznalazłeś:znalazłaś;, $N?', 0),
(10183, 'plPL', 'Praca, praca. Nie ma czasu do stracenia! Trzeba zbudować statek rakietowy!$B$BCzego chcesz?', 0),
(10184, 'plPL', 'Boli mnie świadomość, że tak niewiele możemy zrobić dla naszych towarzyszy.', 0),
(10185, 'plPL', 'Udało ci się oczyścić ruiny wioski choć z części istot many?', 0),
(10186, 'plPL', 'Czy wygląda na to, że Rakieta Otchłani X-52 jest gotowa do startu? Czy przemierzam Wypaczoną Otchłań w wygodnym fotelu dowódcy? Eksploruję dziwne, nowe światy? Szukam nowych technologii i okazji do interesów? Śmiało zmierzam tam, gdzie nie dotarł jeszcze żaden goblin?$B$BNie!$B$BMam więc nadzieję, że masz kryształy, po które cię posłałem.', 0),
(10188, 'plPL', 'Jeśli mam się uwolnić od klątwy wieży, muszę mieć symbol.', 0),
(10189, 'plPL', 'Masz to, o co prosiłem, $N?', 0),
(10190, 'plPL', '$GNaładowałeś:Naładowałaś; już baterię w tym blasterze?', 0),
(10191, 'plPL', 'Już z powrotem?$B$BCzy z Maxxem A. Millionem Mk. V wszystko w porządku?!', 0),
(10192, 'plPL', '$GPrzyniosłeś:Przyniosłaś; księgę?', 0),
(10193, 'plPL', 'Jak idzie, $N? Masz jakieś wieści? Co ostatnio dla mnie $gzrobiłeś:zrobiłaś;?', 0),
(10197, 'plPL', '$GZdobyłeś:Zdobyłaś; części stroju, o które prosiłem?', 0),
(10198, 'plPL', 'Jak idzie podsłuchiwanie, $N? Lepiej się pospiesz. Zaczynam się tu niecierpliwić.', 0),
(10199, 'plPL', 'Jeśli zdołam wycisnąć jad z dość wielu żądeł płaszczek Otchłani, to chyba będziemy mieć najbardziej wybuchowe paliwo, jakie kiedykolwiek wymyślono!', 0),
(10203, 'plPL', 'Czy to miejsce nie jest wspaniałe? Codziennie znajdujemy coś nowego i egzotycznego!$B$BCo za szczęście, że kopiąc tu, omal nie zniszczyliśmy miasta.', 0),
(10204, 'plPL', '$GZbadałeś:Zbadałaś; krwawe klejnoty, których używają magistrowie Słonecznej Furii, $N?', 0),
(10205, 'plPL', 'Więc to koniec? Najeźdźca wypaczenia Nesaad nie żyje?', 0),
(10206, 'plPL', 'Już wracasz z ich sprzętem? Lepiej, żebyś mnie nie $gnabierał:nabierała;, $N.$B$BPowodzenie projektu X-52 zależy od tego, czy dostarczysz nam ten sprzęt, i to migiem!', 0),
(10209, 'plPL', '$GZdobyłeś:Zdobyłaś; Kamień Glaciusa?', 0),
(10221, 'plPL', 'Czy $guwolniłeś:uwolniłaś; nas od łupieżczych wybryków Doktora Huka? Obiecuję, że tym razem nie będzie wybuchających wozów, choć to była świetna zabawa!$B$BNaprawdę powinniśmy to częściej robić.', 0),
(10222, 'plPL', 'Czy to już zrobione, $N? $GPomściłeś:Pomściłaś; poległych z Wioski Kirin\'Var?', 0),
(10223, 'plPL', '$GWykonałeś:Wykonałaś; zadanie, $N?', 0),
(10224, 'plPL', 'Masz już wszystkie esencje?', 0),
(10225, 'plPL', 'Eee, cześć. Jestem trochę zajęty. Co tam masz?', 0),
(10226, 'plPL', 'Masz już moc z tych żywiołaków? Och, nie spiesz się czy coś. Chodzi tylko o moje życie i karierę.', 0),
(10232, 'plPL', 'Mam nadzieję, że dasz radę w tej przepychance z Płonącym Legionem.$B$BNiewiele rzeczy nienawidzę bardziej niż tych, którzy wycofują się z umowy, albo <kaszle> gnomów, ale demony z pewnością do nich należą!', 0),
(10233, 'plPL', 'Nad umocnieniami Warowni Słonecznej Furii unosi się dym. Czy to twoje dzieło?', 0),
(10234, 'plPL', 'Masz już te części? Płonący Legion zajmuje po kolei każdą naszą działkę w okolicy, więc niestety mamy mało czasu.', 0),
(10235, 'plPL', '$GRozprawiłeś:Rozprawiłaś; się już ze Szponem Zagłady?', 0),
(10239, 'plPL', 'Udało ci się zdobyć któreś z ich źródeł energii?', 0),
(10240, 'plPL', '$GAktywowałeś:Aktywowałaś; wszystkie runy? Chętnie zobaczę, czy uda nam się ulepszyć metodę krwawych elfów. Co potrafi jeden z ludzi Kael\'thasa, prawdziwy mag Kirin Toru potrafi lepiej.', 0),
(10243, 'plPL', 'Symbole przesuwające się przed tobą wyglądają obco i niezrozumiale.', 0),
(10245, 'plPL', 'Zobaczmy, co nam $gprzyniosłeś:przyniosłaś;, $N.', 0),
(10248, 'plPL', 'Co o tym sądzisz? Trzeba go jeszcze trochę podrasować, co?', 0),
(10257, 'plPL', '$GZdobyłeś:Zdobyłaś; zwornik?', 0),
(10261, 'plPL', 'Mam nadzieję, że przychodzisz w sprawie mojego ogłoszenia!', 0),
(10262, 'plPL', 'Czy to zrobione? $GZmiotłeś:Zmiotłaś; szumowiny Zaxxis z powierzchni Rubieży i $gprzyniosłeś:przyniosłaś; mi ich insygnia?', 0),
(10265, 'plPL', 'Mam wrażenie, że książę szuka konkretnego kryształu, ale nie wiem na pewno, jakiego.$B$BCzy $godzyskałeś:odzyskałaś; już ten od upiornego władcy?', 0),
(10267, 'plPL', 'Czy masz sprzęt mierniczy, za który krwawe elfy nie zapłaciły?', 0),
(10268, 'plPL', 'Podejdź.', 0),
(10269, 'plPL', 'Witaj, $gwędrowcze:wędrowczyni;. Przychodzisz do Hazzina, bo potrzebujesz moich towarów?', 0),
(10270, 'plPL', 'Czy jesteś już $ggotów:gotowa; porozmawiać o interesach, $N?', 0),
(10271, 'plPL', 'Na pewno masz wiele pytań; na wszystkie otrzymasz odpowiedź we właściwym czasie.', 0),
(10272, 'plPL', 'Udało ci się zebrać jaja?', 0),
(10273, 'plPL', 'Ten Marid to głupiec, a raczej był głupcem.', 0),
(10274, 'plPL', '$GRzuciłeś:Rzuciłaś; wyzwanie Veraku i $gpokonałeś:pokonałaś; go?', 0),
(10275, 'plPL', 'Chcesz kupić czy sprzedać?', 0),
(10276, 'plPL', 'Witaj ponownie, $gprzyjacielu:przyjaciółko;. Jak idą poszukiwania kryształu?', 0),
(10290, 'plPL', 'Rozumiem, że zbieranie farahlitu jest bardzo niebezpieczne, ale i możliwości są ogromne. Kupiec, który nie chce ryzykować, równie dobrze może zamknąć interes i oszczędzić sobie kłopotu.', 0),
(10293, 'plPL', 'Wciąż żyjesz, co oznacza, że albo masz rdzeń, albo $gzmieniłeś:zmieniłaś; zdanie. Które z dwojga?', 0),
(10299, 'plPL', 'Czy twoje zadanie zakończyło się sukcesem, $N?', 0),
(10300, 'plPL', 'Udało ci się znaleźć kryształy nadające się na nową głowicę kostura arcymaga?', 0),
(10301, 'plPL', '$GOdzyskałeś:Odzyskałaś; okulus?', 0),
(10305, 'plPL', 'Co $gznalazłeś:znalazłaś;, $N?', 0),
(10306, 'plPL', 'Co $gznalazłeś:znalazłaś;, $N?', 0),
(10307, 'plPL', 'Co $gznalazłeś:znalazłaś;, $N?', 0),
(10308, 'plPL', 'Konsorcjum bardzo zależy na wybiciu wszystkich buntowników Zaxxis na Hałdzie na południu.$B$B$N, jeśli chcesz jeszcze bardziej zaskarbić sobie naszą przychylność, wróć tam i przynieś więcej insygniów ich przynależności.', 0),
(10309, 'plPL', 'Od tego całego promieniowania Otchłani chyba psuje mi się wzrok. Masz już to serce Grabieżcy Spaczenia?', 0),
(10312, 'plPL', 'Udało ci się znaleźć rejestr?', 0),
(10313, 'plPL', '$GWykonałeś:Wykonałaś; pomiary, o które prosiłem, $N?', 0),
(10314, 'plPL', 'Co $godkryłeś:odkryłaś;, $N?', 0),
(10315, 'plPL', 'Ilu otchłanomantów udało ci się powalić?', 0),
(10318, 'plPL', 'Jakie wieści przynosisz z Kuźni Many Ara? $GRozprawiłeś:Rozprawiłaś; się z brygadzistą Sundownem?', 0),
(10319, 'plPL', 'Musisz odzyskać filakterię Naberiusa, zanim go zaatakujemy. Inaczej będzie niewrażliwy.', 0),
(10320, 'plPL', '$GZniszczyłeś:Zniszczyłaś; lisza, którym stał się ten nędzny Naberius?', 0),
(10321, 'plPL', '$GWykonałeś:Wykonałaś; już swoje zadanie, $N?', 0),
(10322, 'plPL', '$GWykonałeś:Wykonałaś; już swoje zadanie, $N?', 0),
(10328, 'plPL', 'Udało ci się zdobyć odprawy z Kuźni Many Duro?', 0),
(10329, 'plPL', 'Plan zadziałał? Szczerze mówiąc, trochę się spodziewałem, że wylecisz w powietrze.', 0),
(10330, 'plPL', '$GWykonałeś:Wykonałaś; już swoje zadanie, $N?', 0),
(10331, 'plPL', 'Udało ci się znaleźć mój młot?', 0),
(10332, 'plPL', '<Uczeń ma chyba łzy w oczach, gdy mówi.>$B$BCzy... $grozprawiłeś:rozprawiłaś; się z mistrzem Rhonsusem?', 0),
(10334, 'plPL', '<Krowa patrzy na ciebie nieufnie, ale nie rusza się z miejsca.>', 0),
(10335, 'plPL', 'Szybko poszło. Musisz być bardzo sprawną osobą, skoro już $grozstawiłeś:rozstawiłaś; wszystkie trzy znaczniki.', 0),
(10336, 'plPL', '$GZabiłeś:Zabiłaś; już wszystkie demony w Ruinach Farahlonu?', 0),
(10338, 'plPL', '$GWyłączyłeś:Wyłączyłaś; ją? Lepiej się pośpiesz, zanim zmienię zdanie w całej tej sprawie.', 0),
(10339, 'plPL', 'Dobra robota, istoto z mięsa...', 0),
(10342, 'plPL', 'Masz już dość tego łupka? Będę potrzebował mnóstwa, żeby wydobyć tyle oleju, ile trzeba na paliwo dla Rakiety Otchłani X-52.', 0),
(10343, 'plPL', '$GZnalazłeś:Znalazłaś; szczątki broni, której Kael\'thas użył przeciw wiosce?', 0),
(10345, 'plPL', 'Udało ci się znaleźć Ya-sixa?', 0),
(10348, 'plPL', 'Udało ci się zebrać zioła?', 0),
(10353, 'plPL', 'Meldunek, istoto z mięsa? Jaka jest sytuacja?', 0),
(10380, 'plPL', 'Czy twoje zadanie zakończyło się sukcesem, $N?', 0),
(10384, 'plPL', '$GOdzyskałeś:Odzyskałaś; ogniwo danych?', 0),
(10385, 'plPL', '$GOdzyskałeś:Odzyskałaś; dane z przekaźników?', 0),
(10405, 'plPL', '$GZdobyłeś:Zdobyłaś; owijacz?', 0),
(10406, 'plPL', 'Musi ci się udać!', 0),
(10407, 'plPL', '$GZdobyłeś:Zdobyłaś; kamień teleportacyjny Socrethara, $N?', 0),
(10408, 'plPL', 'Czy... Czy on naprawdę nie żyje? Zniszczony?', 0),
(10411, 'plPL', 'Zarówno szlam, jak i odpady są niezwykle toksyczne. Pozostawione bez kontroli zbiją się w zakrzepłą poczwarę Pustki!', 0),
(10413, 'plPL', 'Hmm, wyglądasz na trochę $gubrudzonego:ubrudzoną;... W co ty się $gwpakowałeś:wpakowałaś;?', 0),
(10417, 'plPL', 'Masz wyniki diagnostyki?', 0),
(10418, 'plPL', '$GUkróciłeś:Ukróciłaś; męki tych stworzeń? Nie zrozum mnie źle, naprawdę kocham zwierzęta, ale nie wtedy, gdy gryzą rękę, która je karmi i daje im schronienie.', 0),
(10422, 'plPL', '$GZnalazłeś:Znalazłaś; Tyraliusa?', 0),
(10424, 'plPL', 'Masz wyniki diagnostyki?', 0),
(10426, 'plPL', '$GSpróbowałeś:Spróbowałaś; skupić energię kopuły?', 0),
(10427, 'plPL', 'Udało ci się oznaczyć dość talbuków?', 0),
(10429, 'plPL', 'Masz próbkę z tej potwornej hydry?', 0),
(10430, 'plPL', 'Widzę, że masz prototyp. Przysłał cię Ghabar?', 0),
(10432, 'plPL', 'No i? Co miał do powiedzenia Theledorn?', 0),
(10433, 'plPL', 'Masz jakieś futra na sprzedaż?', 0),
(10435, 'plPL', '$GZebrałeś:Zebrałaś; wszystko?', 0),
(10436, 'plPL', '$GOczyściłeś:Oczyściłaś; teren testowy?', 0),
(10437, 'plPL', '$GZebrałeś:Zebrałaś; dość fragmentów?', 0),
(10438, 'plPL', '$GTrafiłeś:Trafiłaś; w cel?', 0),
(10439, 'plPL', 'Co z władcą Pustki?', 0),
(10508, 'plPL', '$GZdobyłeś:Zdobyłaś; kamień teleportacyjny Socrethara, $N?', 0),
(10701, 'plPL', 'Co? Co?! Streszczaj się... tyle tu roboty.$B$BChciałbym kiedyś poderwać to coś z ziemi, wiesz?', 0),
(10850, 'plPL', 'Odsłaniasz otwór, przez który ładuje się paliwo do Grabieżcy Spaczenia.', 0),
(10855, 'plPL', '$GWypróbowałeś:Wypróbowałaś; mój mały eksperyment, $N?', 0),
(10856, 'plPL', 'Jak idzie? Udało ci się dać Legionowi nauczkę czy dwie?', 0),
(10857, 'plPL', 'Więc zrobione? Teleportery wyłączone?', 0),
(10899, 'plPL', 'Na pewno chcesz zostać $gmistrzem:mistrzynią; transmutacji? Jeśli wyspecjalizujesz się w tej dziedzinie, nie będziesz już $gmógł:mogła; specjalizować się w miksturach ani eliksirach.', 0),
(10924, 'plPL', 'Czy Zeppit współpracował na tyle, że udało ci się zebrać całą potrzebną mi krew?', 0),
(10971, 'plPL', '$GZdobyłeś:Zdobyłaś; jakieś identyfikatory?', 0),
(10972, 'plPL', 'Potrzebuję więcej identyfikatorów, $N. Jak dotąd odkryłem, że to nie tylko sposób na katalogowanie więźniów, ale i zapis miejsc!$B$BGdy złamiemy ten szyfr, ustalimy dokładnie, gdzie są przetrzymywani wszyscy nasi sojusznicy, i uwolnimy ich przy jak najmniejszym oporze wroga.', 0),
(10973, 'plPL', 'Wiem, że proszę o wiele, ale pomyśl, ile istnień można uratować!', 0),
(12413, 'plPL', '$GWykonałeś:Wykonałaś; już swoje zadanie, $N?', 0);
