(31957, 'plPL', 'Identyfikator więźnia Eterium', 'Przód i tył tego identyfikatora pokrywają dziwne glify i symbole.', 0),
(32666, 'plPL', 'Utwardzona skóra Tyrantusa', '', 0),
(32840, 'plPL', 'Wielka mikstura ochrony przed tajemną mocą', '', 0),
(32845, 'plPL', 'Wielka mikstura ochrony przed cieniem', '', 0),
(33804, 'plPL', 'Schemat: wytwórnica strzał z adamantytu', 'Uczy konstruowania wytwórnicy strzał z adamantytu.', 0);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(2984, 'plPL', '<Po kilku stronach otępiającej „nauki”, która zdaje się nie mieć absolutnie żadnego sensu, na dole ostatniej strony widnieje nabazgrana notatka...>\n\nWybacz, szefie. Wygląda na to, że Burza Otchłani wkrótce wyleci w powietrze. Pewnie pociągnie za sobą większość reszty Rubieży.\n\nNie mam stuprocentowej pewności, ale chyba problem ma związek z tym, co te krwawe elfy wyprawiają w kuźniach many.\n\nDobrze, że budujesz tę rakietę!\n\n– Miedziogrosz\n\nPS Myślisz, że dostałbym miejsce w rakiecie? Na pewno przyda ci się otchłanolog podczas rejsu przez Wypaczoną Otchłań!', 0);
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(20464, 3, 0, 'plPL', 'Dziękuję, że $gsprowadziłeś:sprowadziłaś; z powrotem moją Bessy, $N. Nie mógłbym bez niej żyć!'),
(20552, 0, 0, 'plPL', 'Hej! Hej, ty! $R! Tam!'),
(20985, 1, 0, 'plPL', 'Powiedz mi, kiedy będziesz $ggotów:gotowa;. Zaatakujemy na twój rozkaz.');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(16867, 'plPL', '„Burza Otchłani” nie zawsze wyglądała tak jak teraz.$B$BByły czasy, gdy tę rozpadającą się krainę nazywano Równinami Farahlonu. Niewiele z tamtych dni przetrwało zło, które tu zapanowało.', '', 0),
(16869, 'plPL', 'Arcymag Vargoth powierzył mi swój kostur, gdy kazał mi uciekać przed atakiem krwawych elfów na Purpurową Wieżę. Zrobiłem, jak kazał, w nadziei, że schronię się w starej osadzie draenei Arklon.$B$BNie było mi dane odetchnąć. Wszedłem prosto na czoło sił Płonącego Legionu. Demony wyrwały mi kostur, ale zdołałem ujść z życiem.$B$BChoć mój mistrz nic nie wie o mojej porażce, wciąż się jej wstydzę.', '', 0),
(16874, 'plPL', '', 'Otaczają mnie idioci!', 0),
(16883, 'plPL', '', 'Powiedzieliśmy wam wszystko, co wiemy! Zapominacie, że wielu z nas było kiedyś zaufanymi stronnikami Kael\'thasa?', 0),
(16894, 'plPL', 'No proszę, kogo to przywiały wichry Otchłani. Wejdź, usiądź i odpocznij chwilę. Opłata jest skromna, na pewno cię na nią stać.', 'No proszę, kogo to przywiały wichry Otchłani. Wejdź, usiądź i odpocznij chwilę. Opłata jest skromna, na pewno cię na nią stać.', 0),
(16926, 'plPL', 'Uff! Jest mój szczęśliwy kapelusz. Wszędzie go szukałem.', '', 0),
(16927, 'plPL', 'Nie mogę przecież wyjść bez płaszcza. Mam nadzieję, że jest tutaj...', '', 0),
(16929, 'plPL', 'Jest! Mógłbym przysiąc, że nie było go tu, kiedy ostatnio sprawdzałem...', '', 0),
(16931, 'plPL', 'Nie wiem, co mi strzeliło do głowy, żeby wychodzić bez miecza. Przypasałbym go, gdybym go tu zobaczył...', '', 0),
(16932, 'plPL', '', 'Nie zasnę bez dobrej bajki na dobranoc. Teraz na pewno dobrze wypocznę.', 0),
(16941, 'plPL', 'Cześć! Miło zobaczyć nową twarz – rzadko miewam gości, a technicy nie są zbyt rozmowni.$B$BZałożę się, że zmierzasz do Strefy 52. Zgadłem?', '', 0),
(16951, 'plPL', 'Ostatni raz kupuję używany sprzęt od eteryka!', '', 0),
(16952, 'plPL', 'Mam nadzieję, że te krwawe elfy po drugiej stronie nie myślą, że je szpieguję!', '', 0),
(16953, 'plPL', 'Jeśli to się zgadza, zostało nam niewiele czasu! A, trudno.', '', 0),
(16955, 'plPL', 'Gdybym był mądry, sprzedałbym te badania za miejsce na pokładzie rakiety. Mam przeczucie, że niedługo trzeba będzie się stąd zmywać!', '', 0),
(16959, 'plPL', '', 'Tu trzeba delikatnej roboty, wiesz? Nie można się spieszyć, bo coś się zepsuje.$B$BNa przykład głowa Kadłubka!$B$BPewnie ciekawią cię moje boty? Ciągle pracuję nad Mk. I, a Mk. II na ułamek sekundy zyskał świadomość, zanim przepalił mu się kondensator mózgowy i oszalał!$B$BPostanowiłam pominąć III i IV i przeszłam od razu do Mk. V – mojej dumy i radości!', 0),
(16962, 'plPL', 'Uważaj w ruinach, $N. Duchy Kirin Toru, które tam spotkasz, nie rozpoznają w tobie przyjaciela.$B$BTylko kustosz i ja zachowaliśmy z tym miejscem więź dość silną, by po śmierci zachować pełną tożsamość.', '', 0),
(16963, 'plPL', 'Wioska Kirin\'Var przetrwała 20 długich lat i niezliczone ataki orków, ale nie oparła się siłom Kael\'thasa. Ten, który niegdyś nazywał siebie członkiem Kirin Toru, wymordował nas wszystkich, z wyjątkiem jednego.$B$BArcymag Vargoth przeżył atak, więc Kael\'thas uwięził go w Purpurowej Wieży i otoczył ją magią, która nie przepuszcza nikogo z Kirin Toru.', '', 0),
(17001, 'plPL', 'Ach, $gkolejny potężny podróżnik:kolejna potężna podróżniczka;. Otchłań bywa niebezpieczna, zechcesz mieć pod ręką najsilniejsze zaklęcia. Mam najlepsze reagenty, zwykłe i egzotyczne. Chodź, kupuj – nie pożałujesz!', '', 0),
(17002, 'plPL', 'Tutejsze stworzenia są silne, $gwędrowcze:wędrowczyni;. Jeśli chcesz przeżyć, będziesz potrzebować sporo amunicji. Masz szczęście – mam duży zapas świetnych strzał, kul i broni miotanej. Cena jest rozsądna, zważywszy na okoliczności.', '', 0),
(17004, 'plPL', 'Może $grzemieślnik:rzemieślniczka;? Po zaopatrzenie nie musisz szukać dalej niż u mnie. Moje ceny są całkiem uczciwe, $gprzyjacielu:przyjaciółko;. Trudno było zdobyć te towary, ale czy to ważne, skąd pochodzą, co? Dostaniesz, czego potrzebujesz.', '', 0),
(17035, 'plPL', 'Mam kolejny odczyt z Otchłani.', '', 0),
(17045, 'plPL', 'No to dawaj go, zobaczmy, co tam masz!', '', 0),
(17048, 'plPL', 'Na co masz ochotę? Przysuń sobie stołek i golnij sobie jednego.$B$BJestem Boots, główny miksolog B.U.M. i barman nad barmanami!$B$BJeśli coś ma kopa, stary Boots ci to poda.', '', 0),
(17054, 'plPL', 'Boots, co tam masz takiego, co gładko wchodzi?', 'Boots, co tam masz takiego, co gładko wchodzi?', 0),
(17056, 'plPL', 'Wielki Gazolu!', '', 0),
(17088, 'plPL', 'Promieniowanie?!$B$BNie, tym nie musisz się martwić! Rany, w co to ludzie dziś nie wierzą.$B$BTo co sądzisz o naszej robocie tu na dole? Najwyższy światowy poziom, złotko! Możesz być $gpewien:pewna;.', '', 0),
(17094, 'plPL', 'Na tablicy przybito dwa rzucające się w oczy ogłoszenia: jedno od Papy Wheelera, drugie od Rakietowodza Kadłubka.$B$BTo od Papy wygląda na poszukiwanie części do maszyny. To od rakietowodza dotyczy nagrody za głowę ogromnego górskiego giganta!$B$BSzczegóły obu zapisano bardzo drobnym goblińskim pismem, które oczywiście jest ledwie czytelne.', '', 0),
(17115, 'plPL', 'Może po tej zmianie zbiorę paru innych agentów i się tam wybierzemy?', 'Może po tej zmianie zbiorę paru innych agentów i się tam wybierzemy?', 0),
(17116, 'plPL', 'Hmm, tajemne anihilatory są naprawdę twarde. Ciekawe, czy Papa Wheeler wie, o co prosi?', 'Hmm, tajemne anihilatory są naprawdę twarde. Ciekawe, czy Papa Wheeler wie, o co prosi?', 0),
(17119, 'plPL', 'Całe szczęście, że dookoła mamy sąsiadów z nadmiarem części do maszyn.', 'Całe szczęście, że dookoła mamy sąsiadów z nadmiarem części do maszyn.', 0),
(17130, 'plPL', 'Rozdrabniacze?! Już do niczego się nie nadają. To przeżytek!$B$BJeśli mamy budować rakiety – jeśli X-52 ma się oderwać od ziemi – potrzebujemy lepszej techniki!', '', 0),
(17179, 'plPL', 'Uwielbiam zapach Otchłani o poranku.', 'Uwielbiam zapach Otchłani o poranku.', 0),
(17180, 'plPL', 'Pachnie jak...', 'Pachnie jak...', 0),
(17181, 'plPL', '...zwycięstwo.', '...zwycięstwo.', 0),
(17288, 'plPL', '<Głowa wizerunku rozmywa się, gdy obraca się on, by rozejrzeć się dookoła.>$B$BKto widział Równiny Farahlonu, nie uwierzyłby, że to to samo miejsce. Jeszcze kilka miesięcy temu te pola nie wyglądałyby obco w Zachodnim Skraju.$B$BTo wszystko przepadło, ale jak i dlaczego?', '', 0),
(17289, 'plPL', 'Kraina jest w gorszym stanie, niż mogłem sobie wyobrazić. Jeśli zniszczenia będą postępować w tym tempie, Farahlon – ee, Burza Otchłani – już wkrótce będzie tylko kosmicznym żwirem.$B$BCiekawe, gdzie to się skończy? A może lepiej zapytać: „czy to się w ogóle skończy?”', '', 0),
(17290, 'plPL', '<Wizerunek arcymaga zdaje się patrzeć przez ciebie, a nie na ciebie.>$B$BWstęgi i prądy tajemnej energii przypływają tu i odpływają, jakby okolica tonęła w morzu magicznej mocy. Nawet pierwszy kataklizm nie wyrządził takich szkód.', '', 0),
(17291, 'plPL', 'Zemszczę się na Kael\'thasie za tę zniewagę wobec Kirin Toru! Niegdyś chodził wśród nas jak brat, lecz nie jesteśmy już braćmi.$B$BNadejdzie dzień rozrachunku.$B$B<Arcymag ponuro kiwa głową, bez radości na myśl o tym.>$B$BKael\'thas to ktoś więcej niż zwykły mag renegat. Gdy tylko uwolnię się z wieży, Ravandwyr i ja pomożemy każdemu, kto mu się przeciwstawi.', '', 0),
(17296, 'plPL', 'Ciszej! Nie chcę, żeby mnie tu zobaczyli.$B$BOch, aż się we mnie gotuje! Za kogo ci eterycy się mają?$B$BTo MOJA działka!', '', 0),
(17345, 'plPL', 'Kiedy Rakietowódz Kadłubek szukał ochotników do budowy Rakiety Otchłani X-52, złożyłem podanie do działu ochrony.$B$BNiestety jedynym wolnym stanowiskiem był główny inżynier. Na szczęście mam tu Xyrola, który patrzy mi na ręce.', '', 0),
(17359, 'plPL', '', 'Wierzysz w tę eteryczną technikę?!$B$BAle się cieszę, że pozwolili mi tu z nimi zostać. Wiele się nauczę... a może i coś sobie przygarnę!', 0),
(17408, 'plPL', 'Hahaha! Idziemy po was, gobliniki!', '', 0),
(17413, 'plPL', 'Jestem spakowany i gotowy do drogi.', '', 0),
(17414, 'plPL', 'Statek jeszcze nie jest gotowy. Musimy skalibrować długość lontu, żeby się nie wypalił i nie zostawił cię tam samego.', '', 0),
(17416, 'plPL', 'Co trzeba zrobić? Nie znam się na tej całej nauce... Dla mnie to zwykła robota od poniedziałku do piątku.', '', 0),
(17417, 'plPL', 'Krótko mówiąc, do startu jeszcze bardzo daleko. Może na razie wróć do domu, do rodziny.', '', 0),
(17419, 'plPL', 'Nie mogę. W domu mają mnie za kogoś innego. Zresztą nie przywiozłem ich tutaj.', '', 0),
(17420, 'plPL', 'Czemu nie? Rodzina dodaje sił.', '', 0),
(17421, 'plPL', 'To nie jest miejsce na wychowywanie dzieci. Zimno tu i nie byłoby komu się nimi zająć.', '', 0),
(17422, 'plPL', 'A ty nie mógłbyś się nimi zająć?', '', 0),
(17423, 'plPL', 'O nie, nie, nie... Ja jestem od rakiet.', '', 0),
(17424, 'plPL', 'Cóż, jak mówiłem, minie trochę czasu, zanim przygotujemy ten statek do lotu. Będziemy cię informować.', '', 0),
(17425, 'plPL', 'Ten kryształowy konstrukt aż buczy od energii. Przed tobą wyświetlają się dziwne glify, przewijając się w szybkim tempie.', '', 0),
(17427, 'plPL', 'Zajęty, zajęty! Tyle do zrobienia, tak mało czasu!$B$BGdzie ja położyłem ten piroklucz? Wiem, że jest gdzieś tutaj... Przed chwilą sparzyłem sobie o niego palce!', '', 0),
(17440, 'plPL', 'W tej branży przydaje się odrobina magii. Iluzje nie zawsze zwiodą każdego, ale zwykle wystarczą, żeby załatwić sprawę.', '', 0),
(17443, 'plPL', 'Co tu robisz? Czy nie masz przypadkiem pracować przy rurociągu energii?$B$BPrzesyłamy do Twierdzy Burz ponad dwa razy więcej energii niż wcześniej i nie możemy sobie pozwolić, żeby ktoś się obijał. Nie chcemy tu drugiego Ultris.', '', 0),
(17444, 'plPL', 'Ultris?', 'Ultris?', 0),
(17445, 'plPL', 'Kuźnia Many Ultris, oczywiście! Gdzie ty $gbyłeś:byłaś;?$B$BKuźnia many została przeciążona i doszło do potężnego wybuchu. Zostawił on rozdarcie w rzeczywistości, przez które wlewają się teraz istoty Pustki. Widać je wszędzie w kierunku północno-wschodnim.', '', 0),
(17455, 'plPL', 'JESTEM ŚMIERCIĄ! PRZYGOTUJCIE SWOJE MIASTO NA ZAGŁADĘ!', '', 0),
(17456, 'plPL', 'O nie! Co to jest? Szybko, broń nas Złomowym grabieżcą X6000!!!', '', 0),
(17463, 'plPL', 'Tu możesz czuć się bezpiecznie – po atakach na Kuźnię Many Duro wzmocniliśmy ochronę tej placówki.', '', 0),
(17464, 'plPL', 'Kto zaatakował Kuźnię Many Duro?', 'Kto zaatakował Kuźnię Many Duro?', 0),
(17465, 'plPL', 'Kuźnia Many Duro leży najbliżej Twierdzy Burz, więc przejmuje większość obciążenia.$B$BJak wiadomo, przeciążanie tych kuźni many powoduje przecieki w rurociągach. Wydobywająca się energia przyciąga niepożądane istoty many. Plagi istot many nawiedziły wiele miejsc przecieków; najmocniej obrywa obecnie Kuźnia Many Duro.', '', 0),
(17468, 'plPL', 'TWOJA ŻAŁOSNA PRÓBA STWORZENIA GRABIEŻCY SPACZENIA, KTÓRY MIAŁ MNIE POWSTRZYMAĆ, ZAWIODŁA! A TERAZ – NA STREFĘ 52!', '', 0),
(17469, 'plPL', '', 'Praca z tą techniką to potworny ból głowy. Wszystko jest zbudowane w tak obcy sposób.', 0),
(17475, 'plPL', 'Skąd pochodzi ta technika?', 'Skąd pochodzi ta technika?', 0),
(17476, 'plPL', '', 'Niczego was, nowych rekrutów, nie uczą? Te kuźnie many zbudowano z części Twierdzy Burz, zaprojektowanych do wysysania energii z Otchłani.$B$BNaaru zasilali tą techniką swój statek podczas podróży. Niektórzy mówili, że używanie jej na lądzie może nie być bezpieczne. Szybko ich uciszono.', 0),
(17482, 'plPL', 'Konsorcjum zemści się na zdrajcach z Zaxxis!', '', 0),
(17529, 'plPL', '', 'Pojawia się migoczący wizerunek dowódczyni krwawych elfów. Po otoczeniu widać, że musi przebywać w Twierdzy Burz.', 0),
(17530, 'plPL', '', 'Krwawa elfka nie wygląda na magistra, ale może ma przy sobie coś, co jest kluczem do klątwy wieży.', 0),
(17553, 'plPL', 'Jako przedstawiciel Konsorcjum zawsze pamiętam o skutkach, jakie moje działania mają dla naszych interesów.$B$BSzkoda, że krwawe elfy nie traktują swoich partnerów z takim szacunkiem.', '', 0),
(17554, 'plPL', 'Mój młodszy brat to prawdziwa wschodząca gwiazda Konsorcjum. Oczywiście jest zbyt skromny, żeby to przyznać.', '', 0),
(17555, 'plPL', 'Kiedy mówi „młodszy brat”, zapomina wspomnieć, że jesteśmy bliźniakami. Jest starszy raptem o kilka minut.$B$BI nie daj się zwieść tej „wschodzącej gwieździe”. Nigdy nie będę handlarzem jego formatu.', '', 0),
(17571, 'plPL', '', 'Chyba wybrałam zły dzień, żeby rzucić czerpanie many...', 0),
(17590, 'plPL', 'Ta eteryczna platforma teleportacyjna jest pokryta jaskrawymi przyciskami i przełącznikami, ale wygląda na dawno nieużywaną.', '', 0),
(17591, 'plPL', 'Wszystko na sprzedaż, $gprzyjacielu:przyjaciółko;! Duże i małe – czegokolwiek potrzebujesz, Hazzin to dostarczy.$B$BJeśli cenisz życie, nie zbliżaj się do Kuźni Many Ultris bez uzupełnienia zapasów. Hazzin to twoja ostatnia szansa.', '', 0),
(17592, 'plPL', 'Handlarzu Hazzinie, co masz do zaoferowania?', 'Handlarzu Hazzinie, co masz do zaoferowania?', 0),
(17615, 'plPL', 'Dokończmy naszą rozmowę w bardziej... ustronnym miejscu. Chodź za mną, $n.', '', 0),
(17618, 'plPL', 'Chyba naprawdę nie $gmyślałeś:myślałaś;, że znów zrobię z tobą interes? Czasem najlepszym sposobem na powrót do zysków jest wiedzieć, kiedy ograniczyć straty.', '', 0),
(17625, 'plPL', '', 'Nigdy nie widziałam czegoś takiego jak te smoki Otchłani. Zdają się mieć temperament po ojcu, ale stały się czymś zupełnie innym.', 0),
(17627, 'plPL', 'Skoro zapuszczasz się aż tutaj, to pewnie masz odwagę zbliżyć się do Kuźni Many Ara.$B$BChcesz coś kupić lub sprzedać, zanim tam wyruszysz?', '', 0),
(17628, 'plPL', 'Co masz na sprzedaż, Tulumanie?', 'Co masz na sprzedaż, Tulumanie?', 0),
(17629, 'plPL', 'Na tym świecie są tylko 3 rodzaje ludzi: konkurenci, klienci i pracownicy. Konkurentów należy bezwzględnie miażdżyć, klientom dogadzać, a pracowników ściśle nadzorować.$B$BNiezależni wykonawcy to mit. Chcą zarabiać lepiej niż pracownicy, ale być traktowani jak klienci. Nigdy nie ufaj komuś, kto tak siebie nazywa.', '', 0),
(17638, 'plPL', 'Spróbuj skontaktować się z handlarzem wiatru Maridem.', 'Spróbuj skontaktować się z handlarzem wiatru Maridem.', 0),
(17754, 'plPL', 'Handlarzu wiatru Maridzie, wracam z nowymi informacjami o smokowcach Otchłani. Jestem $ggotów:gotowa; zostać twoim wspólnikiem, a za dodatkową opłatą zajmę się tą kłopotliwą elfką i jej przyjacielem człowiekiem.', 'Handlarzu wiatru Maridzie, wracam z nowymi informacjami o smokowcach Otchłani. Jestem $ggotów:gotowa; zostać twoim wspólnikiem, a za dodatkową opłatą zajmę się tą kłopotliwą elfką i jej przyjacielem człowiekiem.', 0),
(17760, 'plPL', '', 'Załatwiłam ci lot do Kuźni Many Coruu. Czy jesteś $ggotów:gotowa;, $n? Wysadzą cię za liniami wroga, więc upewnij się, że masz przy sobie wszystko, czego potrzebujesz.', 0),
(17761, 'plPL', 'Bardziej $ggotów:gotowa; już nie będę.', 'Bardziej $ggotów:gotowa; już nie będę.', 0),
(17788, 'plPL', 'Użyję mocy kryształu Ata\'mal, by cię zmiażdżyć!', '', 0),
(17790, 'plPL', 'Nigdy nie odbierzesz mi kryształu Ata\'mal!', '', 0),
(17791, 'plPL', 'Kryształ Ata\'mal jest mój!', '', 0),
(17799, 'plPL', 'Chcesz coś kupić? Chcesz coś sprzedać?$B$BPo to tu jesteśmy, $gprzyjacielu:przyjaciółko;.$B$BProszę, powiedz, na co masz ochotę.', '', 0),
(17800, 'plPL', 'Handlarzu Dunarze, chcę obejrzeć twoje towary.', 'Handlarzu Dunarze, chcę obejrzeć twoje towary.', 0),
(17848, 'plPL', 'Och, już kolejny pokaz? No dobrze...', '', 0),
(17849, 'plPL', '%s głośno wzdycha i zerka na Sagana.', '', 0),
(17850, 'plPL', 'A teraz kolejna sztuczka...', '', 0),
(17852, 'plPL', 'Pokaż nam sztuczkę, Ravandwyrze!', '', 0),
(17853, 'plPL', 'To była najlepsza sztuczka w historii! Dobra, chłopaki, chodźmy się napić.', '', 0),
(17854, 'plPL', 'Zionę ogniem!', '', 0),
(17855, 'plPL', 'Przemienię mojego chowańca, Sagana, w coś naprawdę cudownego!', '', 0),
(17856, 'plPL', 'Dziękuję wszystkim za uwagę! Byłbym wdzięczny, gdybyście na jutrzejsze przedstawienie przynieśli nienapromieniowane monety.', '', 0),
(17857, 'plPL', 'Skunks! Fuuuuuuuuuuuuj! Nie dotykaj mnie!', '', 0),
(17858, 'plPL', 'Zabierz go ode mnie!', '', 0),
(17874, 'plPL', 'Wypuśćcie mnie stąd! Chłopaki... chłopaki?', '', 0),
(17875, 'plPL', 'O rany, ale cię urządził!', '', 0),
(17876, 'plPL', 'Pamiętasz, jak ciągle nam powtarzasz, żebyśmy ochłonęli?', '', 0),
(17877, 'plPL', 'Taki mały żarcik.', '', 0),
(17884, 'plPL', 'Awaryjne wyłączenie zakończy się za trzydzieści sekund.', '', 0),
(17885, 'plPL', 'Awaryjne wyłączenie zakończy się za dziesięć sekund.', '', 0),
(17886, 'plPL', 'Wyłączanie kuźni many przerwane. Wznawianie pracy kuźni many.', '', 0),
(17900, 'plPL', 'Awaryjne wyłączenie zakończone.', '', 0),
(17914, 'plPL', 'Oczywiście żaden z moich towarów nie jest kradziony. Ale jak ktoś zapyta, to nie masz ich ode mnie!', '', 0),
(17915, 'plPL', 'Najnowsze plany, wykroje i schematy – tylko tutaj. Instrukcje są tak proste, że przedmioty praktycznie wytwarzają się same!', '', 0),
(17916, 'plPL', 'Największy wybór przemycanych towarów – tylko tutaj, $n. Świetne dla całej rodziny! Unikaj goblińskich podatków i zakazów naaru – Konsorcjum zaspokoi wszystkie twoje potrzeby zakupowe!', '', 0),
(17917, 'plPL', 'Psst! Mam coś, co może cię zainteresować, $n. Spadło z jucznego muła w Nagrandzie!', '', 0),
(17940, 'plPL', 'Dobrze. Zanim tam zejdziemy, poświęć chwilę na przygotowania.', '', 0),
(17941, 'plPL', 'Ruszajmy żwawym krokiem.', '', 0),
(17942, 'plPL', 'Zaczniemy od tamtego pierwszego pylonu energii, prosto przed nami. Pamiętaj, staraj się trzymać ich z dala ode mnie.', '', 0),
(17943, 'plPL', 'Skończyłem z tym pylonem. Do następnego.', '', 0),
(17944, 'plPL', 'Dobra, drugi pylon załatwiony. Teraz kolektor cieplny.', '', 0),
(17945, 'plPL', 'To powinno wystarczyć. Teleporter lada chwila wyleci w powietrze!', '', 0),
(17947, 'plPL', 'Masz ochotę pomóc mi zniszczyć bramę wypaczenia w obozie Płonącego Legionu na południu?', '', 0),
(17949, 'plPL', 'Dziękuję, $n! Bez ciebie nie dałbym rady. Przekażesz to Gahrujowi?', '', 0),
(17950, 'plPL', 'Trzymaj ich z dala ode mnie!', '', 0),
(17951, 'plPL', '', 'Ci ludzie przybyli z Shattrath kilka nocy temu i od tamtej pory nie przestają się kłócić.$B$BCieszę się, że cię to nie odstraszyło. Zaczynałam już myśleć, że płoszą mi klientów.', 0),
(17952, 'plPL', '', 'Mam nadzieję, że ci z Shattrath wkrótce przestaną się kłócić. Zaczynają mi działać na nerwy.$B$BW czym mogę pomóc?', 0),
(17953, 'plPL', 'Pracować ciężej, psy!', '', 0),
(17954, 'plPL', 'Szybciej, albo posmakujecie Pazura!', '', 0),
(17960, 'plPL', 'Ciężka robota. Chyba potrzebuję urlopu. Ty tam, przyłóż się!', '', 0),
(18008, 'plPL', 'Jeśli $gbyłeś:byłaś; na Moczarach Zangarskich, może $gnatknąłeś:natknęłaś; się na gościa imieniem Daniels. No wiesz – nosi dziwny hełm, reaguje tylko na „Specjalista”.$B$BOczywiście to ja nauczyłem go wszystkiego, co umie.$B$BNie daj się zwieść eleganckim ciuchom. W głębi serca wciąż jestem łotrzykiem. Daniels i ja spędziliśmy razem sporo czasu w okopach, ale to było, zanim przeszedłem na emeryturę. O ile wiem, on wciąż tam jest i daje im popalić.', '', 0),
(18010, 'plPL', 'Dzień w dzień tylko harujemy w tej kopalni. Mężczyźni krwawych elfów nie są stworzeni do takiej fizycznej harówki.', '', 0),
(18119, 'plPL', '<Rozpocznij awaryjne wyłączenie.>', '<Rozpocznij awaryjne wyłączenie.>', 0),
(18120, 'plPL', 'Gdy zbliżasz się do konsoli, kryształ dostępu, który masz przy sobie, zaczyna cicho buczeć i pulsować światłem.$B$BDo twojego umysłu napływa fala informacji i nagle znasz poziom produkcji energii kuźni many, jej stabilność i to, ile oddaje do poszczególnych rurociągów. Konsola czeka na twoje polecenie.', '', 0),
(18155, 'plPL', 'Uwaga! %s: rozpoczęto awaryjne wyłączenie, inicjator: $n. Wyłączenie zakończy się za dwie minuty.', '', 0),
(18156, 'plPL', 'Awaryjne wyłączenie zakończy się za minutę.', '', 0),
(18165, 'plPL', 'Musisz wysłać posiłki do Kuźni Many Duro, Ardonisie. To nie prośba, to rozkaz.', '', 0),
(18166, 'plPL', 'Chyba żartujesz! Mamy poważne braki w ludziach i ledwie utrzymujemy tę kuźnię many w działaniu!', '', 0),
(18167, 'plPL', 'Zrobisz, co ci każą. Kuźnia Many Duro znalazła się pod ciężkim atakiem istot many i sytuacja wymknęła się spod kontroli. Niewykonanie rozkazu nie będzie tolerowane!', '', 0),
(18174, 'plPL', 'Szukam kogoś, kto pomoże mi w zadaniu, które dawno powinno zostać wykonane.$B$BWyglądasz na kogoś, kto sobie poradzi.', '', 0),
(18176, 'plPL', 'Wszędzie Legion... trzeba się z nim rozprawić!', '', 0),
(18179, 'plPL', 'Muuuuu...', '', 0),
(18180, 'plPL', 'Muuuuuuuuuu!', '', 0),
(18181, 'plPL', 'Bessy, jesteś w domu. Dzięki Światłości!', '', 0),
(18216, 'plPL', '<Uczeń co jakiś czas spogląda przez ramię, najwyraźniej reagując na dźwięki, których nie słyszysz.>$B$BDzień dobry, $n. Wybacz, jeśli wydaję się rozproszony, ale jestem w trakcie zlecenia dla rolnika Natina. Chcę podkuć wszystkie jego konie, zanim wróci z ratusza. W czym mogę pomóc?', '', 0),
(18246, 'plPL', 'Agent Ya-six i ja dostaliśmy od dowództwa Protektoratu misję najwyższej wagi: wytępić wszelkie ślady plagi istot Pustki w Ultris. Miały to być precyzyjne uderzenia. Ostatnim celem przed powrotem do Strażnicy Protektoratu był władca Pustki imieniem Arconus, który tuczył się na tutejszych istotach z mięsa.$B$BNiestety, przybyliśmy trochę za późno. W strzelaninie z bestiami z mięsa rozdzieliliśmy się z Ya-sixem. Teraz on jest uwięziony w środku, odcięty za liniami wroga.\n', '', 0),
(18249, 'plPL', 'Araxes, zgłoś się... Jesteś tam, Araxesie? Widoczność zerowa. Burze wypaczenia nas blokują.', '', 0),
(18250, 'plPL', 'Przyjąłem. Meldunek, żołnierzu.', '', 0),
(18256, 'plPL', 'Oby to cholerstwo działało. *Araxes wali pięścią w przenośny transponder.*', '', 0),
(18267, 'plPL', 'Jestem, dowódco.', '', 0),
(18268, 'plPL', 'Namierzyliśmy cel, dowódco. Rozdzieliliśmy się z Ya-sixem. Proszę o wsparcie.', '', 0),
(18269, 'plPL', 'Przyjąłem, Araxesie. Wsparcie jest w drodze. Utrzymaj pozycję. Powtarzam, utrzymaj pozycję.', '', 0),
(18270, 'plPL', 'Tu Ameer, bez odbioru.', '', 0),
(18271, 'plPL', '%s: mechaniczne serce zaczyna cicho bić.', '', 0),
(18281, 'plPL', 'Araxesie! Przyślij pomoc! Utknąłem w kopalni pod ostrzałem. Nie... nie wiem dokładnie, gdzie jestem, ale miałem na tyle przytomności umysłu, żeby zostawiać za sobą znaczniki na ziemi.', '', 0),
(18282, 'plPL', 'Nie mogę wrócić po znacznikach, na drodze jest za dużo bestii z mięsa. Przyślij kogoś... Niech idzie po znacznikach... Tu Ya-six, bez odbioru.', '', 0),
(18385, 'plPL', 'Światłości! Nie opuszczaj mnie!', '', 0),
(18386, 'plPL', 'Nie umieraj mi tu, obrońco!', '', 0),
(18387, 'plPL', 'Kael\'thas i Legion... tylko tego nam brakowało!', '', 0),
(18388, 'plPL', '$gOcaliłeś:Ocaliłaś; mnie, istoto z mięsa! Ameer usłyszy o tym szlachetnym czynie.', '', 0),
(18441, 'plPL', 'Chronić przewodnik! Powstrzymać intruzów!', '', 0),
(18443, 'plPL', 'Przygotujcie się na niebyt, wścibscy głupcy. Uwolniliście boga!', '', 0),
(18479, 'plPL', '%s rozpada się na grudki!', '', 0),
(18491, 'plPL', 'Witaj, istoto z mięsa. Jestem Navuud, główny badacz w Strażnicy Protektoratu.', '', 0),
(18546, 'plPL', '$GZgubiłem:Zgubiłam; Kostur arcymaga Vargotha. Możesz dać mi nowy?', '$GZgubiłem:Zgubiłam; Kostur arcymaga Vargotha. Możesz dać mi nowy?', 0),
(18548, 'plPL', 'Wśród eterycznych są tacy, którzy zajmują się wyłącznie mięsem i istotami z mięsa. Nazywa się ich treserami mięsobestii.', '', 0),
(18566, 'plPL', 'Do Strażnicy Protektoratu już niedaleko, $n. Tędy!', '', 0),
(18567, 'plPL', 'Dowódco! Ta istota z mięsa mnie uratowała!', '', 0),
(18568, 'plPL', '%s salutuje dowódcy Ameerowi.', '', 0),
(18579, 'plPL', 'Ameer może się martwić tym, co knuje Eterium, ale ja skupiam się na prawdziwym zagrożeniu: na Dimensiusie.', '', 0),
(18587, 'plPL', '%s, stoczywszy dobrą walkę, rozpada się na kawałki.', '', 0),
(18588, 'plPL', 'W innym czasie i miejscu uważano by mnie za ledwie młodzika. Tu jestem zaprawionym w boju wojownikiem, gotowym żyć i umrzeć dla chwały naaru.$B$BDo Kuźni Many Ara weszło nas dziesięciu. Wszyscy pozostali polegli z ręki Legionu.', '', 0),
(18592, 'plPL', 'Czy to Widzący przysłali cię do mnie? Wcale nie wyglądasz na kogoś z Widzących.', '', 0),
(18594, 'plPL', 'To beznadziejne... Zrobiłem wszystko, co mogłem.', '', 0),
(18595, 'plPL', 'Zawiodłem. Światłość mnie opuściła.', '', 0),
(18602, 'plPL', 'Przyspieszacie tylko nieuniknione. Z czasem wszystko zostanie pożarte!', '', 0),
(18606, 'plPL', '%s wydaje się osłabiona.', '', 0),
(18633, 'plPL', 'Istoto z mięsa, jestem kapitan Saeed z Protektoratu, a żołnierze u mego boku to moi Mściciele. Czekamy na rozkazy od istoty z mięsa, która zniszczyła przewodnik Pustki. Na jej słowo ruszymy do leża Dimensiusa i będziemy czekać na sygnał do ostatecznego uderzenia!$B$BZbyt długo to trwało... Władca Pustki wkrótce zmierzy się z naszą połączoną potęgą!', '', 0),
(18635, 'plPL', 'Potrzebuję nowego dezintegratora fazowego, profesorze.', 'Potrzebuję nowego dezintegratora fazowego, profesorze.', 0),
(18636, 'plPL', 'Smokowiec Otchłani spogląda na ciebie z aprobatą.', '', 0),
(18637, 'plPL', 'Jestem $ggotów:gotowa; do lotu! Wznieś mnie w górę, smoku!', 'Jestem $ggotów:gotowa; do lotu! Wznieś mnie w górę, smoku!', 0),
(18639, 'plPL', 'To ja jestem tą istotą z mięsa, Saeedzie. Ruszajmy!', 'To ja jestem tą istotą z mięsa, Saeedzie. Ruszajmy!', 0),
(18641, 'plPL', 'Jestem $ggotów:gotowa;. Zapiszmy się w historii!', 'Jestem $ggotów:gotowa;. Zapiszmy się w historii!', 0),
(18642, 'plPL', 'Słyszeliście istotę z mięsa! NAPRZÓD!', '', 0),
(18644, 'plPL', 'Teraz albo nigdy, żołnierze! Do dzieła! Za K\'aresh! Za Protektorat!', '', 0),
(18645, 'plPL', 'Nadszedł wreszcie czas twojej zagłady, Dimensiusie!', '', 0),
(18647, 'plPL', 'Czas ma znaczenie tylko dla śmiertelników, insekcie. Dimensius jest nieskończony!', '', 0),
(18650, 'plPL', 'Witaj w Ekokopule Środka, $gpodróżniku:podróżniczko;. Uważaj na interesy z tym goblinem – Shauly się nazywa. Chyba nikt nigdy przy mnie nie używał słowa „koleżko” jako znaku interpunkcyjnego.', '', 0),
(18651, 'plPL', 'Czas zacząć naprawy.', '', 0),
(18652, 'plPL', 'Działa! Ghabar ucieszy się na tę wieść.', '', 0),
(18869, 'plPL', '%s jest bardzo osłabiony.', '', 0),
(18912, 'plPL', '%s próbuje podzielić się na dwoje.', '', 0),
(19115, 'plPL', '%s rozpada się na odłamki.', '', 0),
(19134, 'plPL', 'Z pomocą mojego brata Zapa z Wiecznowidu zbudowałem tu, w Strefie 52, Implozer wymiarowy. Komu potrzebna rakieta, skoro Goblińska inżynieria daje natychmiastowy transport! Czy jesteś $gdość wprawnym inżynierem goblińskim:dość wprawną inżynierką goblińską;, by nauczyć się budować własną latarnię Implozera?\n', '', 0),
(19186, 'plPL', 'Mój panie!', '', 0),
(19189, 'plPL', 'Tak, mój panie.', '', 0),
(19190, 'plPL', 'Dopilnuj tego, Ardonisie!', '', 0),
(19207, 'plPL', '%s wzywa na pomoc pobliskiego samca!', '', 0),
(19659, 'plPL', 'Otchłanioskał?! To coś zgniecie cię na placek jednym krokiem swojej ogromnej stopy! Nie, dzięki!', 'Otchłanioskał?! To coś zgniecie cię na placek jednym krokiem swojej ogromnej stopy! Nie, dzięki!', 0),
(19660, 'plPL', 'Ostatnim razem, gdy ktoś wybrał się po nagrodę za Otchłanioskała, wróciła do nas tylko sprasowana warstwa lekkomyślnego poszukiwacza przygód!', 'Ostatnim razem, gdy ktoś wybrał się po nagrodę za Otchłanioskała, wróciła do nas tylko sprasowana warstwa lekkomyślnego poszukiwacza przygód!', 0),
(19873, 'plPL', 'Wykryto intruza! Natychmiastowa neutralizacja zagrożenia!', '', 0),
(20103, 'plPL', '%s zaczyna się krztusić, gdy jego silnik zawodzi.', '', 0),
(20285, 'plPL', 'Moje brwi! Przypaliłeś mi brwi!', '', 0),
(20286, 'plPL', 'Nie martw się. Tak jest lepiej!', '', 0),
(20341, 'plPL', 'Kiedyś zabawiałem się, przyjmując wyzwania od każdego, kto je rzucał, ale dawno już znudziły mi się tak łatwe zwycięstwa.$B$BNa razie poświęcam trochę czasu, by rozkręcić interes z reagentami i napisać książkę o moich przeżyciach w Młocie Zmierzchu.', '', 0),
(20345, 'plPL', 'Nie wyzwę cię, ale chcę obejrzeć twoje towary.', 'Nie wyzwę cię, ale chcę obejrzeć twoje towary.', 0),
(20371, 'plPL', '%s zbiera krew ścigacza wypaczenia.', '', 0),
(20556, 'plPL', 'Jestem tu na polecenie księcia Nexusa Haramada. W Burzowej Iglicy dzieją się dziwne rzeczy.', '', 0),
(33038, 'plPL', 'Witaj, $N, w moim skromnym ustroniu. To miejsce bardzo mnie odpręża, a w Dalaranie zawsze czułem się jak w domu. Czasem jednak bywa tu samotnie... tak bardzo samotnie.', '', 0),
(33039, 'plPL', 'Mam księgę, która może cię zainteresować. Chcesz rzucić okiem?', 'Mam księgę, która może cię zainteresować. Chcesz rzucić okiem?', 0),
(33040, 'plPL', 'Niesamowite! Są tu fragmenty, których nigdy wcześniej nie widziałem. Wytropienie tej księgi musiało ci zająć sporo czasu. Jeśli kiedyś znajdziesz więcej takich ksiąg, chcę się o tym dowiedzieć natychmiast.\nWeź, proszę, jednego z moich Chowańców Kirin Toru, na wypadek gdyby coś wpadło ci w ręce.', '', 0),
(33043, 'plPL', 'Dziękuję! Na pewno dam ci znać, jeśli znajdę coś jeszcze.', 'Dziękuję! Na pewno dam ci znać, jeśli znajdę coś jeszcze.', 0);
